/**
 * Opens the shared saved-searches dialog for a workspace context.
 * @param {string} context - Either "threadExplorer", "archive", or "search".
 * @returns {void}
 */
function openSavedSearchesDialog(context = "threadExplorer") {
  if (context === "archive") {
    savedSearchDialogContext = "archive";
  } else if (context === "search") {
    savedSearchDialogContext = "search";
  } else {
    savedSearchDialogContext = "threadExplorer";
  }
  if (savedSearchesNote) {
    if (savedSearchDialogContext === "search") {
      savedSearchesNote.textContent = t("savedSearchesSearchNote");
    } else {
      savedSearchesNote.textContent = t("savedSearchesNote");
    }
  }
  if (savedSearchUrlField) {
    savedSearchUrlField.hidden = savedSearchDialogContext === "search";
  }
  if (savedSearchesActions) {
    savedSearchesActions.hidden = savedSearchDialogContext === "search";
  }
  savedSearchUrlInput.value = "";
  renderSavedSearchesDialog();
  savedSearchesDialog.showModal();
}

/**
 * Creates a saved search entry from full Threadline search preferences.
 * @param {object} preferences - Search preferences to store.
 * @returns {object} Saved-search entry with Threadline-specific parameters.
 */
function createSavedSearchFromPreferences(preferences = {}) {
  const normalizedPreferences = normalizeSearchPreferencesForStorage(preferences);
  const urlResult = buildBskySearchUrlFromPayload(normalizedPreferences);
  const parsed = parseSavedSearchUrl(urlResult.url);
  const now = new Date().toISOString();
  return {
    id: `search-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
    sourceUrl: parsed.sourceUrl,
    params: parsed.params,
    searchPreferences: normalizedPreferences,
    label: buildSavedSearchLabelFromPreferences(normalizedPreferences),
    createdAt: now,
    updatedAt: now,
    lastLoadedAt: "",
  };
}

/**
 * Saves the current live search form for later reuse.
 * @returns {Promise<void>} Resolves after settings were persisted.
 */
async function saveCurrentSearchPreferences() {
  const preferences = normalizeSearchPreferencesForStorage(getSearchPreferences());
  const hasAnyValue = (
    Boolean(preferences.query)
    || Boolean(preferences.actor)
    || preferences.tags.length > 0
    || Boolean(preferences.excludeText)
    || Boolean(preferences.mentions)
    || preferences.langs.length > 0
    || Boolean(preferences.domain)
    || Boolean(preferences.url)
    || Boolean(preferences.since)
    || Boolean(preferences.until)
    || preferences.mode !== "network"
    || preferences.mediaFilter !== "all"
    || preferences.postTypeFilter !== "all"
  );
  if (!hasAnyValue) {
    if (searchStatus) {
      searchStatus.textContent = t("searchSaveEmptyWarning");
    }
    return;
  }

  const existing = savedSearches.find((search) => {
    return areSearchPreferencesEqual(search.searchPreferences || search.params || {}, preferences);
  });
  if (existing) {
    if (searchStatus) {
      searchStatus.textContent = t("searchSaveAlreadyExists");
    }
    return;
  }

  const entry = createSavedSearchFromPreferences(preferences);
  savedSearches = normalizeSavedSearches([entry, ...savedSearches]);
  await persistSettings();
  if (searchStatus) {
    searchStatus.textContent = t("searchSaveSuccess", {
      title: entry.label,
    });
  }
}

/**
 * Adds a shared Bluesky search URL to local saved searches.
 * @returns {Promise<void>} Resolves after settings are persisted.
 */
async function addSavedSearchFromInput() {
  const sourceUrl = String(savedSearchUrlInput.value || "").trim();
  const entry = createSavedSearchFromUrl(sourceUrl);
  const existing = savedSearches.find((search) => search.sourceUrl.toLowerCase() === entry.sourceUrl.toLowerCase());
  if (existing) {
    savedSearchesStatus.textContent = t("savedSearchAlreadyExists");
    return;
  }

  savedSearches = normalizeSavedSearches([entry, ...savedSearches]);
  savedSearchUrlInput.value = "";
  await persistSettings();
  renderSavedSearchesDialog();
}

/**
 * Removes a locally saved search.
 * @param {string} id - Saved search id.
 * @returns {Promise<void>} Resolves after settings are persisted.
 */
async function removeSavedSearch(id) {
  const normalizedId = String(id || "").trim();
  if (!normalizedId) {
    return;
  }
  savedSearches = savedSearches.filter((search) => search.id !== normalizedId);
  if (getThreadExplorerSearchIdFromSource(threadExplorerSource) === normalizedId) {
    threadExplorerSource = "follows";
    threadExplorerCursor = "";
    threadExplorerHasMore = true;
    threadExplorerItems = [];
    threadExplorerSelectedUri = "";
    threadExplorerTree = null;
    clearThreadExplorerRenderedMediaCache();
    clearThreadExplorerSelectionPreference();
  }
  if (archiveSavedSearchId === normalizedId) {
    archiveSavedSearchId = "";
    renderArchiveSavedSearchNote();
  }
  await persistSettings();
  renderSavedSearchesDialog();
  renderThreadExplorerWorkspace();
}

/**
 * Loads a saved search into the Thread Explorer result list.
 * @param {string} id - Saved search id.
 * @returns {Promise<void>} Resolves after the search source starts loading.
 */
async function loadSavedSearchInThreadExplorer(id) {
  const search = getSavedSearchById(id);
  if (!search) {
    return;
  }
  search.lastLoadedAt = new Date().toISOString();
  search.updatedAt = search.lastLoadedAt;
  await persistSettings();
  if (savedSearchesDialog.open) {
    savedSearchesDialog.close();
  }
  setThreadExplorerSource(`search:${search.id}`);
}

/**
 * Applies a saved search to the archive special tools area.
 * @param {string} id - Saved search id.
 * @returns {Promise<void>} Resolves after archive preferences are persisted.
 */
async function loadSavedSearchInArchive(id) {
  const search = getSavedSearchById(id);
  if (!search) {
    return;
  }
  search.lastLoadedAt = new Date().toISOString();
  search.updatedAt = search.lastLoadedAt;
  await persistSettings();
  if (savedSearchesDialog.open) {
    savedSearchesDialog.close();
  }
  archiveSavedSearchId = search.id;
  await persistArchivePreferences();
  archiveThreadUrlNote.textContent = t("archiveSavedSearchSelected", {
    label: search.label || buildSavedSearchLabel(search),
    url: search.sourceUrl,
  });
}

/**
 * Loads a saved search back into the live search workspace.
 * @param {string} id - Saved search id.
 * @returns {Promise<void>} Resolves after the search form was updated.
 */
async function loadSavedSearchInSearchWorkspace(id) {
  const search = getSavedSearchById(id);
  if (!search) {
    return;
  }
  search.lastLoadedAt = new Date().toISOString();
  search.updatedAt = search.lastLoadedAt;
  await persistSettings();
  if (savedSearchesDialog.open) {
    savedSearchesDialog.close();
  }
  applySearchPreferences(search.searchPreferences || search.params || {});
  searchResults = [];
  searchCursor = "";
  searchResultPreferences = null;
  renderHashtagCloud();
  renderSearchResults();
  renderSearchWorkspace();
  await persistSettings();
  if (searchStatus) {
    searchStatus.textContent = t("searchLoadSavedStatus", {
      title: search.label || buildSavedSearchLabel(search),
    });
  }
}

/**
 * Renders actors or quote authors into the Thread Explorer reactions dialog.
 * @param {Array<object>} actors - Actor entries from the Service Worker.
 * @returns {void}
 */
function renderThreadExplorerReactionActors(actors) {
  threadExplorerReactionsList.replaceChildren();
  if (!Array.isArray(actors) || actors.length === 0) {
    threadExplorerReactionsStatus.textContent = t("threadExplorerReactionsEmpty");
    return;
  }

  threadExplorerReactionsStatus.textContent = t("threadExplorerReactionsLoaded", {
    count: formatCount(actors.length),
  });
  actors.forEach((actor) => {
    const fragment = threadExplorerActorItemTemplate.content.cloneNode(true);
    const avatar = fragment.querySelector(".thread-explorer-avatar");
    const name = fragment.querySelector(".thread-explorer-actor-name");
    const handle = fragment.querySelector(".thread-explorer-actor-handle");
    setAvatarImage(avatar, actor.avatar, actor.displayName || actor.handle || actor.did || "account");
    name.textContent = actor.displayName || actor.handle || actor.did || t("threadExplorerUnknownAuthor");
    if (actor.handle) {
      handle.textContent = `@${actor.handle}`;
    } else {
      handle.textContent = actor.did || "";
    }
    threadExplorerReactionsList.appendChild(fragment);
  });
}

/**
 * Opens and loads the reactions dialog for a Thread Explorer post count.
 * @param {string} type - Reaction type: Likes, Reposts, or Quotes.
 * @param {string} uri - Post URI.
 * @param {string} cid - Optional post CID.
 * @returns {Promise<void>} Resolves after the dialog renders.
 */
async function openThreadExplorerReactionsDialog(type, uri, cid) {
  if (threadExplorerReactionsLoading) {
    return;
  }

  const normalizedType = String(type || "").trim();
  const normalizedUri = String(uri || "").trim();
  if (!normalizedType || !normalizedUri) {
    return;
  }

  threadExplorerReactionsLoading = true;
  threadExplorerReactionsTitle.textContent = t(`threadExplorer${normalizedType}Title`);
  threadExplorerReactionsStatus.textContent = t("threadExplorerReactionsLoading");
  threadExplorerReactionsList.replaceChildren();
  threadExplorerReactionsDialog.showModal();
  try {
    const result = await sendToServiceWorker("LOAD_THREAD_EXPLORER_REACTIONS", {
      type: normalizedType.toLowerCase(),
      uri: normalizedUri,
      cid: String(cid || "").trim(),
      limit: 100,
    }, {
      timeoutMs: 120000,
    });
    renderThreadExplorerReactionActors(result?.actors || []);
  } catch (error) {
    threadExplorerReactionsStatus.textContent = error.message || t("threadExplorerReactionsFailed");
  } finally {
    threadExplorerReactionsLoading = false;
  }
}

/**
 * Finds a normalized Thread Explorer tree node by post URI.
 * @param {object|null} node - Current normalized tree node.
 * @param {string} uri - AT URI to locate.
 * @returns {object|null} Matching tree node, or null.
 */
function findThreadExplorerTreeNode(node, uri) {
  const normalizedUri = String(uri || "").trim();
  if (!node || !normalizedUri) {
    return null;
  }

  if (node.post?.uri === normalizedUri) {
    return node;
  }

  if (!Array.isArray(node.replies)) {
    return null;
  }

  for (const reply of node.replies) {
    const found = findThreadExplorerTreeNode(reply, normalizedUri);
    if (found) {
      return found;
    }
  }

  return null;
}

/**
 * Finds the direct parent node for one normalized Thread Explorer post URI.
 * @param {object|null} node - Current normalized tree node.
 * @param {string} uri - AT URI to locate below the current node.
 * @returns {object|null} Direct parent node, or null when the URI is the root or missing.
 */
function findThreadExplorerParentNode(node, uri) {
  const normalizedUri = String(uri || "").trim();
  if (!node || !normalizedUri || !Array.isArray(node.replies)) {
    return null;
  }

  for (const reply of node.replies) {
    if (reply?.post?.uri === normalizedUri) {
      return node;
    }
    const found = findThreadExplorerParentNode(reply, normalizedUri);
    if (found) {
      return found;
    }
  }

  return null;
}

/**
 * Renders loaded replies for a Thread Explorer post into the replies dialog.
 * @param {object|null} node - Normalized tree node whose replies should be listed.
 * @returns {void}
 */
function renderThreadExplorerRepliesDialog(node) {
  threadExplorerRepliesList.replaceChildren();
  let replies = [];
  if (Array.isArray(node?.replies)) {
    replies = node.replies;
  }
  const expectedCount = Number(node?.post?.replyCount) || 0;
  threadExplorerRepliesTitle.textContent = t("threadExplorerRepliesTitle");

  if (!replies.length) {
    threadExplorerRepliesStatus.textContent = t("threadExplorerRepliesEmpty");
    return;
  }

  threadExplorerRepliesStatus.textContent = t("threadExplorerRepliesLoaded", {
    loaded: formatCount(replies.length),
    total: formatCount(expectedCount),
  });

  replies.forEach((reply) => {
    const post = reply.post || {};
    const actor = post.author || {};
    const fragment = threadExplorerActorItemTemplate.content.cloneNode(true);
    const item = fragment.querySelector(".thread-explorer-actor-item");
    const avatar = fragment.querySelector(".thread-explorer-avatar");
    const name = fragment.querySelector(".thread-explorer-actor-name");
    const handle = fragment.querySelector(".thread-explorer-actor-handle");

    item.dataset.uri = post.uri || "";
    item.tabIndex = 0;
    item.setAttribute("role", "button");
    setAvatarImage(avatar, actor.avatar, getThreadExplorerActorLabel(actor));
    name.textContent = getThreadExplorerActorLabel(actor);
    if (actor.handle) {
      handle.textContent = `@${actor.handle}`;
    } else {
      handle.textContent = actor.did || "";
    }
    item.addEventListener("click", () => {
      if (!post.uri) {
        return;
      }
      threadExplorerSelectedUri = post.uri;
      persistThreadExplorerSelectionPreference(post.uri);
      renderThreadExplorerWorkspace();
      window.requestAnimationFrame(focusSelectedThreadExplorerNode);
      threadExplorerRepliesDialog.close();
    });
    item.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") {
        return;
      }
      event.preventDefault();
      item.click();
    });
    threadExplorerRepliesList.appendChild(fragment);
  });
}

/**
 * Opens a popup with replies already loaded in the current Thread Explorer tree.
 * @param {string} uri - AT URI of the post whose replies should be shown.
 * @returns {void}
 */
function openThreadExplorerRepliesDialog(uri) {
  const node = findThreadExplorerTreeNode(threadExplorerTree, uri);
  renderThreadExplorerRepliesDialog(node);
  threadExplorerRepliesDialog.showModal();
}

/**
 * Normalizes a Thread Explorer image entry for gallery display.
 * @param {object} image - Raw normalized image object from a post.
 * @returns {object|null} Gallery image entry, or null when no URL exists.
 */
function normalizeThreadExplorerGalleryImage(image) {
  const fullsize = String(image?.fullsize || "").trim();
  const thumb = String(image?.thumb || "").trim();
  let src = "";
  if (fullsize) {
    src = fullsize;
  } else if (thumb) {
    src = thumb;
  }

  if (!src) {
    return null;
  }

  return {
    src,
    thumb: thumb || src,
    alt: String(image?.alt || "").trim(),
  };
}

/**
 * Updates the visible image and selected thumbnail in the Thread Explorer gallery.
 * @returns {void}
 */
function renderThreadExplorerGalleryImage() {
  const image = threadExplorerGalleryImages[threadExplorerGalleryIndex];
  if (!image) {
    return;
  }

  if (threadExplorerGalleryOverlayCloseButton) {
    threadExplorerGalleryOverlayCloseButton.textContent = "×";
  }
  if (threadExplorerGalleryOverlayPrevButton) {
    threadExplorerGalleryOverlayPrevButton.textContent = "‹";
  }
  if (threadExplorerGalleryOverlayNextButton) {
    threadExplorerGalleryOverlayNextButton.textContent = "›";
  }
  applyTranslatedTitle(threadExplorerGalleryOverlayCloseButton, "closeButton");
  applyTranslatedTitle(threadExplorerGalleryOverlayPrevButton, "threadExplorerGalleryPrevButton");
  applyTranslatedTitle(threadExplorerGalleryOverlayNextButton, "threadExplorerGalleryNextButton");
  applyTranslatedTitle(threadExplorerGalleryPrevButton, "threadExplorerGalleryPrevButton");
  applyTranslatedTitle(threadExplorerGalleryNextButton, "threadExplorerGalleryNextButton");

  threadExplorerGalleryImage.hidden = false;
  threadExplorerGalleryImage.dataset.fallbackAttempted = "false";
  threadExplorerGalleryImage.src = image.src;
  threadExplorerGalleryImage.alt = image.alt;
  threadExplorerGalleryImage.title = t("threadExplorerGalleryFullscreenHint");
  threadExplorerGalleryCaption.textContent = image.alt;
  threadExplorerGalleryCaption.hidden = !image.alt;
  threadExplorerGalleryTitle.textContent = t("threadExplorerGalleryTitle");
  threadExplorerGalleryThumbs.hidden = threadExplorerGalleryImages.length <= 1;

  if (threadExplorerGalleryPrevButton) {
    threadExplorerGalleryPrevButton.hidden = threadExplorerGalleryImages.length <= 1;
  }
  if (threadExplorerGalleryNextButton) {
    threadExplorerGalleryNextButton.hidden = threadExplorerGalleryImages.length <= 1;
  }
  if (threadExplorerGalleryOverlayPrevButton) {
    threadExplorerGalleryOverlayPrevButton.hidden = threadExplorerGalleryImages.length <= 1;
  }
  if (threadExplorerGalleryOverlayNextButton) {
    threadExplorerGalleryOverlayNextButton.hidden = threadExplorerGalleryImages.length <= 1;
  }

  const thumbs = threadExplorerGalleryThumbs.querySelectorAll(".thread-explorer-gallery-thumb");
  thumbs.forEach((thumb, index) => {
    let isSelected = false;
    if (index === threadExplorerGalleryIndex) {
      isSelected = true;
    }
    thumb.classList.toggle("is-selected", isSelected);
    if (isSelected) {
      thumb.setAttribute("aria-pressed", "true");
    } else {
      thumb.setAttribute("aria-pressed", "false");
    }
  });
}

/**
 * Hides a failed Thread Explorer post image and redraws tree edges.
 * @param {Event} event - Image error event from an inline post image.
 * @returns {void}
 */
function handleThreadExplorerPostImageError(event) {
  const image = event.currentTarget;
  const figure = image.closest(".thread-explorer-image");
  image.removeAttribute("src");
  if (figure) {
    figure.hidden = true;
  }
  refreshThreadExplorerRenderedGeometry();
}

/**
 * Hides a failed Thread Explorer quoted post image preview.
 * @param {Event} event - Image error event from a quoted post image.
 * @returns {void}
 */
function handleThreadExplorerQuoteImageError(event) {
  const image = event.currentTarget;
  image.removeAttribute("src");
  image.hidden = true;
  refreshThreadExplorerRenderedGeometry();
}

/**
 * Hides a failed Thread Explorer gallery thumbnail.
 * @param {Event} event - Image error event from a gallery thumbnail.
 * @returns {void}
 */
function handleThreadExplorerGalleryThumbError(event) {
  const image = event.currentTarget;
  const button = image.closest(".thread-explorer-gallery-thumb");
  image.removeAttribute("src");
  if (button) {
    button.hidden = true;
  }
}

/**
 * Falls back from fullsize to thumbnail in the Thread Explorer image gallery.
 * @param {Event} event - Image error event from the large gallery image.
 * @returns {void}
 */
function handleThreadExplorerGalleryImageError(event) {
  const imageElement = event.currentTarget;
  const image = threadExplorerGalleryImages[threadExplorerGalleryIndex];
  if (!image) {
    imageElement.hidden = true;
    return;
  }

  if (image.thumb && imageElement.dataset.fallbackAttempted !== "true") {
    imageElement.dataset.fallbackAttempted = "true";
    imageElement.src = image.thumb;
    return;
  }

  imageElement.hidden = true;
}

/**
 * Opens the Thread Explorer gallery at a selected image index.
 * @param {Array<object>} images - Post images to render.
 * @param {number} startIndex - Selected image index.
 * @returns {void}
 */
function openThreadExplorerGallery(images, startIndex) {
  const normalizedImages = [];
  if (Array.isArray(images)) {
    images.forEach((image) => {
      const normalizedImage = normalizeThreadExplorerGalleryImage(image);
      if (normalizedImage) {
        normalizedImages.push(normalizedImage);
      }
    });
  }

  if (!normalizedImages.length) {
    return;
  }

  threadExplorerGalleryImages = normalizedImages;
  threadExplorerGalleryIndex = Math.min(normalizedImages.length - 1, Math.max(0, Number(startIndex) || 0));
  threadExplorerGalleryThumbs.replaceChildren();

  normalizedImages.forEach((image, index) => {
    const fragment = threadExplorerGalleryThumbTemplate.content.cloneNode(true);
    const button = fragment.querySelector(".thread-explorer-gallery-thumb");
    const img = fragment.querySelector("img");
    img.src = image.thumb;
    img.alt = image.alt;
    img.addEventListener("error", handleThreadExplorerGalleryThumbError);
    button.dataset.index = String(index);
    button.addEventListener("click", () => {
      threadExplorerGalleryIndex = index;
      renderThreadExplorerGalleryImage();
    });
    threadExplorerGalleryThumbs.appendChild(fragment);
  });

  renderThreadExplorerGalleryImage();
  threadExplorerGalleryDialog.showModal();
}

/**
 * Handles left and right keyboard navigation while the Thread Explorer gallery is open.
 * @param {KeyboardEvent} event - Keyboard event emitted for the gallery dialog.
 * @returns {void}
 */
function handleThreadExplorerGalleryKeydown(event) {
  if (!threadExplorerGalleryDialog?.open) {
    return;
  }

  if (event.key === "Escape" && threadExplorerGalleryPseudoFullscreen) {
    event.preventDefault();
    setThreadExplorerGalleryPseudoFullscreen(false);
    return;
  }

  if (event.key === "ArrowLeft") {
    event.preventDefault();
    stepThreadExplorerGallery(-1);
    return;
  }

  if (event.key === "ArrowRight") {
    event.preventDefault();
    stepThreadExplorerGallery(1);
  }
}

/**
 * Opens the current Thread Explorer gallery image through the Fullscreen API.
 * @returns {Promise<void>} Resolves after the fullscreen request is attempted.
 */
async function openThreadExplorerGalleryFullscreen() {
  const fullscreenTarget = threadExplorerGalleryMain || threadExplorerGalleryImage;
  if (!fullscreenTarget) {
    return;
  }

  if (isIosDevice()) {
    setThreadExplorerGalleryPseudoFullscreen(true);
    return;
  }

  if (fullscreenTarget.requestFullscreen) {
    try {
      await fullscreenTarget.requestFullscreen();
      setThreadExplorerGalleryPseudoFullscreen(false);
      return;
    } catch {
      // Fall back to the in-app fullscreen mode below.
    }
  }

  setThreadExplorerGalleryPseudoFullscreen(true);
}

/**
 * Closes Thread Explorer gallery fullscreen first, then falls back to closing the dialog.
 * @returns {Promise<void>} Resolves after fullscreen or dialog close was attempted.
 */
async function closeThreadExplorerGalleryOverlay() {
  if (document.fullscreenElement) {
    try {
      await document.exitFullscreen();
      return;
    } catch {
      // Fall through to closing the dialog when fullscreen exit fails.
    }
  }

  if (threadExplorerGalleryPseudoFullscreen) {
    setThreadExplorerGalleryPseudoFullscreen(false);
    return;
  }

  threadExplorerGalleryDialog?.close();
}

/**
 * Toggles the Thread Explorer in-app fullscreen fallback for browsers without element fullscreen.
 * @param {boolean} enabled - True when the gallery image should cover the full viewport.
 * @returns {void}
 */
function setThreadExplorerGalleryPseudoFullscreen(enabled) {
  threadExplorerGalleryPseudoFullscreen = enabled === true;
  if (threadExplorerGalleryMain) {
    threadExplorerGalleryMain.classList.toggle("is-inline-fullscreen", threadExplorerGalleryPseudoFullscreen);
  }
  document.body.classList.toggle("thread-explorer-gallery-fullscreen", threadExplorerGalleryPseudoFullscreen);
}

/**
 * Computes an engagement score for one Thread Explorer post.
 * @param {object} post - Normalized Thread Explorer post.
 * @returns {number} Weighted score from likes, replies, reposts, and quotes.
 */
function getThreadExplorerEngagementScore(post) {
  const likes = Number(post?.likeCount) || 0;
  const replies = Number(post?.replyCount) || 0;
  const reposts = Number(post?.repostCount) || 0;
  const quotes = Number(post?.quoteCount) || 0;
  return likes + (replies * 3) + (reposts * 4) + (quotes * 4);
}

/**
 * Converts an engagement score into a visual intensity tier.
 * @param {number} score - Weighted post engagement score.
 * @returns {string} Engagement tier name for CSS classes.
 */
function getThreadExplorerEngagementTier(score) {
  const numericScore = Number(score) || 0;
  if (numericScore >= 1000) {
    return "viral";
  }
  if (numericScore >= 180) {
    return "hot";
  }
  if (numericScore >= 40) {
    return "warm";
  }
  return "quiet";
}

/**
 * Returns direct rendered child node items for a Thread Explorer item.
 * @param {HTMLElement} item - Rendered Thread Explorer node item.
 * @returns {HTMLElement[]} Direct child node items.
 */
function getRenderedThreadExplorerChildItems(item) {
  const childrenList = item.querySelector(":scope > .thread-explorer-children");
  if (!childrenList) {
    return [];
  }
  return Array.from(childrenList.children).filter((child) => child.classList.contains("thread-explorer-node-item"));
}

/**
 * Returns the visible post card for a rendered Thread Explorer item.
 * @param {HTMLElement} item - Rendered Thread Explorer node item.
 * @returns {HTMLElement|null} Direct post card element, or null.
 */
function getRenderedThreadExplorerCard(item) {
  return item.querySelector(":scope > .thread-explorer-node > .thread-explorer-post-card");
}

/**
 * Returns an element rectangle in unzoomed Thread Explorer stage coordinates.
 * @param {HTMLElement} element - Element to measure.
 * @param {DOMRect} stageRect - Stage viewport rectangle.
 * @returns {object} Rectangle with position and center values.
 */
function getThreadExplorerStageRect(element, stageRect) {
  const elementRect = element.getBoundingClientRect();
  let zoom = Number(threadExplorerZoom) || 1;
  if (zoom <= 0) {
    zoom = 1;
  }

  const left = (elementRect.left - stageRect.left) / zoom;
  const top = (elementRect.top - stageRect.top) / zoom;
  const width = elementRect.width / zoom;
  const height = elementRect.height / zoom;
  const right = left + width;
  const bottom = top + height;
  const centerX = left + (width / 2);
  const centerY = top + (height / 2);
  return {
    left,
    top,
    width,
    height,
    right,
    bottom,
    centerX,
    centerY,
  };
}

/**
 * Builds a curved SVG path between two rendered Thread Explorer cards.
 * @param {object} parentRect - Parent card rectangle in stage coordinates.
 * @param {object} childRect - Child card rectangle in stage coordinates.
 * @returns {string} SVG path data.
 */
function createThreadExplorerEdgePath(parentRect, childRect) {
  if (threadExplorerOrientation === THREAD_EXPLORER_ORIENTATION_HORIZONTAL) {
    const startX = parentRect.right;
    const startY = parentRect.centerY;
    const endX = childRect.left;
    const endY = childRect.centerY;
    const distance = Math.max(72, Math.abs(endX - startX));
    const controlOffset = Math.max(48, distance * 0.42);
    return `M ${startX} ${startY} C ${startX + controlOffset} ${startY}, ${endX - controlOffset} ${endY}, ${endX} ${endY}`;
  }

  const startX = parentRect.centerX;
  const startY = parentRect.bottom;
  const endX = childRect.centerX;
  const endY = childRect.top;
  const distance = Math.max(60, Math.abs(endY - startY));
  const controlOffset = Math.max(36, distance * 0.45);
  return `M ${startX} ${startY} C ${startX} ${startY + controlOffset}, ${endX} ${endY - controlOffset}, ${endX} ${endY}`;
}

/**
 * Schedules a redraw of Thread Explorer SVG edges after layout settles.
 * @returns {void}
 */
function scheduleThreadExplorerEdgeRender() {
  if (isThreadExplorerReplyClusterModeActive()) {
    return;
  }
  if (threadExplorerDragState?.started === true) {
    return;
  }
  if (threadExplorerPanInertiaFrame) {
    return;
  }
  if (threadExplorerEdgeRenderFrame) {
    window.cancelAnimationFrame(threadExplorerEdgeRenderFrame);
  }
  threadExplorerEdgeRenderFrame = window.requestAnimationFrame(() => {
    threadExplorerEdgeRenderFrame = 0;
    renderThreadExplorerEdges();
  });
}

/**
 * Removes the current Thread Explorer SVG edge layer.
 * @returns {void}
 */
function clearThreadExplorerEdges() {
  const existingLayer = threadExplorerThreadStage.querySelector(":scope > .thread-explorer-edge-layer");
  if (existingLayer) {
    existingLayer.remove();
  }
}

/**
 * Enables or disables the lightweight panning mode for the Thread Explorer.
 * @param {boolean} active - Whether the viewport is currently being panned.
 * @returns {void}
 */
function setThreadExplorerPanningMode(active) {
  const isActive = active === true;
  threadExplorerThreadTree.classList.toggle("is-dragging", isActive);
  threadExplorerThreadStage.classList.toggle("is-panning", isActive);
  if (!isActive) {
    threadExplorerThreadTree.classList.remove("is-pan-armed");
  }
}

/**
 * Stops any running inertial panning animation in the Thread Explorer.
 * @returns {void}
 */
function cancelThreadExplorerPanInertia() {
  if (threadExplorerPanInertiaFrame) {
    window.cancelAnimationFrame(threadExplorerPanInertiaFrame);
    threadExplorerPanInertiaFrame = 0;
  }
  threadExplorerPanVelocityX = 0;
  threadExplorerPanVelocityY = 0;
  if (!threadExplorerDragState) {
    setThreadExplorerPanningMode(false);
  }
}

/**
 * Applies one scroll delta to the Thread Explorer viewport.
 * @param {number} deltaX - Horizontal movement delta in CSS pixels.
 * @param {number} deltaY - Vertical movement delta in CSS pixels.
 * @returns {void}
 */
function applyThreadExplorerScrollDelta(deltaX, deltaY) {
  if (!threadExplorerThreadTree) {
    return;
  }
  threadExplorerPanX += deltaX;
  threadExplorerPanY += deltaY;
  applyThreadExplorerStageTransform();
}

/**
 * Updates the recent pan velocity sample for inertial Thread Explorer panning.
 * @param {object} state - Active drag state.
 * @param {PointerEvent} event - Current pointer move event.
 * @returns {void}
 */
function updateThreadExplorerPanVelocity(state, event) {
  if (!state) {
    return;
  }

  const lastSampleTime = Number(state.lastSampleTime) || 0;
  const elapsedMs = Math.max(1, event.timeStamp - lastSampleTime);
  const moveX = event.clientX - state.lastSampleX;
  const moveY = event.clientY - state.lastSampleY;

  state.velocityX = moveX / elapsedMs;
  state.velocityY = moveY / elapsedMs;
  state.lastSampleX = event.clientX;
  state.lastSampleY = event.clientY;
  state.lastSampleTime = event.timeStamp;
}

/**
 * Starts inertial panning after the pointer was released from the Thread Explorer.
 * @returns {void}
 */
function startThreadExplorerPanInertia() {
  cancelThreadExplorerPanInertia();

  const velocityMagnitude = Math.max(Math.abs(threadExplorerPanVelocityX), Math.abs(threadExplorerPanVelocityY));
  if (velocityMagnitude < THREAD_EXPLORER_INERTIA_MIN_VELOCITY) {
    setThreadExplorerPanningMode(false);
    scheduleThreadExplorerEdgeRender();
    return;
  }

  let previousTime = performance.now();
  setThreadExplorerPanningMode(true);

  /**
   * Advances one frame of inertial Thread Explorer panning.
   * @param {number} now - Current animation frame timestamp.
   * @returns {void}
   */
  function step(now) {
    const elapsedMs = Math.max(1, now - previousTime);
    previousTime = now;

    const moveX = threadExplorerPanVelocityX * elapsedMs;
    const moveY = threadExplorerPanVelocityY * elapsedMs;
    applyThreadExplorerScrollDelta(moveX, moveY);

    const frameFriction = Math.pow(THREAD_EXPLORER_INERTIA_FRICTION, elapsedMs / 16.67);
    threadExplorerPanVelocityX *= frameFriction;
    threadExplorerPanVelocityY *= frameFriction;

    const nextMagnitude = Math.max(Math.abs(threadExplorerPanVelocityX), Math.abs(threadExplorerPanVelocityY));
    if (nextMagnitude <= THREAD_EXPLORER_INERTIA_STOP_VELOCITY) {
      threadExplorerPanInertiaFrame = 0;
      threadExplorerPanVelocityX = 0;
      threadExplorerPanVelocityY = 0;
      setThreadExplorerPanningMode(false);
      scheduleThreadExplorerEdgeRender();
      return;
    }

    threadExplorerPanInertiaFrame = window.requestAnimationFrame(step);
  }

  threadExplorerPanInertiaFrame = window.requestAnimationFrame(step);
}

/**
 * Renders curved SVG edges between visible Thread Explorer parent and child cards.
 * @returns {void}
 */
function renderThreadExplorerEdges() {
  clearThreadExplorerEdges();
  if (!threadExplorerTree) {
    threadExplorerThreadStage.classList.remove("has-svg-edges");
    return;
  }
  if (isThreadExplorerReplyClusterModeActive()) {
    threadExplorerThreadStage.classList.remove("has-svg-edges");
    return;
  }

  const stageRect = threadExplorerThreadStage.getBoundingClientRect();
  const rootItem = threadExplorerThreadStage.querySelector(":scope > ul > .thread-explorer-node-item");
  if (!rootItem) {
    threadExplorerThreadStage.classList.remove("has-svg-edges");
    return;
  }

  const stageWidth = Math.max(threadExplorerThreadStage.scrollWidth, threadExplorerThreadStage.offsetWidth);
  const stageHeight = Math.max(threadExplorerThreadStage.scrollHeight, threadExplorerThreadStage.offsetHeight);
  const svg = createSvgNode("svg", {
    class: "thread-explorer-edge-layer",
    width: stageWidth,
    height: stageHeight,
    viewBox: `0 0 ${stageWidth} ${stageHeight}`,
    "aria-hidden": "true",
    focusable: "false",
  });

  /**
   * Walks rendered Thread Explorer nodes and draws edges to direct children.
   * @param {HTMLElement} item - Current rendered node item.
   * @returns {void}
   */
  function visitRenderedThreadExplorerItem(item) {
    if (item.classList.contains("is-collapsed")) {
      return;
    }

    const parentCard = getRenderedThreadExplorerCard(item);
    if (!parentCard) {
      return;
    }

    const parentRect = getThreadExplorerStageRect(parentCard, stageRect);
    const childItems = getRenderedThreadExplorerChildItems(item);
    childItems.forEach((childItem) => {
      const childCard = getRenderedThreadExplorerCard(childItem);
      if (!childCard) {
        return;
      }

      const childRect = getThreadExplorerStageRect(childCard, stageRect);
      const tier = childItem.dataset.engagementTier || "quiet";
      const path = createSvgNode("path", {
        class: `thread-explorer-edge thread-explorer-edge-${tier}`,
        d: createThreadExplorerEdgePath(parentRect, childRect),
      });
      svg.appendChild(path);
      visitRenderedThreadExplorerItem(childItem);
    });
  }

  visitRenderedThreadExplorerItem(rootItem);
  threadExplorerThreadStage.prepend(svg);
  threadExplorerThreadStage.classList.add("has-svg-edges");
}

/**
 * Sets the active Thread Explorer source and refreshes the feed.
 * @param {string} source - Either "follows" or "mutuals".
 * @returns {void}
 */
function setThreadExplorerSource(source) {
  threadExplorerSource = normalizeThreadExplorerSource(source);
  threadExplorerCursor = "";
  threadExplorerHasMore = true;
  threadExplorerItems = [];
  threadExplorerSelectedUri = "";
  threadExplorerTree = null;
  clearThreadExplorerRenderedMediaCache();
  threadExplorerFeedError = "";
  threadExplorerThreadError = "";
  clearThreadExplorerSelectionPreference();
  renderThreadExplorerWorkspace();
  void loadThreadExplorerFeed({ reset: true });
}

/**
 * Renders the pinned-feed dropdown options for the Thread Explorer.
 * @returns {void}
 */
function renderThreadExplorerFeedSourceSelect() {
  if (!threadExplorerFeedSelect) {
    return;
  }

  const placeholder = threadExplorerFeedOptionTemplate.content.cloneNode(true);
  const placeholderOption = placeholder.querySelector("option");
  placeholderOption.value = "";
  placeholderOption.textContent = t("threadExplorerFeedPickerPlaceholder");
  threadExplorerFeedSelect.replaceChildren(placeholderOption);

  threadExplorerFeedSources.forEach((feed) => {
    const source = buildThreadExplorerFeedSource(feed.uri);
    if (!source) {
      return;
    }
    const fragment = threadExplorerFeedOptionTemplate.content.cloneNode(true);
    const option = fragment.querySelector("option");
    option.value = source;
    option.textContent = feed.displayName || feed.uri;
    threadExplorerFeedSelect.appendChild(option);
  });

  const activeFeedSource = getThreadExplorerFeedUriFromSource(threadExplorerSource) ? normalizeThreadExplorerSource(threadExplorerSource) : "";
  threadExplorerFeedSelect.value = activeFeedSource;
  threadExplorerFeedSelect.disabled = !authAccount || threadExplorerFeedSourcesLoading || isThreadExplorerForeignAccountMode();
}

/**
 * Resolves which Thread Explorer post should be opened after a feed load.
 * @param {object} options - Selection behavior flags.
 * @param {boolean} options.allowStoredOutsideFeed - Whether a saved URI may be opened even if it is not in the feed slice.
 * @returns {string} Current, stored, first feed, or empty selected URI.
 */
function getThreadExplorerPreferredSelectionUri(options = {}) {
  const allowStoredOutsideFeed = options.allowStoredOutsideFeed === true;
  const currentUri = String(threadExplorerSelectedUri || "").trim();
  if (currentUri && (allowStoredOutsideFeed || threadExplorerFeedContainsUri(currentUri))) {
    return currentUri;
  }

  const storedSelection = getStoredThreadExplorerSelectionPreference();
  if (storedSelection?.selectedUri && (allowStoredOutsideFeed || threadExplorerFeedContainsUri(storedSelection.selectedUri))) {
    return storedSelection.selectedUri;
  }

  const firstItem = threadExplorerItems[0];
  const firstUri = String(firstItem?.post?.uri || "").trim();
  if (firstUri) {
    return firstUri;
  }

  return "";
}

/**
 * Checks whether a post URI exists in the currently loaded Thread Explorer feed.
 * @param {string} uri - AT URI to look for.
 * @returns {boolean} True when the URI is present in the current feed items.
 */
function threadExplorerFeedContainsUri(uri) {
  const normalizedUri = String(uri || "").trim();
  if (!normalizedUri) {
    return false;
  }

  return threadExplorerItems.some((item) => String(item?.post?.uri || "").trim() === normalizedUri);
}

/**
 * Returns the best avatar URL for a Thread Explorer actor.
 * @param {object} actor - Normalized Thread Explorer actor.
 * @returns {string} Cached data URI, remote avatar URL, or an empty string.
 */
function getThreadExplorerActorAvatarUri(actor = {}) {
  const cachedAvatar = String(actor?.avatarDataUri || "").trim();
  if (cachedAvatar) {
    return cachedAvatar;
  }
  return String(actor?.avatar || "").trim();
}

/**
 * Finds a cached avatar asset for a Thread Explorer actor.
 * @param {object} actor - Normalized Thread Explorer actor.
 * @returns {object|null} Cached avatar asset or null.
 */
function findThreadExplorerActorAvatarAsset(actor = {}) {
  const did = String(actor?.did || "").trim();
  const avatarUrl = String(actor?.avatar || "").trim();
  if (!did || !avatarUrl) {
    return null;
  }

  let assets = [];
  if (Array.isArray(accountAvatarAssets)) {
    assets = accountAvatarAssets;
  }
  const asset = assets.find((entry) => entry.did === did && entry.url === avatarUrl);
  if (!asset) {
    return null;
  }
  return asset;
}

/**
 * Applies cached avatar data from the local avatar cache to one actor.
 * @param {object|null} actor - Normalized Thread Explorer actor.
 * @returns {void}
 */
function applyThreadExplorerActorAvatarFromCache(actor = null) {
  if (!actor || typeof actor !== "object") {
    return;
  }

  const asset = findThreadExplorerActorAvatarAsset(actor);
  if (asset) {
    actor.avatarDataUri = assetToDataUri(asset);
  }
}

/**
 * Adds cache lookup metadata to a Thread Explorer avatar image.
 * @param {HTMLImageElement|null} image - Avatar image element.
 * @param {object} actor - Normalized Thread Explorer actor.
 * @returns {void}
 */
function markThreadExplorerAvatarImage(image, actor = {}) {
  if (!image) {
    return;
  }

  image.dataset.avatarDid = String(actor?.did || "").trim();
  image.dataset.avatarUrl = String(actor?.avatar || "").trim();
}

/**
 * Applies cached avatar data URIs to matching authors in the Thread Explorer tree.
 * @param {object|null} node - Thread Explorer tree node.
 * @param {object} avatars - Map-like object keyed by actor DID.
 * @returns {void}
 */
function applyThreadExplorerAvatarHydration(node = null, avatars = {}) {
  if (!node || typeof node !== "object") {
    return;
  }

  const author = node.post?.author || null;
  if (author?.did && avatars[author.did]?.dataUri) {
    author.avatarDataUri = avatars[author.did].dataUri;
  }

  const quoteAuthor = node.post?.quoteCard?.author || null;
  if (quoteAuthor?.did && avatars[quoteAuthor.did]?.dataUri) {
    quoteAuthor.avatarDataUri = avatars[quoteAuthor.did].dataUri;
  }

  if (Array.isArray(node.replies)) {
    node.replies.forEach((reply) => {
      applyThreadExplorerAvatarHydration(reply, avatars);
    });
  }
}

/**
 * Applies cached avatar data URIs from the local cache to a Thread Explorer tree.
 * @param {object|null} node - Thread Explorer tree node.
 * @returns {void}
 */
function applyThreadExplorerAvatarCacheToTree(node = null) {
  if (!node || typeof node !== "object") {
    return;
  }

  applyThreadExplorerActorAvatarFromCache(node.post?.author || null);
  applyThreadExplorerActorAvatarFromCache(node.post?.quoteCard?.author || null);

  if (Array.isArray(node.replies)) {
    node.replies.forEach((reply) => {
      applyThreadExplorerAvatarCacheToTree(reply);
    });
  }
}

/**
 * Hydrates avatars for the currently loaded Thread Explorer tree through the service worker cache.
 * @param {object|null} root - Thread Explorer root node.
 * @param {(progress: {percent?: number, step?: string, detail?: string}) => Promise<void>} onProgress - Progress reporter.
 * @param {AbortSignal|null} signal - Abort signal for the current export.
 * @returns {Promise<void>} Resolves after cached avatar data URIs were applied.
 */
async function hydrateThreadExplorerTreeAvatars(root = null, onProgress = async () => {}, signal = null) {
  if (!root) {
    return;
  }
  throwIfThreadExplorerSnapshotAborted(signal);

  const result = await sendToServiceWorker("HYDRATE_THREAD_EXPLORER_AVATARS", {
    root,
  }, {
    timeoutMs: 120000,
    signal,
    onProgress(progress) {
      if (progress?.phase !== "thread_explorer_avatars") {
        return;
      }

      const total = Math.max(0, Number(progress.total) || 0);
      const current = Math.max(0, Number(progress.current) || 0);
      const remaining = Math.max(0, Number(progress.remaining) || 0);
      let percent = 5;
      if (total > 0) {
        percent = 5 + (current / total * 12);
      }
      void onProgress({
        percent,
        step: t("threadExplorerSnapshotProgressAvatars"),
        detail: t("threadExplorerSnapshotProgressAvatarDetail", {
          current,
          total,
          remaining,
          hydrated: Number(progress.hydrated) || 0,
          skipped: Number(progress.skipped) || 0,
        }),
      });
    },
  }).catch((error) => {
    if (error?.name === "AbortError") {
      throw error;
    }
    console.warn("Thread Explorer avatar hydration failed.", error);
    return null;
  });

  if (result?.avatars && typeof result.avatars === "object") {
    applyThreadExplorerAvatarHydration(root, result.avatars);
  }
}

/**
 * Hydrates remote media images for the current Thread Explorer snapshot.
 * @param {object|null} root - Thread Explorer root node.
 * @param {(progress: {percent?: number, step?: string, detail?: string}) => Promise<void>} onProgress - Progress reporter.
 * @param {AbortSignal|null} signal - Abort signal for the current export.
 * @returns {Promise<void>} Resolves after media data URIs were prepared.
 */
async function hydrateThreadExplorerSnapshotMedia(root = null, onProgress = async () => {}, signal = null) {
  threadExplorerSnapshotMediaDataUris = new Map();
  if (!root) {
    return;
  }
  throwIfThreadExplorerSnapshotAborted(signal);

  const result = await sendToServiceWorker("HYDRATE_THREAD_EXPLORER_MEDIA", {
    root,
  }, {
    timeoutMs: 420000,
    signal,
    onProgress(progress) {
      if (progress?.phase !== "thread_explorer_media") {
        return;
      }

      const total = Math.max(0, Number(progress.total) || 0);
      const current = Math.max(0, Number(progress.current) || 0);
      const remaining = Math.max(0, Number(progress.remaining) || 0);
      let percent = 18;
      if (total > 0) {
        percent = 18 + (current / total * 9);
      }
      void onProgress({
        percent,
        step: t("threadExplorerSnapshotProgressMedia"),
        detail: t("threadExplorerSnapshotProgressMediaDownloadDetail", {
          current,
          total,
          remaining,
          hydrated: Number(progress.hydrated) || 0,
          skipped: Number(progress.skipped) || 0,
          cacheHits: Number(progress.cacheHits) || 0,
          downloaded: Number(progress.downloaded) || 0,
          concurrency: Number(progress.concurrency) || 0,
        }),
      });
    },
  }).catch((error) => {
    if (error?.name === "AbortError") {
      throw error;
    }
    console.warn("Thread Explorer media hydration failed.", error);
    return null;
  });

  if (!result?.media || typeof result.media !== "object") {
    return;
  }

  storeThreadExplorerHydratedMedia(result.media);
}

/**
 * Stores media returned by the Service Worker in the shared Thread Explorer media cache.
 * @param {object|null} media - Map-like object from original media URL to data URI.
 * @returns {number} Number of cached media entries.
 */
function storeThreadExplorerHydratedMedia(media = null) {
  if (!media || typeof media !== "object") {
    return 0;
  }

  let storedCount = 0;
  Object.entries(media).forEach(([source, dataUri]) => {
    const key = String(source || "").trim();
    const value = String(dataUri || "").trim();
    if (!key || !value) {
      return;
    }

    threadExplorerSnapshotMediaDataUris.set(key, value);
    storeThreadExplorerRenderedMediaDataUri([key], value);
    storedCount += 1;
  });
  return storedCount;
}

/**
 * Preloads all media for the currently selected Thread Explorer thread without delaying rendering.
 * @param {object|null} root - Current Thread Explorer root node.
 * @param {number} generation - Cache generation that must still be current when the request finishes.
 * @returns {Promise<void>} Resolves after the best-effort prewarm finished.
 */
async function prewarmThreadExplorerMediaCacheForCurrentThread(root = null, generation = 0) {
  if (!root) {
    return;
  }

  if (threadExplorerMediaCachePrewarmController) {
    threadExplorerMediaCachePrewarmController.abort();
  }
  const controller = new AbortController();
  threadExplorerMediaCachePrewarmController = controller;

  const result = await sendToServiceWorker("HYDRATE_THREAD_EXPLORER_MEDIA", {
    root,
  }, {
    timeoutMs: 420000,
    signal: controller.signal,
  }).catch((error) => {
    if (error?.name === "AbortError") {
      return null;
    }
    console.warn("Thread Explorer media cache prewarm failed.", error);
    return null;
  });

  if (threadExplorerMediaCachePrewarmController === controller) {
    threadExplorerMediaCachePrewarmController = null;
  }
  if (controller.signal.aborted) {
    return;
  }
  if (generation !== threadExplorerMediaCacheGeneration) {
    return;
  }
  if (root !== threadExplorerTree) {
    return;
  }
  if (!result?.media || typeof result.media !== "object") {
    return;
  }

  storeThreadExplorerHydratedMedia(result.media);
  applyThreadExplorerRenderedMediaCacheToDom();
}

/**
 * Appends newly loaded feed items while preserving the first occurrence of each post URI.
 * @param {Array<object>} currentItems - Feed items already rendered.
 * @param {Array<object>} nextItems - Feed items returned by the newest page.
 * @param {object} options - Append options.
 * @param {boolean} options.groupByRoot - Whether duplicates should be detected by root URI.
 * @returns {Array<object>} Combined feed items without duplicate post URIs.
 */
function appendThreadExplorerFeedItems(currentItems, nextItems, options = {}) {
  const seen = new Set();
  const combined = [];
  const items = [];
  if (Array.isArray(currentItems)) {
    items.push(...currentItems);
  }
  if (Array.isArray(nextItems)) {
    items.push(...nextItems);
  }
  items.forEach((item) => {
    let uri = String(item?.post?.uri || "").trim();
    if (options.groupByRoot === true) {
      uri = String(item?.post?.rootUri || item?.post?.uri || "").trim();
    }
    if (!uri || seen.has(uri)) {
      return;
    }
    seen.add(uri);
    combined.push(item);
  });
  return combined;
}

/**
 * Returns the timestamp used to sort Thread Explorer feed items.
 * @param {object} item - Thread Explorer feed item.
 * @returns {number} Epoch milliseconds or zero.
 */
function getThreadExplorerFeedItemSortTimestamp(item = {}) {
  const createdAt = Date.parse(String(item?.post?.createdAt || "").trim());
  if (Number.isFinite(createdAt)) {
    return createdAt;
  }

  const indexedAt = Date.parse(String(item?.post?.indexedAt || "").trim());
  if (Number.isFinite(indexedAt)) {
    return indexedAt;
  }

  return 0;
}

/**
 * Sorts Thread Explorer feed items by post date, newest first.
 * @param {Array<object>} items - Feed items to sort.
 * @returns {Array<object>} Sorted feed items without mutating the input.
 */
function sortThreadExplorerFeedItemsByDate(items = []) {
  if (!Array.isArray(items)) {
    return [];
  }

  return items
    .map((item, index) => {
      return {
        item,
        index,
      };
    })
    .sort((left, right) => {
      const leftTime = getThreadExplorerFeedItemSortTimestamp(left.item);
      const rightTime = getThreadExplorerFeedItemSortTimestamp(right.item);
      if (leftTime !== rightTime) {
        return rightTime - leftTime;
      }
      return left.index - right.index;
    })
    .map((entry) => {
      return entry.item;
    });
}

/**
 * Returns whether any modal dialog is currently open.
 * @returns {boolean} True when at least one dialog element is open.
 */
function hasOpenDialog() {
  return Boolean(document.querySelector("dialog[open]"));
}

/**
 * Enables or disables the Thread Explorer fullscreen reading mode.
 * @param {boolean} nextFullscreen - Desired fullscreen state.
 * @returns {void}
 */
function setThreadExplorerFullscreen(nextFullscreen) {
  const isFullscreen = nextFullscreen === true;
  if (threadExplorerFullscreen === isFullscreen) {
    return;
  }
  threadExplorerFullscreen = isFullscreen;
  applyThreadExplorerFullscreenState();
  updateThreadExplorerControls();
  scheduleThreadExplorerEdgeRender();
}

/**
 * Toggles the Thread Explorer fullscreen reading mode.
 * @returns {void}
 */
function toggleThreadExplorerFullscreen() {
  if (threadExplorerFullscreen === true) {
    setThreadExplorerFullscreen(false);
    return;
  }
  setThreadExplorerFullscreen(true);
}

/**
 * Updates Thread Explorer toolbar controls and status text.
 * @returns {void}
 */
function updateThreadExplorerControls() {
  const hasAuth = Boolean(authAccount);
  const isForeignAccountMode = isThreadExplorerForeignAccountMode();
  const isForeignActorFocusMode = isThreadExplorerForeignActorFocusMode();
  threadExplorerUrlButton.disabled = !hasAuth || threadExplorerLoadingThread;
  threadExplorerSearchesButton.disabled = !hasAuth;
  if (archiveSavedSearchesButton) {
    archiveSavedSearchesButton.disabled = !hasAuth;
  }
  threadExplorerRefreshButton.disabled = !hasAuth || threadExplorerLoadingFeed;
  if (threadExplorerAccountInput) {
    threadExplorerAccountInput.disabled = !hasAuth || threadExplorerLoadingFeed;
    if (!threadExplorerAccountInput.matches(":focus")) {
      threadExplorerAccountInput.value = normalizeThreadExplorerActor(threadExplorerAccountActor);
    }
  }
  if (threadExplorerUseOwnAccountButton) {
    threadExplorerUseOwnAccountButton.disabled = !hasAuth || threadExplorerLoadingFeed;
  }
  if (threadExplorerSourceField) {
    threadExplorerSourceField.hidden = isForeignActorFocusMode;
  }
  if (threadExplorerAccountField) {
    threadExplorerAccountField.hidden = isForeignActorFocusMode;
  }
  if (threadExplorerAccountModeField) {
    threadExplorerAccountModeField.hidden = !isForeignAccountMode || isForeignActorFocusMode;
  }
  if (threadExplorerAccountModeSelect) {
    threadExplorerAccountModeSelect.value = normalizeThreadExplorerAccountMode(threadExplorerAccountMode);
    threadExplorerAccountModeSelect.disabled = !hasAuth || threadExplorerLoadingFeed || !isForeignAccountMode;
  }
  if (threadExplorerFeedPickerField) {
    threadExplorerFeedPickerField.hidden = isForeignAccountMode || isForeignActorFocusMode;
  }
  if (threadExplorerFeedStatus) {
    threadExplorerFeedStatus.hidden = isForeignActorFocusMode;
  }
  if (threadExplorerFeedList) {
    threadExplorerFeedList.hidden = isForeignActorFocusMode;
  }
  threadExplorerRootButton.disabled = !threadExplorerTree;
  threadExplorerReloadThreadButton.disabled = !hasAuth || !threadExplorerSelectedUri || threadExplorerLoadingThread;
  threadExplorerSnapshotPngButton.disabled = !threadExplorerTree || threadExplorerLoadingThread;
  threadExplorerSaveButton.disabled = !threadExplorerTree;
  threadExplorerFavoritesButton.disabled = !hasAuth;
  threadExplorerZoomOutButton.disabled = !threadExplorerTree;
  threadExplorerZoomResetButton.disabled = !threadExplorerTree;
  threadExplorerZoomInButton.disabled = !threadExplorerTree;
  threadExplorerZoomResetButton.title = t("threadExplorerFitThreadButton");
  threadExplorerZoomResetButton.setAttribute("aria-label", t("threadExplorerFitThreadButton"));
  threadExplorerViewModeButton.disabled = !threadExplorerTree;
  threadExplorerOrientationButton.disabled = !hasAuth || isThreadExplorerReplyClusterModeActive();
  threadExplorerFullscreenButton.disabled = !hasAuth;
  threadExplorerCollapseButton.disabled = !threadExplorerTree || isThreadExplorerReplyClusterModeActive();
  threadExplorerExpandButton.disabled = !threadExplorerTree || isThreadExplorerReplyClusterModeActive();
  if (threadExplorerFullscreenCloseButton) {
    threadExplorerFullscreenCloseButton.disabled = !threadExplorerFullscreen;
    threadExplorerFullscreenCloseButton.hidden = threadExplorerFullscreen !== true;
    threadExplorerFullscreenCloseButton.title = t("threadExplorerExitFullscreenButton");
    threadExplorerFullscreenCloseButton.setAttribute("aria-label", t("threadExplorerExitFullscreenButton"));
  }
  threadExplorerZoomResetButton.textContent = `${Math.round(threadExplorerZoom * 100)}%`;
  if (isThreadExplorerReplyClusterModeActive()) {
    threadExplorerViewModeButton.textContent = t("threadExplorerTreeViewButton");
    threadExplorerViewModeButton.setAttribute("aria-pressed", "true");
  } else {
    threadExplorerViewModeButton.textContent = t("threadExplorerReplyClusterButton");
    threadExplorerViewModeButton.setAttribute("aria-pressed", "false");
  }
  let saveButtonLabel = t("threadExplorerSaveButton");
  let saveButtonActive = false;
  if (isCurrentThreadExplorerThreadSaved()) {
    saveButtonLabel = t("threadExplorerSavedButton");
    saveButtonActive = true;
  }
  threadExplorerSaveButton.title = saveButtonLabel;
  threadExplorerSaveButton.setAttribute("aria-label", saveButtonLabel);
  threadExplorerSaveButton.classList.toggle("is-active", saveButtonActive);
  if (threadExplorerOrientation === THREAD_EXPLORER_ORIENTATION_HORIZONTAL) {
    threadExplorerOrientationButton.textContent = t("threadExplorerVerticalButton");
    threadExplorerOrientationButton.setAttribute("aria-pressed", "true");
  } else {
    threadExplorerOrientationButton.textContent = t("threadExplorerHorizontalButton");
    threadExplorerOrientationButton.setAttribute("aria-pressed", "false");
  }
  if (threadExplorerFullscreen === true) {
    threadExplorerFullscreenButton.textContent = t("threadExplorerExitFullscreenButton");
    threadExplorerFullscreenButton.setAttribute("aria-pressed", "true");
    threadExplorerFullscreenButton.setAttribute("aria-label", t("threadExplorerExitFullscreenButton"));
  } else {
    threadExplorerFullscreenButton.textContent = t("threadExplorerFullscreenButton");
    threadExplorerFullscreenButton.setAttribute("aria-pressed", "false");
    threadExplorerFullscreenButton.setAttribute("aria-label", t("threadExplorerFullscreenButton"));
  }

  if (threadExplorerSourceSelect) {
    if (["mutuals", "follows", "followers"].includes(threadExplorerSource)) {
      threadExplorerSourceSelect.value = threadExplorerSource;
    } else {
      threadExplorerSourceSelect.value = "follows";
    }
    threadExplorerSourceSelect.disabled = !hasAuth || threadExplorerLoadingFeed || isForeignAccountMode;
  }
  renderThreadExplorerAccountNote();
  renderThreadExplorerFeedSourceSelect();
}

/**
 * Renders the live Thread Explorer workspace.
 * @returns {void}
 */
function renderThreadExplorerWorkspace() {
  applyThreadExplorerFullscreenState();
  applyThreadExplorerOrientation();
  updateThreadExplorerControls();
  renderThreadExplorerFeed();
  renderThreadExplorerTree();
}

/**
 * Loads pinned feed sources for the Thread Explorer dropdown.
 * @returns {Promise<void>} Resolves when the dropdown sources are available.
 */
async function loadThreadExplorerFeedSources() {
  if (!authAccount || threadExplorerFeedSourcesLoading) {
    return;
  }
  const accountDid = String(authAccountDid || "").trim();
  if (threadExplorerFeedSourcesLoaded && threadExplorerFeedSourcesAccountDid === accountDid) {
    return;
  }
  if (threadExplorerFeedSourcesAccountDid !== accountDid) {
    threadExplorerFeedSources = [];
    threadExplorerFeedSourcesLoaded = false;
  }

  threadExplorerFeedSourcesLoading = true;
  renderThreadExplorerFeedSourceSelect();
  try {
    const result = await sendToServiceWorker("LOAD_THREAD_EXPLORER_FEED_SOURCES", {}, {
      timeoutMs: 60000,
    });
    if (Array.isArray(result?.feeds)) {
      threadExplorerFeedSources = result.feeds;
    } else {
      threadExplorerFeedSources = [];
    }
    threadExplorerFeedSourcesLoaded = true;
    threadExplorerFeedSourcesAccountDid = accountDid;
  } catch (error) {
    console.warn("Thread Explorer feed sources failed.", error);
    threadExplorerFeedSources = [];
    threadExplorerFeedSourcesLoaded = true;
    threadExplorerFeedSourcesAccountDid = accountDid;
  } finally {
    threadExplorerFeedSourcesLoading = false;
    renderThreadExplorerFeedSourceSelect();
  }
}

/**
 * Applies the current Thread Explorer orientation to the tree viewport.
 * @returns {void}
 */
function applyThreadExplorerOrientation() {
  const isHorizontal = threadExplorerOrientation === THREAD_EXPLORER_ORIENTATION_HORIZONTAL;
  threadExplorerThreadTree.classList.toggle("is-horizontal", isHorizontal);
  threadExplorerThreadTree.classList.toggle("is-vertical", !isHorizontal);
  threadExplorerThreadStage.classList.toggle("is-horizontal", isHorizontal);
  threadExplorerThreadStage.classList.toggle("is-vertical", !isHorizontal);
  threadExplorerThreadTree.classList.toggle("is-reply-cluster-mode", isThreadExplorerReplyClusterModeActive());
  threadExplorerThreadStage.classList.toggle("is-reply-cluster-mode", isThreadExplorerReplyClusterModeActive());
}

/**
 * Applies the current Thread Explorer pan and zoom to the stage element.
 * @returns {void}
 */
function applyThreadExplorerStageTransform() {
  threadExplorerThreadStage.style.setProperty("--thread-explorer-zoom", String(threadExplorerZoom));
  threadExplorerThreadStage.style.setProperty("--thread-explorer-pan-x", `${threadExplorerPanX}px`);
  threadExplorerThreadStage.style.setProperty("--thread-explorer-pan-y", `${threadExplorerPanY}px`);
  threadExplorerZoomResetButton.textContent = `${Math.round(threadExplorerZoom * 100)}%`;
}

/**
 * Applies the current Thread Explorer zoom to the stage element.
 * @returns {void}
 */
function applyThreadExplorerZoom() {
  applyThreadExplorerStageTransform();
}

/**
 * Sets the Thread Explorer zoom level within supported bounds.
 * @param {number} nextZoom - Desired zoom factor.
 * @returns {void}
 */
function setThreadExplorerZoom(nextZoom) {
  const numericZoom = Number(nextZoom);
  if (!Number.isFinite(numericZoom)) {
    return;
  }
  threadExplorerZoom = Math.min(2, Math.max(0.01, numericZoom));
  if (Math.abs(threadExplorerZoom - 1) > 0.01) {
    threadExplorerLastManualZoomBeforeReset = threadExplorerZoom;
  }
  applyThreadExplorerZoom();
}

/**
 * Switches the Thread Explorer between vertical and horizontal tree layout.
 * @returns {void}
 */
function toggleThreadExplorerOrientation() {
  if (isThreadExplorerReplyClusterModeActive()) {
    return;
  }
  if (threadExplorerOrientation === THREAD_EXPLORER_ORIENTATION_HORIZONTAL) {
    threadExplorerOrientation = THREAD_EXPLORER_ORIENTATION_VERTICAL;
  } else {
    threadExplorerOrientation = THREAD_EXPLORER_ORIENTATION_HORIZONTAL;
  }
  persistThreadExplorerOrientationPreference(threadExplorerOrientation);
  renderThreadExplorerWorkspace();
  if (threadExplorerTree) {
    scheduleThreadExplorerSelectedFocus();
  }
}

/**
 * Zooms the Thread Explorer stage around a viewport point.
 * @param {number} factor - Multiplicative zoom factor.
 * @param {number} clientX - Pointer x coordinate in viewport space.
 * @param {number} clientY - Pointer y coordinate in viewport space.
 * @returns {void}
 */
function zoomThreadExplorerAtPoint(factor, clientX, clientY) {
  const previousZoom = threadExplorerZoom;
  const bounds = threadExplorerThreadTree.getBoundingClientRect();
  const localX = clientX - bounds.left;
  const localY = clientY - bounds.top;
  const stageX = (localX - threadExplorerPanX) / previousZoom;
  const stageY = (localY - threadExplorerPanY) / previousZoom;
  setThreadExplorerZoom(previousZoom * factor);
  threadExplorerPanX = localX - (stageX * threadExplorerZoom);
  threadExplorerPanY = localY - (stageY * threadExplorerZoom);
  applyThreadExplorerStageTransform();
  scheduleThreadExplorerEdgeRender();
}

/**
 * Sets one absolute Thread Explorer zoom around the current viewport center.
 * @param {number} nextZoom - Desired absolute zoom factor.
 * @returns {void}
 */
function setThreadExplorerZoomAtViewportCenter(nextZoom) {
  const bounds = threadExplorerThreadTree.getBoundingClientRect();
  const centerX = bounds.left + (bounds.width / 2);
  const centerY = bounds.top + (bounds.height / 2);
  const currentZoom = Math.max(0.01, Number(threadExplorerZoom) || 1);
  zoomThreadExplorerAtPoint(nextZoom / currentZoom, centerX, centerY);
}

/**
 * Creates one feed-list button for a normalized Thread Explorer post.
 * @param {object} item - Feed item with a normalized post.
 * @returns {DocumentFragment} Rendered feed item fragment.
 */
function createThreadExplorerFeedItemFragment(item) {
  const post = item.post;
  const fragment = threadExplorerFeedItemTemplate.content.cloneNode(true);
  const button = fragment.querySelector(".thread-explorer-feed-item");
  const avatar = fragment.querySelector(".thread-explorer-avatar");
  const author = fragment.querySelector(".thread-explorer-feed-author");
  const meta = fragment.querySelector(".thread-explorer-feed-meta");
  const text = fragment.querySelector(".thread-explorer-feed-text");

  button.classList.toggle("is-active", post.uri === threadExplorerSelectedUri);
  markThreadExplorerAvatarImage(avatar, post.author);
  setAvatarImage(avatar, getThreadExplorerActorAvatarUri(post.author), getThreadExplorerActorLabel(post.author));
  author.textContent = getThreadExplorerActorLabel(post.author);
  meta.textContent = formatThreadExplorerDate(post.createdAt || post.indexedAt);
  text.textContent = getThreadExplorerPreviewText(post);
  button.dataset.uri = post.uri;
  button.addEventListener("click", handleThreadExplorerFeedItemClick);
  return fragment;
}

/**
 * Renders the Actor-Fokus card and its current result list.
 * @returns {void}
 */
function renderThreadExplorerActorFocus() {
  if (!threadExplorerActorFocus || !threadExplorerActorFeedList) {
    return;
  }

  threadExplorerActorFeedList.replaceChildren();
  if (!threadExplorerActorFocusActor) {
    threadExplorerActorFocus.hidden = true;
    return;
  }

  threadExplorerActorFocus.hidden = false;
  const actor = threadExplorerActorFocusActor;
  setAvatarImage(threadExplorerActorFocusAvatar, getThreadExplorerActorAvatarUri(actor), getThreadExplorerActorLabel(actor));
  threadExplorerActorFocusTitle.textContent = t("threadExplorerActorFocusTitle", {
    account: getThreadExplorerActorLabel(actor),
  });
  if (actor.handle) {
    threadExplorerActorFocusHandle.textContent = `@${actor.handle}`;
  } else {
    threadExplorerActorFocusHandle.textContent = actor.did || "";
  }

  if (threadExplorerActorModeSelect) {
    threadExplorerActorModeSelect.value = threadExplorerActorFocusMode;
    threadExplorerActorModeSelect.disabled = threadExplorerActorFocusLoading;
  }

  if (threadExplorerActorFocusError) {
    threadExplorerActorFocusStatus.textContent = threadExplorerActorFocusError;
  } else if (threadExplorerActorFocusLoading) {
    threadExplorerActorFocusStatus.textContent = t("threadExplorerActorFocusLoading");
  } else if (!threadExplorerActorFocusItems.length) {
    threadExplorerActorFocusStatus.textContent = t("threadExplorerActorFocusEmpty");
  } else {
    threadExplorerActorFocusStatus.textContent = t("threadExplorerActorFocusLoaded", {
      count: formatCount(threadExplorerActorFocusItems.length),
    });
  }

  threadExplorerActorFocusItems.forEach((item) => {
    threadExplorerActorFeedList.appendChild(createThreadExplorerFeedItemFragment(item));
  });
}

/**
 * Renders the left Thread Explorer feed list from templates.
 * @returns {void}
 */
function renderThreadExplorerFeed() {
  threadExplorerFeedList.replaceChildren();
  renderThreadExplorerActorFocus();
  const isForeignAccountMode = isThreadExplorerForeignAccountMode();

  if (threadExplorerFeedError) {
    threadExplorerFeedStatus.textContent = threadExplorerFeedError;
  } else if (threadExplorerLoadingFeed) {
    if (isForeignAccountMode) {
      threadExplorerFeedStatus.textContent = t("threadExplorerActorFocusLoading");
    } else if (threadExplorerItems.length > 0) {
      threadExplorerFeedStatus.textContent = t("threadExplorerFeedLoadingMore", {
        count: formatCount(threadExplorerItems.length),
      });
    } else {
      threadExplorerFeedStatus.textContent = t("threadExplorerFeedLoading");
    }
  } else if (!threadExplorerItems.length) {
    if (isForeignAccountMode) {
      threadExplorerFeedStatus.textContent = t("threadExplorerActorFocusEmpty");
    } else {
      threadExplorerFeedStatus.textContent = t("threadExplorerFeedEmpty");
    }
  } else {
    if (isForeignAccountMode) {
      threadExplorerFeedStatus.textContent = t("threadExplorerActorFocusLoaded", {
        count: formatCount(threadExplorerItems.length),
      });
    } else if (getThreadExplorerSearchIdFromSource(threadExplorerSource)) {
      threadExplorerFeedStatus.textContent = t("threadExplorerSearchLoaded", {
        count: formatCount(threadExplorerItems.length),
      });
    } else {
      threadExplorerFeedStatus.textContent = t("threadExplorerFeedLoaded", {
        count: formatCount(threadExplorerItems.length),
      });
    }
  }

  threadExplorerItems.forEach((item) => {
    threadExplorerFeedList.appendChild(createThreadExplorerFeedItemFragment(item));
  });
}

/**
 * Moves the Thread Explorer gallery selection by one or more images with loop-around.
 * @param {number} step - Relative movement, negative for previous and positive for next.
 * @returns {void}
 */
function stepThreadExplorerGallery(step) {
  const imageCount = threadExplorerGalleryImages.length;
  if (imageCount <= 1) {
    return;
  }

  const normalizedStep = Number(step) || 0;
  if (!normalizedStep) {
    return;
  }

  threadExplorerGalleryIndex = (threadExplorerGalleryIndex + normalizedStep + imageCount) % imageCount;
  renderThreadExplorerGalleryImage();
}

/**
 * Opens the Thread Explorer thread for the clicked feed item.
 * @param {Event} event - Click event from a feed item button.
 * @returns {void}
 */
function handleThreadExplorerFeedItemClick(event) {
  const button = event.currentTarget;
  const uri = String(button?.dataset?.uri || "").trim();
  void selectThreadExplorerPost(uri);
}

/**
 * Loads the next Thread Explorer feed page when the feed list is scrolled near the bottom.
 * @returns {void}
 */
function handleThreadExplorerFeedScroll() {
  if (!threadExplorerHasMore || threadExplorerLoadingFeed) {
    return;
  }
  const remaining = threadExplorerFeedList.scrollHeight - threadExplorerFeedList.scrollTop - threadExplorerFeedList.clientHeight;
  if (remaining > 240) {
    return;
  }
  void loadThreadExplorerFeed({ append: true });
}

/**
 * Loads the next Actor-Fokus page when the focus list is scrolled near the bottom.
 * @returns {void}
 */
function handleThreadExplorerActorFocusScroll() {
  if (!threadExplorerActorFocusHasMore || threadExplorerActorFocusLoading || !threadExplorerActorFeedList) {
    return;
  }
  const remaining = threadExplorerActorFeedList.scrollHeight - threadExplorerActorFeedList.scrollTop - threadExplorerActorFeedList.clientHeight;
  if (remaining > 240) {
    return;
  }
  void loadThreadExplorerActorFocusFeed({ append: true });
}

/**
 * Switches the Thread Explorer to the selected pinned feed.
 * @returns {void}
 */
function handleThreadExplorerFeedSelectChange() {
  const source = normalizeThreadExplorerSource(threadExplorerFeedSelect.value);
  if (!source.startsWith("feed:")) {
    return;
  }
  setThreadExplorerSource(source);
}

/**
 * Switches the Thread Explorer to the selected relationship source.
 * @param {Event} event - Change event from the relationship source select.
 * @returns {void}
 */
function handleThreadExplorerSourceSelectChange(event) {
  const source = normalizeThreadExplorerSource(event.currentTarget?.value || "");
  setThreadExplorerSource(source);
}

/**
 * Loads the Actor-Fokus feed for the current actor.
 * @param {object} options - Loading behavior.
 * @param {boolean} options.append - True when the next page should be appended.
 * @returns {Promise<void>} Resolves after the Actor-Fokus list is rendered.
 */
async function loadThreadExplorerActorFocusFeed(options = {}) {
  if (!authAccount || !threadExplorerActorFocusActor || threadExplorerActorFocusLoading) {
    return;
  }

  const append = options.append === true;
  if (append && !threadExplorerActorFocusHasMore) {
    return;
  }

  if (!append) {
    threadExplorerActorFocusItems = [];
    threadExplorerActorFocusCursor = "";
    threadExplorerActorFocusHasMore = false;
  }

  threadExplorerActorFocusLoading = true;
  threadExplorerActorFocusError = "";
  renderThreadExplorerWorkspace();
  try {
    const result = await sendToServiceWorker("LOAD_THREAD_EXPLORER_ACTOR_FEED", {
      actor: getThreadExplorerActorFocusId(threadExplorerActorFocusActor),
      cursor: threadExplorerActorFocusCursor,
      mode: threadExplorerActorFocusMode,
      limit: 30,
    }, {
      timeoutMs: 120000,
    });
    threadExplorerActorFocusCursor = String(result?.cursor || "");
    threadExplorerActorFocusHasMore = Boolean(threadExplorerActorFocusCursor);
    if (Array.isArray(result?.items)) {
      if (append) {
        threadExplorerActorFocusItems = appendThreadExplorerFeedItems(threadExplorerActorFocusItems, result.items);
      } else {
        threadExplorerActorFocusItems = result.items;
      }
      threadExplorerActorFocusItems = sortThreadExplorerFeedItemsByDate(threadExplorerActorFocusItems);
    }
  } catch (error) {
    threadExplorerActorFocusError = error.message || t("threadExplorerActorFocusFailed");
  } finally {
    threadExplorerActorFocusLoading = false;
    renderThreadExplorerWorkspace();
  }
}

/**
 * Opens the Actor-Fokus card for a Thread Explorer actor.
 * @param {object} actor - Normalized Thread Explorer actor.
 * @returns {void}
 */
function openThreadExplorerActorFocus(actor = {}) {
  const actorId = getThreadExplorerActorFocusId(actor);
  if (!actorId) {
    return;
  }

  const isOwnActor = isThreadExplorerOwnActor(actor);
  if (!isOwnActor) {
    if (!isThreadExplorerForeignActorFocusMode()) {
      threadExplorerAccountActorBeforeFocus = normalizeThreadExplorerActor(threadExplorerAccountActor);
      threadExplorerAccountModeBeforeFocus = normalizeThreadExplorerAccountMode(threadExplorerAccountMode);
    }
    threadExplorerAccountActor = normalizeThreadExplorerActor(actor.handle || actor.did || "");
    if (threadExplorerAccountInput) {
      threadExplorerAccountInput.value = threadExplorerAccountActor;
    }
    threadExplorerAccountError = "";
    threadExplorerActorFocusMode = normalizeThreadExplorerActorFocusMode(threadExplorerAccountMode);
  }
  threadExplorerActorFocusActor = { ...actor };
  threadExplorerActorFocusMode = normalizeThreadExplorerActorFocusMode(threadExplorerActorFocusMode);
  threadExplorerActorFocusItems = [];
  threadExplorerActorFocusCursor = "";
  threadExplorerActorFocusHasMore = false;
  threadExplorerActorFocusError = "";
  renderThreadExplorerWorkspace();
  void persistSettings();
  void loadThreadExplorerActorFocusFeed({ append: false });
}

/**
 * Clears the current Thread Explorer Actor-Fokus card.
 * @returns {void}
 */
function closeThreadExplorerActorFocus() {
  const shouldRestoreOwnContext = isThreadExplorerForeignActorFocusMode();
  threadExplorerActorFocusActor = null;
  threadExplorerActorFocusItems = [];
  threadExplorerActorFocusCursor = "";
  threadExplorerActorFocusHasMore = false;
  threadExplorerActorFocusLoading = false;
  threadExplorerActorFocusError = "";
  if (shouldRestoreOwnContext) {
    threadExplorerAccountActor = normalizeThreadExplorerActor(threadExplorerAccountActorBeforeFocus);
    threadExplorerAccountMode = normalizeThreadExplorerAccountMode(threadExplorerAccountModeBeforeFocus);
    threadExplorerAccountError = "";
    if (threadExplorerAccountInput) {
      threadExplorerAccountInput.value = threadExplorerAccountActor;
    }
    if (threadExplorerAccountModeSelect) {
      threadExplorerAccountModeSelect.value = threadExplorerAccountMode;
    }
    threadExplorerAccountActorBeforeFocus = "";
    threadExplorerAccountModeBeforeFocus = "posts";
    void loadThreadExplorerFeedSources();
  }
  renderThreadExplorerWorkspace();
  void persistSettings();
  if (shouldRestoreOwnContext && authAccount && !threadExplorerLoadingFeed) {
    void loadThreadExplorerFeed({ reset: true, clearSelection: true });
    return;
  }
}

/**
 * Changes the current Actor-Fokus feed mode.
 * @param {Event} event - Change event from the Actor-Fokus mode select.
 * @returns {void}
 */
function handleThreadExplorerActorModeChange(event) {
  threadExplorerActorFocusMode = normalizeThreadExplorerActorFocusMode(event.currentTarget?.value || "");
  void loadThreadExplorerActorFocusFeed({ append: false });
}

/**
 * Loads the next Actor-Fokus page.
 * @returns {void}
 */
function handleThreadExplorerActorMoreClick() {
  void loadThreadExplorerActorFocusFeed({ append: true });
}

/**
 * Opens a reaction account popup from a Thread Explorer count button.
 * @param {Event} event - Click event from a count button.
 * @returns {void}
 */
function handleThreadExplorerCountClick(event) {
  const button = event.currentTarget;
  const type = String(button?.dataset?.reactionType || "").trim();
  const uri = String(button?.dataset?.uri || "").trim();
  const cid = String(button?.dataset?.cid || "").trim();
  void openThreadExplorerReactionsDialog(type, uri, cid);
}

/**
 * Opens the loaded replies popup from a Thread Explorer reply count button.
 * @param {Event} event - Click event from a reply count button.
 * @returns {void}
 */
function handleThreadExplorerRepliesCountClick(event) {
  const button = event.currentTarget;
  const uri = String(button?.dataset?.uri || "").trim();
  openThreadExplorerRepliesDialog(uri);
}

/**
 * Renders the right Thread Explorer tree from templates.
 * @returns {void}
 */
function renderThreadExplorerTree() {
  resetThreadExplorerLazyCardObserver();
  threadExplorerReplyClusterLayoutState = null;
  threadExplorerThreadStage.replaceChildren();
  threadExplorerThreadStage.classList.remove("has-svg-edges");
  threadExplorerThreadStage.classList.remove("is-reply-cluster-mode");
  applyThreadExplorerStageTransform();

  if (threadExplorerThreadError) {
    threadExplorerThreadTitle.textContent = t("threadExplorerThreadLoadedTitle", {
      count: formatCount(0),
    });
    threadExplorerThreadStatus.textContent = threadExplorerThreadError;
    return;
  }

  if (threadExplorerLoadingThread) {
    threadExplorerThreadTitle.textContent = t("threadExplorerThreadLoadedTitle", {
      count: formatCount(0),
    });
    threadExplorerThreadStatus.textContent = t("threadExplorerThreadLoading");
    return;
  }

  if (!threadExplorerTree) {
    threadExplorerThreadTitle.textContent = t("threadExplorerThreadTitle");
    threadExplorerThreadStatus.textContent = t("threadExplorerThreadIdle");
    return;
  }

  const count = countThreadExplorerPosts(threadExplorerTree);
  threadExplorerThreadTitle.textContent = t("threadExplorerThreadLoadedTitle", {
    count: formatCount(count),
  });
  threadExplorerThreadStatus.textContent = t("threadExplorerThreadLoaded", {
    count: formatCount(count),
  });

  if (threadExplorerViewMode === THREAD_EXPLORER_VIEW_MODE_REPLY_CLUSTER) {
    renderThreadExplorerReplyCluster();
  } else {
    const rootList = document.createElement("ul");
    rootList.appendChild(createThreadExplorerNode(threadExplorerTree));
    threadExplorerThreadStage.appendChild(rootList);
  }
  hydrateVisibleThreadExplorerCards();
  if (threadExplorerViewMode !== THREAD_EXPLORER_VIEW_MODE_REPLY_CLUSTER) {
    scheduleThreadExplorerEdgeRender();
  }
}

/**
 * Disconnects the current Thread Explorer lazy-card observer.
 * @returns {void}
 */
function resetThreadExplorerLazyCardObserver() {
  if (threadExplorerCardObserver) {
    threadExplorerCardObserver.disconnect();
  }
  threadExplorerCardObserver = null;
}

/**
 * Returns the lazy-card observer for Thread Explorer post cards.
 * @returns {IntersectionObserver|null} Observer instance or null when unsupported.
 */
function getThreadExplorerLazyCardObserver() {
  if (threadExplorerForceHydrateCards) {
    return null;
  }
  if (typeof IntersectionObserver !== "function") {
    return null;
  }
  if (threadExplorerCardObserver) {
    return threadExplorerCardObserver;
  }

  threadExplorerCardObserver = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) {
        return;
      }
      const card = entry.target;
      hydrateThreadExplorerCardContent(card);
      threadExplorerCardObserver.unobserve(card);
    });
  }, {
    root: threadExplorerThreadTree,
    rootMargin: "900px",
    threshold: 0,
  });
  return threadExplorerCardObserver;
}

/**
 * Hydrates a Thread Explorer card when it becomes relevant for display.
 * @param {HTMLElement|null} card - Rendered post card.
 * @returns {void}
 */
function hydrateThreadExplorerCardContent(card = null) {
  if (!card || card.dataset.hydrated === "true") {
    return;
  }

  const post = card._threadExplorerPost || null;
  if (!post || post.isDeletedThreadAnchor === true) {
    card.dataset.hydrated = "true";
    return;
  }

  const avatar = card.querySelector(".thread-explorer-avatar");
  const gallery = card.querySelector(".thread-explorer-post-gallery");
  markThreadExplorerAvatarImage(avatar, post.author);
  setAvatarImage(avatar, getThreadExplorerActorAvatarUri(post.author), getThreadExplorerActorLabel(post.author));
  renderThreadExplorerImages(post, gallery);
  syncThreadExplorerPostCardImageShape(card, gallery);
  renderThreadExplorerExternalCard(post, card);
  renderThreadExplorerQuoteCard(post, card);
  card.dataset.hydrated = "true";
  card.classList.remove("is-awaiting-content");
  if (isThreadExplorerReplyClusterModeActive()) {
    layoutThreadExplorerReplyCluster(threadExplorerReplyClusterLayoutState);
  } else {
    scheduleThreadExplorerEdgeRender();
  }
}

/**
 * Observes or immediately hydrates a Thread Explorer card.
 * @param {HTMLElement|null} card - Rendered post card.
 * @param {object} post - Normalized Thread Explorer post.
 * @returns {void}
 */
function prepareThreadExplorerCardHydration(card = null, post = {}) {
  if (!card || post?.isDeletedThreadAnchor === true) {
    return;
  }

  card._threadExplorerPost = post;
  card.classList.add("is-awaiting-content");
  if (threadExplorerForceHydrateCards || post.uri === threadExplorerSelectedUri) {
    hydrateThreadExplorerCardContent(card);
    return;
  }

  const observer = getThreadExplorerLazyCardObserver();
  if (!observer) {
    hydrateThreadExplorerCardContent(card);
    return;
  }
  observer.observe(card);
}

/**
 * Hydrates cards that are already visible after a tree render.
 * @returns {void}
 */
function hydrateVisibleThreadExplorerCards() {
  if (threadExplorerForceHydrateCards) {
    threadExplorerThreadStage.querySelectorAll(".thread-explorer-post-card").forEach((card) => {
      hydrateThreadExplorerCardContent(card);
    });
  }
}

/**
 * Returns the timestamp used to sort one Thread Explorer reply.
 * @param {object|null} node - Normalized Thread Explorer reply node.
 * @returns {number} Epoch milliseconds or a large fallback value.
 */
function getThreadExplorerReplySortTimestamp(node = null) {
  const createdAt = Date.parse(String(node?.post?.createdAt || "").trim());
  if (Number.isFinite(createdAt)) {
    return createdAt;
  }

  const indexedAt = Date.parse(String(node?.post?.indexedAt || "").trim());
  if (Number.isFinite(indexedAt)) {
    return indexedAt;
  }

  return Number.POSITIVE_INFINITY;
}

/**
 * Returns Thread Explorer replies sorted chronologically without mutating the source array.
 * @param {Array<object>} replies - Raw reply nodes for one parent post.
 * @returns {Array<object>} Replies sorted oldest first within the sibling group.
 */
function getChronologicalThreadExplorerReplies(replies) {
  if (!Array.isArray(replies)) {
    return [];
  }

  return replies
    .map((reply, index) => {
      return {
        reply,
        index,
      };
    })
    .sort((left, right) => {
      const leftTime = getThreadExplorerReplySortTimestamp(left.reply);
      const rightTime = getThreadExplorerReplySortTimestamp(right.reply);
      if (leftTime !== rightTime) {
        return leftTime - rightTime;
      }
      return left.index - right.index;
    })
    .map((entry) => {
      return entry.reply;
    });
}

/**
 * Creates a rendered Thread Explorer post item from the shared node template.
 * @param {object} node - Normalized Thread Explorer tree node.
 * @param {object} options - Rendering options for this shared post item.
 * @param {boolean} options.renderReplies - Whether child replies should be rendered recursively.
 * @param {boolean} options.showToggle - Whether the collapse toggle should stay visible.
 * @returns {{item:HTMLElement, card:HTMLElement, children:HTMLElement, post:object, replies:Array<object>}} Rendered node parts.
 */
function createThreadExplorerRenderedItem(node, options = {}) {
  const renderReplies = options.renderReplies !== false;
  const showToggle = options.showToggle !== false;
  const fragment = threadExplorerNodeTemplate.content.cloneNode(true);
  const item = fragment.querySelector(".thread-explorer-node-item");
  const toggle = fragment.querySelector(".thread-explorer-node-toggle");
  const card = fragment.querySelector(".thread-explorer-post-card");
  const actorTriggers = Array.from(fragment.querySelectorAll(".thread-explorer-actor-trigger"));
  const avatar = fragment.querySelector(".thread-explorer-avatar");
  const author = fragment.querySelector(".thread-explorer-post-author");
  const handle = fragment.querySelector(".thread-explorer-post-handle");
  const meta = fragment.querySelector(".thread-explorer-post-meta");
  const viewLink = fragment.querySelector(".thread-explorer-view-link");
  const headButtons = fragment.querySelector(".thread-explorer-post-head-buttons");
  const editButton = fragment.querySelector(".thread-explorer-edit-button");
  const actions = fragment.querySelector(".thread-explorer-post-actions");
  const text = fragment.querySelector(".thread-explorer-post-text");
  const gallery = fragment.querySelector(".thread-explorer-post-gallery");
  const counts = fragment.querySelector(".thread-explorer-post-counts");
  const children = fragment.querySelector(".thread-explorer-children");
  const post = node.post;
  const replies = getChronologicalThreadExplorerReplies(node.replies);
  const engagementScore = getThreadExplorerEngagementScore(post);
  const engagementTier = getThreadExplorerEngagementTier(engagementScore);
  const isDeletedThreadAnchor = post.isDeletedThreadAnchor === true;

  item.dataset.uri = post.uri;
  item.dataset.engagementScore = String(engagementScore);
  item.dataset.engagementTier = engagementTier;
  item.classList.toggle("is-collapsed", threadExplorerCollapsedUris.has(post.uri));
  card.classList.toggle("is-selected", post.uri === threadExplorerSelectedUri);
  card.classList.toggle("is-deleted-thread-anchor", isDeletedThreadAnchor);
  if (!isDeletedThreadAnchor) {
    card.classList.add(`is-engagement-${engagementTier}`);
  }

  if (isDeletedThreadAnchor) {
    actorTriggers.forEach((trigger) => {
      trigger.hidden = true;
      trigger.disabled = true;
    });
    avatar.hidden = true;
    author.textContent = t("threadExplorerDeletedThreadTitle");
    handle.textContent = post.uri.replace(/^at:\/\//, "");
    meta.textContent = "";
    viewLink.hidden = true;
    editButton.hidden = true;
    actions.hidden = true;
    text.textContent = t("threadExplorerDeletedThreadText");
    counts.replaceChildren();
  } else {
    setAvatarImage(avatar, "", getThreadExplorerActorLabel(post.author));
    author.textContent = getThreadExplorerActorLabel(post.author);
    if (post.author?.handle) {
      handle.textContent = `@${post.author.handle}`;
    } else if (post.author?.did) {
      handle.textContent = post.author.did;
    } else {
      handle.textContent = "";
    }
    meta.textContent = formatThreadExplorerDate(post.createdAt || post.indexedAt);
    renderThreadExplorerViewLink(post, viewLink);
    renderThreadExplorerEditButton(post, editButton);
    renderThreadExplorerInteractionActions(post, actions, headButtons, viewLink);
    text.textContent = getThreadExplorerPostDisplayText(post) || t("threadExplorerNoText");
    renderThreadExplorerCounts(post, counts);
    actorTriggers.forEach((trigger) => {
      trigger.dataset.actorDid = post.author?.did || "";
      trigger.dataset.actorHandle = post.author?.handle || "";
      applyTranslatedTitle(trigger, "threadExplorerActorFocusTriggerTitle");
      trigger.addEventListener("click", () => {
        openThreadExplorerActorFocus(post.author || {});
      });
    });
    prepareThreadExplorerCardHydration(card, post);
  }

  card.addEventListener("click", handleThreadExplorerCardClick);
  card.addEventListener("dblclick", handleThreadExplorerCardDoubleClick);
  card.addEventListener("pointerup", handleThreadExplorerCardPointerUp);

  if (!showToggle || !replies.length) {
    toggle.classList.add("is-hidden");
    toggle.disabled = true;
  } else {
    if (isThreadExplorerReplyClusterModeActive()) {
      if (isThreadExplorerReplyClusterExpanded(post.uri)) {
        toggle.textContent = "-";
      } else {
        toggle.textContent = "+";
      }
    } else {
      if (threadExplorerCollapsedUris.has(post.uri)) {
        toggle.textContent = "+";
      } else {
        toggle.textContent = "-";
      }
    }
    toggle.dataset.uri = post.uri;
    toggle.addEventListener("click", handleThreadExplorerNodeToggleClick);
  }

  if (renderReplies) {
    replies.forEach((reply) => {
      children.appendChild(createThreadExplorerNode(reply));
    });
  } else {
    children.remove();
  }

  return {
    item,
    card,
    children,
    post,
    replies,
  };
}

/**
 * Creates one Thread Explorer tree node from the node template.
 * @param {object} node - Normalized Thread Explorer tree node.
 * @returns {HTMLElement} A rendered list item containing the post and child replies.
 */
function createThreadExplorerNode(node) {
  return createThreadExplorerRenderedItem(node, {
    renderReplies: true,
    showToggle: true,
  }).item;
}

/**
 * Returns whether the Thread Explorer currently renders the reply-cluster mode.
 * @returns {boolean} True when the reply-cluster mode is active.
 */
function isThreadExplorerReplyClusterModeActive() {
  return threadExplorerViewMode === THREAD_EXPLORER_VIEW_MODE_REPLY_CLUSTER;
}

/**
 * Ensures that the current thread root is always expanded in reply-cluster mode.
 * @returns {void}
 */
function ensureThreadExplorerReplyClusterRootExpanded() {
  const rootUri = String(threadExplorerTree?.post?.uri || "").trim();
  if (!rootUri) {
    return;
  }

  threadExplorerReplyClusterExpandedUris.add(rootUri);
}

/**
 * Expands the complete loaded reply-cluster tree.
 * @param {object|null} node - Normalized Thread Explorer tree node.
 * @returns {void}
 */
function expandAllThreadExplorerReplyClusterNodes(node) {
  if (!node || !node.post?.uri) {
    return;
  }

  threadExplorerReplyClusterExpandedUris.add(String(node.post.uri).trim());
  const replies = Array.isArray(node.replies) ? node.replies : [];
  replies.forEach((reply) => {
    expandAllThreadExplorerReplyClusterNodes(reply);
  });
}

/**
 * Returns whether one reply-cluster node is currently expanded.
 * @param {string} uri - AT URI of the cluster node.
 * @returns {boolean} True when the node is expanded or is the current root.
 */
function isThreadExplorerReplyClusterExpanded(uri) {
  const normalizedUri = String(uri || "").trim();
  if (!normalizedUri) {
    return false;
  }

  ensureThreadExplorerReplyClusterRootExpanded();
  return threadExplorerReplyClusterExpandedUris.has(normalizedUri);
}

/**
 * Toggles one reply-cluster subtree and keeps the current open state for every other node.
 * @param {string} uri - AT URI of the subtree root that should toggle.
 * @returns {void}
 */
function toggleThreadExplorerReplyClusterNode(uri) {
  const normalizedUri = String(uri || "").trim();
  if (!normalizedUri) {
    return;
  }

  if (threadExplorerReplyClusterExpandedUris.has(normalizedUri)) {
    threadExplorerReplyClusterExpandedUris.delete(normalizedUri);
  } else {
    threadExplorerReplyClusterExpandedUris.add(normalizedUri);
  }
  renderThreadExplorerTree();
}

/**
 * Refreshes rendered Thread Explorer geometry after media changed size.
 * @returns {void}
 */
function refreshThreadExplorerRenderedGeometry() {
  if (isThreadExplorerReplyClusterModeActive()) {
    layoutThreadExplorerReplyCluster(threadExplorerReplyClusterLayoutState);
    return;
  }

  scheduleThreadExplorerEdgeRender();
}

/**
 * Applies one absolute center position to a reply-cluster card.
 * @param {HTMLElement|null} item - Cluster item element to move.
 * @param {number} centerX - Horizontal stage-space center.
 * @param {number} centerY - Vertical stage-space center.
 * @returns {void}
 */
function setThreadExplorerReplyClusterItemPosition(item, centerX, centerY) {
  if (!item) {
    return;
  }

  item.style.setProperty("--thread-explorer-cluster-x", `${Math.round(centerX)}px`);
  item.style.setProperty("--thread-explorer-cluster-y", `${Math.round(centerY)}px`);
}

/**
 * Returns the edge anchor point where a reply-cluster line should leave one card.
 * @param {{x:number, y:number}} center - Card center in stage space.
 * @param {{width:number, height:number}} size - Rendered card size.
 * @param {{x:number, y:number}} target - Opposing card center that defines the direction.
 * @returns {{x:number, y:number}} Anchor point on the card edge.
 */
function getThreadExplorerReplyClusterEdgeAnchor(center, size, target) {
  const deltaX = Number(target?.x) - Number(center?.x);
  const deltaY = Number(target?.y) - Number(center?.y);
  const distance = Math.hypot(deltaX, deltaY);
  if (!distance || !size) {
    return {
      x: Number(center?.x) || 0,
      y: Number(center?.y) || 0,
    };
  }

  const directionX = deltaX / distance;
  const directionY = deltaY / distance;
  const halfWidth = Math.max(1, Number(size.width) || 0) / 2;
  const halfHeight = Math.max(1, Number(size.height) || 0) / 2;
  let scaleX = Number.POSITIVE_INFINITY;
  let scaleY = Number.POSITIVE_INFINITY;
  if (Math.abs(directionX) > 0.0001) {
    scaleX = halfWidth / Math.abs(directionX);
  }
  if (Math.abs(directionY) > 0.0001) {
    scaleY = halfHeight / Math.abs(directionY);
  }
  const edgeDistance = Math.min(scaleX, scaleY);
  return {
    x: center.x + (directionX * edgeDistance),
    y: center.y + (directionY * edgeDistance),
  };
}

/**
 * Measures one rendered reply-cluster card.
 * @param {HTMLElement|null} item - Cluster item element to measure.
 * @returns {{width:number, height:number}} Rendered size in CSS pixels.
 */
function getThreadExplorerReplyClusterItemSize(item) {
  if (!item) {
    return {
      width: 0,
      height: 0,
    };
  }

  return {
    width: Math.max(0, item.offsetWidth),
    height: Math.max(0, item.offsetHeight),
  };
}

/**
 * Returns the current rectangle of one positioned reply-cluster item.
 * @param {object|null} renderNode - Positioned reply-cluster render node.
 * @returns {{left:number, top:number, right:number, bottom:number, width:number, height:number}} Rectangle in stage space.
 */
function getThreadExplorerReplyClusterNodeRect(renderNode) {
  const itemSize = renderNode?.itemSize || getThreadExplorerReplyClusterItemSize(renderNode?.item || null);
  const centerX = Number(renderNode?.position?.x) || 0;
  const centerY = Number(renderNode?.position?.y) || 0;
  return {
    left: centerX - (itemSize.width / 2),
    top: centerY - (itemSize.height / 2),
    right: centerX + (itemSize.width / 2),
    bottom: centerY + (itemSize.height / 2),
    width: itemSize.width,
    height: itemSize.height,
  };
}

/**
 * Applies one new reply-cluster center position to a positioned render node.
 * @param {object|null} renderNode - Positioned reply-cluster render node.
 * @param {number} nextX - New center X position in stage space.
 * @param {number} nextY - New center Y position in stage space.
 * @returns {void}
 */
function setThreadExplorerReplyClusterNodePosition(renderNode, nextX, nextY) {
  if (!renderNode) {
    return;
  }

  renderNode.position = {
    x: nextX,
    y: nextY,
  };
  setThreadExplorerReplyClusterItemPosition(renderNode.item, nextX, nextY);
}

/**
 * Pushes overlapping reply-cluster cards apart after media growth changed their size.
 * @param {object|null} layoutState - Current reply-cluster render state.
 * @returns {void}
 */
function resolveThreadExplorerReplyClusterOverlaps(layoutState) {
  if (!layoutState?.rootRenderNode || !Array.isArray(layoutState.positionedItems) || layoutState.positionedItems.length < 2) {
    return;
  }

  const rootNode = layoutState.rootRenderNode;
  const collisionPadding = 24;
  const maxIterations = 18;

  for (let iteration = 0; iteration < maxIterations; iteration += 1) {
    let hasMoved = false;

    for (let indexA = 0; indexA < layoutState.positionedItems.length; indexA += 1) {
      const nodeA = layoutState.positionedItems[indexA];
      const rectA = getThreadExplorerReplyClusterNodeRect(nodeA);

      for (let indexB = indexA + 1; indexB < layoutState.positionedItems.length; indexB += 1) {
        const nodeB = layoutState.positionedItems[indexB];
        const rectB = getThreadExplorerReplyClusterNodeRect(nodeB);
        const overlapX = Math.min(rectA.right, rectB.right) - Math.max(rectA.left, rectB.left);
        const overlapY = Math.min(rectA.bottom, rectB.bottom) - Math.max(rectA.top, rectB.top);
        if (overlapX <= 0 || overlapY <= 0) {
          continue;
        }

        let deltaX = (Number(nodeB.position?.x) || 0) - (Number(nodeA.position?.x) || 0);
        let deltaY = (Number(nodeB.position?.y) || 0) - (Number(nodeA.position?.y) || 0);
        if (!deltaX && !deltaY) {
          deltaX = (Number(nodeB.position?.x) || 0) - (Number(rootNode.position?.x) || 0);
          deltaY = (Number(nodeB.position?.y) || 0) - (Number(rootNode.position?.y) || 0);
        }
        if (!deltaX && !deltaY) {
          deltaY = 1;
        }

        const distance = Math.hypot(deltaX, deltaY) || 1;
        const directionX = deltaX / distance;
        const directionY = deltaY / distance;
        const pushDistance = Math.max(overlapX, overlapY) + collisionPadding;

        if (nodeA === rootNode) {
          setThreadExplorerReplyClusterNodePosition(
            nodeB,
            (Number(nodeB.position?.x) || 0) + (directionX * pushDistance),
            (Number(nodeB.position?.y) || 0) + (directionY * pushDistance),
          );
        } else if (nodeB === rootNode) {
          setThreadExplorerReplyClusterNodePosition(
            nodeA,
            (Number(nodeA.position?.x) || 0) - (directionX * pushDistance),
            (Number(nodeA.position?.y) || 0) - (directionY * pushDistance),
          );
        } else {
          const halfPush = pushDistance / 2;
          setThreadExplorerReplyClusterNodePosition(
            nodeA,
            (Number(nodeA.position?.x) || 0) - (directionX * halfPush),
            (Number(nodeA.position?.y) || 0) - (directionY * halfPush),
          );
          setThreadExplorerReplyClusterNodePosition(
            nodeB,
            (Number(nodeB.position?.x) || 0) + (directionX * halfPush),
            (Number(nodeB.position?.y) || 0) + (directionY * halfPush),
          );
        }

        hasMoved = true;
      }
    }

    if (!hasMoved) {
      break;
    }
  }
}

/**
 * Measures one recursive reply-cluster subtree and returns its required bounds.
 * @param {object|null} renderNode - Recursive reply-cluster render node.
 * @returns {{width:number, height:number}} Required subtree bounds.
 */
function measureThreadExplorerReplyClusterSubtree(renderNode) {
  if (!renderNode) {
    return {
      width: 0,
      height: 0,
    };
  }

  const itemSize = getThreadExplorerReplyClusterItemSize(renderNode.item);
  renderNode.itemSize = itemSize;
  if (!Array.isArray(renderNode.children) || renderNode.children.length === 0) {
    renderNode.subtreeWidth = Math.max(220, itemSize.width);
    renderNode.subtreeHeight = Math.max(120, itemSize.height);
    return {
      width: renderNode.subtreeWidth,
      height: renderNode.subtreeHeight,
    };
  }

  const childGap = 48;
  let totalChildWidth = 0;
  let maxChildHeight = 0;
  renderNode.children.forEach((childNode, childIndex) => {
    const childBounds = measureThreadExplorerReplyClusterSubtree(childNode);
    totalChildWidth += childBounds.width;
    if (childIndex > 0) {
      totalChildWidth += childGap;
    }
    maxChildHeight = Math.max(maxChildHeight, childBounds.height);
  });

  renderNode.subtreeWidth = Math.max(itemSize.width, totalChildWidth);
  renderNode.subtreeHeight = itemSize.height + 84 + maxChildHeight;
  return {
    width: renderNode.subtreeWidth,
    height: renderNode.subtreeHeight,
  };
}

/**
 * Returns the combined breadth of all direct child subtrees including gaps.
 * @param {object|null} renderNode - Recursive reply-cluster render node.
 * @param {number} childGap - Gap between sibling subtrees in local layout space.
 * @returns {number} Total local breadth for the child row.
 */
function getThreadExplorerReplyClusterChildrenBreadth(renderNode, childGap) {
  if (!renderNode || !Array.isArray(renderNode.children) || renderNode.children.length === 0) {
    return 0;
  }

  let totalBreadth = 0;
  renderNode.children.forEach((childNode, childIndex) => {
    totalBreadth += childNode.subtreeWidth;
    if (childIndex > 0) {
      totalBreadth += childGap;
    }
  });
  return totalBreadth;
}

/**
 * Places one reply-cluster branch so that children continue away from the root direction.
 * @param {object|null} renderNode - Recursive reply-cluster render node.
 * @param {number} centerX - Branch center X in stage space.
 * @param {number} centerY - Branch center Y in stage space.
 * @param {number} angle - Outward branch angle in radians.
 * @param {Array<object>} positionedItems - Flat array that receives positioned cards.
 * @returns {void}
 */
function placeThreadExplorerReplyClusterSubtree(renderNode, centerX, centerY, angle, positionedItems) {
  if (!renderNode) {
    return;
  }

  renderNode.position = {
    x: centerX,
    y: centerY,
  };
  setThreadExplorerReplyClusterItemPosition(renderNode.item, centerX, centerY);
  positionedItems.push(renderNode);

  if (!Array.isArray(renderNode.children) || renderNode.children.length === 0) {
    return;
  }

  const childGap = 48;
  const childrenBreadth = getThreadExplorerReplyClusterChildrenBreadth(renderNode, childGap);
  const radialX = Math.cos(angle);
  const radialY = Math.sin(angle);
  const tangentX = -Math.sin(angle);
  const tangentY = Math.cos(angle);
  let childOffset = -childrenBreadth / 2;
  const outwardDistance = (renderNode.itemSize.height / 2) + 84;
  renderNode.children.forEach((childNode) => {
    const childCenterOffset = childOffset + (childNode.subtreeWidth / 2);
    const childCenterDistance = outwardDistance + (childNode.itemSize.height / 2);
    const childCenterX = centerX + (tangentX * childCenterOffset) + (radialX * childCenterDistance);
    const childCenterY = centerY + (tangentY * childCenterOffset) + (radialY * childCenterDistance);
    placeThreadExplorerReplyClusterSubtree(childNode, childCenterX, childCenterY, angle, positionedItems);
    childOffset += childNode.subtreeWidth + childGap;
  });
}

/**
 * Returns stable star angles for the direct replies around the cluster root.
 * @param {Array<object>} directReplies - Direct reply subtrees around the root.
 * @param {number} clusterRadius - Radius used for the first reply ring.
 * @returns {number[]} One outward angle per direct reply in radians.
 */
function getThreadExplorerReplyClusterRootChildAngles(directReplies, clusterRadius) {
  if (!Array.isArray(directReplies) || directReplies.length === 0) {
    return [];
  }

  if (directReplies.length === 1) {
    return [Math.PI / 2];
  }

  const arcPadding = 56;
  let totalAngularSpan = 0;
  directReplies.forEach((childNode) => {
    totalAngularSpan += (childNode.subtreeWidth + arcPadding) / Math.max(1, clusterRadius);
  });

  if (totalAngularSpan <= 0) {
    return [];
  }

  const normalizedSpan = Math.min(Math.PI * 2, totalAngularSpan);
  let currentAngle = (-Math.PI / 2) - (normalizedSpan / 2);
  const angles = [];
  directReplies.forEach((childNode) => {
    const childSpan = (childNode.subtreeWidth + arcPadding) / Math.max(1, clusterRadius);
    const centeredSpan = Math.min(childSpan, Math.PI * 2);
    angles.push(currentAngle + (centeredSpan / 2));
    currentAngle += centeredSpan;
  });
  return angles;
}

/**
 * Renders every visible reply-cluster edge for the positioned recursive tree.
 * @param {object|null} layoutState - Current reply-cluster render state.
 * @returns {void}
 */
function renderThreadExplorerReplyClusterEdges(layoutState) {
  if (!layoutState?.edgeLayer || !Array.isArray(layoutState.positionedItems)) {
    return;
  }

  layoutState.edgeLayer.replaceChildren();
  layoutState.positionedItems.forEach((renderNode) => {
    if (!Array.isArray(renderNode.children) || renderNode.children.length === 0) {
      return;
    }

    const parentSize = getThreadExplorerReplyClusterItemSize(renderNode.item);
    renderNode.children.forEach((childNode) => {
      const childSize = getThreadExplorerReplyClusterItemSize(childNode.item);
      const start = getThreadExplorerReplyClusterEdgeAnchor(renderNode.position, parentSize, childNode.position);
      const end = getThreadExplorerReplyClusterEdgeAnchor(childNode.position, childSize, renderNode.position);
      appendThreadExplorerReplyClusterEdge(layoutState.edgeLayer, start, end, "thread-explorer-edge-reply");
    });
  });
}

/**
 * Applies the positioned recursive reply-cluster tree to the stage and updates bounds.
 * @param {object|null} layoutState - Current reply-cluster render state.
 * @returns {void}
 */
function applyThreadExplorerReplyClusterBounds(layoutState) {
  if (!layoutState?.cluster || !Array.isArray(layoutState.positionedItems)) {
    return;
  }

  let minLeft = Number.POSITIVE_INFINITY;
  let minTop = Number.POSITIVE_INFINITY;
  let maxRight = Number.NEGATIVE_INFINITY;
  let maxBottom = Number.NEGATIVE_INFINITY;
  layoutState.positionedItems.forEach((renderNode) => {
    const itemSize = getThreadExplorerReplyClusterItemSize(renderNode.item);
    minLeft = Math.min(minLeft, renderNode.position.x - (itemSize.width / 2));
    minTop = Math.min(minTop, renderNode.position.y - (itemSize.height / 2));
    maxRight = Math.max(maxRight, renderNode.position.x + (itemSize.width / 2));
    maxBottom = Math.max(maxBottom, renderNode.position.y + (itemSize.height / 2));
  });

  const shiftX = Math.max(0, 80 - minLeft);
  const shiftY = Math.max(0, 80 - minTop);
  if (shiftX || shiftY) {
    layoutState.positionedItems.forEach((renderNode) => {
      renderNode.position.x += shiftX;
      renderNode.position.y += shiftY;
      setThreadExplorerReplyClusterItemPosition(renderNode.item, renderNode.position.x, renderNode.position.y);
    });
    maxRight += shiftX;
    maxBottom += shiftY;
  }

  const stageWidth = Math.max(1120, Math.ceil(maxRight + 80));
  const stageHeight = Math.max(860, Math.ceil(maxBottom + 80));
  layoutState.cluster.style.width = `${stageWidth}px`;
  layoutState.cluster.style.height = `${stageHeight}px`;
  layoutState.edgeLayer.setAttribute("width", String(stageWidth));
  layoutState.edgeLayer.setAttribute("height", String(stageHeight));
  layoutState.edgeLayer.setAttribute("viewBox", `0 0 ${stageWidth} ${stageHeight}`);
  renderThreadExplorerReplyClusterEdges(layoutState);
}

/**
 * Recomputes the complete recursive reply-cluster layout without overlaps.
 * @param {object|null} layoutState - Current reply-cluster render state.
 * @returns {void}
 */
function layoutThreadExplorerReplyCluster(layoutState) {
  if (!layoutState?.rootRenderNode) {
    return;
  }

  measureThreadExplorerReplyClusterSubtree(layoutState.rootRenderNode);
  layoutState.positionedItems = [];
  const rootNode = layoutState.rootRenderNode;
  const rootSize = rootNode.itemSize || getThreadExplorerReplyClusterItemSize(rootNode.item);
  const rootCenterX = 720;
  const rootCenterY = 540;

  rootNode.position = {
    x: rootCenterX,
    y: rootCenterY,
  };
  setThreadExplorerReplyClusterItemPosition(rootNode.item, rootCenterX, rootCenterY);
  layoutState.positionedItems.push(rootNode);

  const directReplies = Array.isArray(rootNode.children) ? rootNode.children : [];
  if (directReplies.length > 0) {
    const maxChildWidth = directReplies.reduce((maximumWidth, childNode) => {
      return Math.max(maximumWidth, childNode.itemSize?.width || 0);
    }, 0);
    const totalBreadth = directReplies.reduce((breadthSum, childNode) => {
      return breadthSum + childNode.subtreeWidth;
    }, 0);
    const rootClearanceRadius = (Math.max(rootSize.width, rootSize.height) / 2) + (maxChildWidth / 2) + 120;
    const circumferenceRadius = totalBreadth / (Math.PI * 1.75);
    const clusterRadius = Math.max(320, rootClearanceRadius, circumferenceRadius);
    const directReplyAngles = getThreadExplorerReplyClusterRootChildAngles(directReplies, clusterRadius);

    directReplies.forEach((childNode, childIndex) => {
      const angle = directReplyAngles[childIndex];
      const childCenterX = rootCenterX + (Math.cos(angle) * clusterRadius);
      const childCenterY = rootCenterY + (Math.sin(angle) * clusterRadius);
      placeThreadExplorerReplyClusterSubtree(childNode, childCenterX, childCenterY, angle, layoutState.positionedItems);
    });
  }

  resolveThreadExplorerReplyClusterOverlaps(layoutState);
  applyThreadExplorerReplyClusterBounds(layoutState);
}

/**
 * Selects one already loaded Thread Explorer URI without changing the cluster center.
 * @param {string} uri - AT URI to select locally.
 * @returns {void}
 */
function setThreadExplorerSelectedUriLocally(uri) {
  const selectedUri = String(uri || "").trim();
  if (!selectedUri || selectedUri === threadExplorerSelectedUri) {
    return;
  }

  threadExplorerSelectedUri = selectedUri;
  persistThreadExplorerSelectionPreference(selectedUri);
  renderThreadExplorerWorkspace();
  scheduleThreadExplorerSelectedFocus();
}

/**
 * Creates one absolute-positioned reply-cluster item from the shared node template.
 * @param {object} node - Normalized Thread Explorer node for this cluster card.
 * @param {number} centerX - X center position in stage space.
 * @param {number} centerY - Y center position in stage space.
 * @param {string} role - Visual role such as "center", "parent" or "reply".
 * @returns {HTMLElement} Rendered absolute-positioned cluster item.
 */
function createThreadExplorerReplyClusterItem(node, centerX, centerY, role) {
  const renderedItem = createThreadExplorerRenderedItem(node, {
    renderReplies: false,
    showToggle: true,
  });
  const item = renderedItem.item;
  item.classList.add("thread-explorer-cluster-node-item");
  item.classList.add(`is-cluster-${role}`);
  item.style.setProperty("--thread-explorer-cluster-x", `${Math.round(centerX)}px`);
  item.style.setProperty("--thread-explorer-cluster-y", `${Math.round(centerY)}px`);
  return item;
}

/**
 * Creates one recursive reply-cluster render node for the expanded cluster tree.
 * @param {object|null} node - Normalized Thread Explorer tree node.
 * @returns {object|null} Recursive render node with rendered item and expanded children.
 */
function createThreadExplorerReplyClusterRenderNode(node) {
  if (!node || !node.post?.uri) {
    return null;
  }

  let role = "reply";
  if (node.post?.uri === threadExplorerTree?.post?.uri) {
    role = "center";
  }
  const item = createThreadExplorerReplyClusterItem(node, 0, 0, role);
  const renderNode = {
    node,
    item,
    children: [],
    subtreeWidth: 0,
    subtreeHeight: 0,
    position: {
      x: 0,
      y: 0,
    },
  };

  if (!isThreadExplorerReplyClusterExpanded(node.post.uri)) {
    return renderNode;
  }

  const replies = getChronologicalThreadExplorerReplies(node.replies);
  replies.forEach((reply) => {
    const childRenderNode = createThreadExplorerReplyClusterRenderNode(reply);
    if (childRenderNode) {
      renderNode.children.push(childRenderNode);
    }
  });
  return renderNode;
}

/**
 * Appends one curved cluster edge between two cluster anchor points.
 * @param {SVGElement} svg - Target SVG edge layer.
 * @param {{x:number, y:number}} start - Edge start point.
 * @param {{x:number, y:number}} end - Edge end point.
 * @param {string} edgeClassName - Additional CSS class for this edge.
 * @returns {void}
 */
function appendThreadExplorerReplyClusterEdge(svg, start, end, edgeClassName) {
  if (!svg) {
    return;
  }

  const path = createSvgNode("path", {
    class: `thread-explorer-edge ${edgeClassName}`.trim(),
    d: `M ${start.x} ${start.y} C ${start.x} ${start.y + ((end.y - start.y) * 0.35)}, ${end.x} ${end.y - ((end.y - start.y) * 0.35)}, ${end.x} ${end.y}`,
  });
  svg.appendChild(path);
}

/**
 * Renders the reply-cluster layout around the currently selected or contextual post.
 * @returns {void}
 */
function renderThreadExplorerReplyCluster() {
  if (!threadExplorerTree) {
    return;
  }

  ensureThreadExplorerReplyClusterRootExpanded();
  const rootRenderNode = createThreadExplorerReplyClusterRenderNode(threadExplorerTree);
  if (!rootRenderNode) {
    return;
  }

  const cluster = document.createElement("div");
  cluster.className = "thread-explorer-reply-cluster";
  cluster.style.width = "1120px";
  cluster.style.height = "860px";

  const edgeLayer = createSvgNode("svg", {
    class: "thread-explorer-reply-cluster-edge-layer",
    width: 1120,
    height: 860,
    viewBox: "0 0 1120 860",
    "aria-hidden": "true",
    focusable: "false",
  });
  cluster.appendChild(edgeLayer);

  const pendingNodes = [rootRenderNode];
  while (pendingNodes.length > 0) {
    const currentNode = pendingNodes.shift();
    if (!currentNode) {
      continue;
    }

    cluster.appendChild(currentNode.item);
    if (Array.isArray(currentNode.children) && currentNode.children.length > 0) {
      currentNode.children.forEach((childNode) => {
        pendingNodes.push(childNode);
      });
    }
  }

  threadExplorerReplyClusterLayoutState = {
    cluster,
    edgeLayer,
    rootRenderNode,
    positionedItems: [],
  };
  threadExplorerThreadStage.classList.add("is-reply-cluster-mode");
  threadExplorerThreadStage.appendChild(cluster);
  layoutThreadExplorerReplyCluster(threadExplorerReplyClusterLayoutState);
}

/**
 * Toggles the clicked Thread Explorer node button.
 * @param {Event} event - Click event from a node toggle button.
 * @returns {void}
 */
function handleThreadExplorerNodeToggleClick(event) {
  const button = event.currentTarget;
  const uri = String(button?.dataset?.uri || "").trim();
  if (isThreadExplorerReplyClusterModeActive()) {
    toggleThreadExplorerReplyClusterNode(uri);
    return;
  }
  toggleThreadExplorerNode(uri);
}

/**
 * Applies preview-shape classes for one Thread Explorer post image.
 * @param {HTMLImageElement|null} image - Loaded image element inside the preview figure.
 * @param {HTMLElement|null} figure - Figure wrapper around the image.
 * @param {HTMLElement|null} gallery - Gallery container that owns the image.
 * @returns {void}
 */
function applyThreadExplorerPostImagePreviewShape(image = null, figure = null, gallery = null) {
  if (!image || !figure || !gallery) {
    return;
  }

  figure.classList.remove("is-portrait", "is-landscape", "is-square");
  gallery.classList.remove(
    "has-single-thread-image",
    "has-single-thread-image-portrait",
    "has-single-thread-image-landscape",
    "has-single-thread-image-square",
    "has-multiple-thread-images",
  );

  const imageCount = Math.max(0, Number(gallery.dataset.imageCount) || 0);
  if (imageCount === 1) {
    gallery.classList.add("has-single-thread-image");
  } else if (imageCount > 1) {
    gallery.classList.add("has-multiple-thread-images");
  }

  const naturalWidth = Math.max(0, Number(image.naturalWidth) || 0);
  const naturalHeight = Math.max(0, Number(image.naturalHeight) || 0);
  if (!naturalWidth || !naturalHeight) {
    return;
  }

  if (naturalHeight > naturalWidth * 1.08) {
    figure.classList.add("is-portrait");
    if (imageCount === 1) {
      gallery.classList.add("has-single-thread-image-portrait");
    }
    return;
  }

  if (naturalWidth > naturalHeight * 1.08) {
    figure.classList.add("is-landscape");
    if (imageCount === 1) {
      gallery.classList.add("has-single-thread-image-landscape");
    }
    return;
  }

  figure.classList.add("is-square");
  if (imageCount === 1) {
    gallery.classList.add("has-single-thread-image-square");
  }
}

/**
 * Copies gallery image-shape classes onto the surrounding Thread Explorer post card.
 * @param {HTMLElement|null} card - Rendered Thread Explorer post card.
 * @param {HTMLElement|null} gallery - Gallery inside the post card.
 * @returns {void}
 */
function syncThreadExplorerPostCardImageShape(card = null, gallery = null) {
  if (!card || !gallery) {
    return;
  }

  card.classList.remove(
    "has-single-thread-image",
    "has-single-thread-image-portrait",
    "has-single-thread-image-landscape",
    "has-single-thread-image-square",
    "has-multiple-thread-images",
  );

  if (gallery.classList.contains("has-single-thread-image")) {
    card.classList.add("has-single-thread-image");
  }
  if (gallery.classList.contains("has-single-thread-image-portrait")) {
    card.classList.add("has-single-thread-image-portrait");
  }
  if (gallery.classList.contains("has-single-thread-image-landscape")) {
    card.classList.add("has-single-thread-image-landscape");
  }
  if (gallery.classList.contains("has-single-thread-image-square")) {
    card.classList.add("has-single-thread-image-square");
  }
  if (gallery.classList.contains("has-multiple-thread-images")) {
    card.classList.add("has-multiple-thread-images");
  }

  const node = card.closest(".thread-explorer-node");
  if (!node) {
    return;
  }

  node.classList.remove(
    "has-single-thread-image",
    "has-single-thread-image-portrait",
    "has-single-thread-image-landscape",
    "has-single-thread-image-square",
    "has-multiple-thread-images",
  );

  if (gallery.classList.contains("has-single-thread-image")) {
    node.classList.add("has-single-thread-image");
  }
  if (gallery.classList.contains("has-single-thread-image-portrait")) {
    node.classList.add("has-single-thread-image-portrait");
  }
  if (gallery.classList.contains("has-single-thread-image-landscape")) {
    node.classList.add("has-single-thread-image-landscape");
  }
  if (gallery.classList.contains("has-single-thread-image-square")) {
    node.classList.add("has-single-thread-image-square");
  }
  if (gallery.classList.contains("has-multiple-thread-images")) {
    node.classList.add("has-multiple-thread-images");
  }
}

/**
 * Renders post images into a Thread Explorer gallery element.
 * @param {object} post - Normalized Thread Explorer post.
 * @param {HTMLElement} gallery - Gallery container element.
 * @returns {void}
 */
function renderThreadExplorerImages(post, gallery) {
  gallery.replaceChildren();
  let images = [];
  if (Array.isArray(post.images)) {
    images = post.images;
  }
  gallery.dataset.imageCount = String(images.length);
  images.forEach((image, imageIndex) => {
    const fragment = threadExplorerImageTemplate.content.cloneNode(true);
    const figure = fragment.querySelector(".thread-explorer-image");
    const button = fragment.querySelector(".thread-explorer-image-button");
    const img = fragment.querySelector("img");
    const caption = fragment.querySelector("figcaption");
    const source = image.fullsize || image.thumb || "";
    const thumb = image.thumb || source;
    setThreadExplorerCachedImageSource(img, source, thumb);
    img.alt = image.alt || "";
    img.addEventListener("load", () => {
      applyThreadExplorerPostImagePreviewShape(img, figure, gallery);
      syncThreadExplorerPostCardImageShape(gallery.closest(".thread-explorer-post-card"), gallery);
      refreshThreadExplorerRenderedGeometry();
    }, { once: true });
    attachThreadExplorerRenderedMediaCacheHandlers(img, handleThreadExplorerPostImageError);
    button.addEventListener("click", () => {
      openThreadExplorerGallery(images, imageIndex);
    });
    caption.textContent = image.alt || "";
    caption.hidden = !image.alt;
    gallery.appendChild(figure);
    if (img.complete) {
      applyThreadExplorerPostImagePreviewShape(img, figure, gallery);
      syncThreadExplorerPostCardImageShape(gallery.closest(".thread-explorer-post-card"), gallery);
      refreshThreadExplorerRenderedGeometry();
    }
  });
  gallery.hidden = images.length === 0;
}

/**
 * Returns a likely favicon URL for a link-card URI.
 * @param {string} uri - External link URI from a Bluesky embed.
 * @returns {string} Absolute favicon URL, or an empty string when the URI is invalid.
 */
function getThreadExplorerFaviconUrl(uri) {
  try {
    const parsed = new URL(uri);
    return `${parsed.origin}/favicon.ico`;
  } catch (error) {
    return "";
  }
}

/**
 * Hides a Thread Explorer link-card image when its fallback asset cannot load.
 * @param {Event} event - Image error event.
 * @returns {void}
 */
function handleThreadExplorerLinkImageError(event) {
  const image = event.currentTarget;
  const card = image.closest(".thread-explorer-link-card");
  image.hidden = true;
  image.removeAttribute("src");
  if (card) {
    card.classList.add("has-no-thumb");
    card.classList.remove("has-favicon-thumb");
  }
  refreshThreadExplorerRenderedGeometry();
}

/**
 * Hides a failed Thread Explorer quoted link-card thumbnail.
 * @param {Event} event - Image error event.
 * @returns {void}
 */
function handleThreadExplorerQuoteLinkImageError(event) {
  const image = event.currentTarget;
  const card = image.closest(".thread-explorer-quote-link-card");
  image.hidden = true;
  image.removeAttribute("src");
  if (card) {
    card.classList.add("has-no-thumb");
    card.classList.remove("has-favicon-thumb");
  }
  refreshThreadExplorerRenderedGeometry();
}

/**
 * Renders a post external card into a Thread Explorer node fragment.
 * @param {object} post - Normalized Thread Explorer post.
 * @param {DocumentFragment} fragment - Node template fragment.
 * @returns {void}
 */
function renderThreadExplorerExternalCard(post, fragment) {
  const card = fragment.querySelector(".thread-explorer-link-card");
  const image = fragment.querySelector(".thread-explorer-link-card-image");
  const title = fragment.querySelector(".thread-explorer-link-card-title");
  const description = fragment.querySelector(".thread-explorer-link-card-description");
  const url = fragment.querySelector(".thread-explorer-link-card-url");
  const external = post.externalCard;

  if (!external || !external.uri) {
    card.hidden = true;
    card.classList.remove("is-publication");
    return;
  }

  const standardSite = normalizeStandardSiteMetadata(external.standardSite);
  card.hidden = false;
  if (standardSite) {
    card.classList.add("is-publication");
  } else {
    card.classList.remove("is-publication");
  }
  card.href = external.uri;
  image.removeEventListener("error", handleThreadExplorerLinkImageError);
  image.addEventListener("error", handleThreadExplorerLinkImageError);
  image.addEventListener("load", () => {
    cacheThreadExplorerRenderedMediaImage(image);
    refreshThreadExplorerRenderedGeometry();
  }, { once: true });
  if (external.thumb) {
    card.classList.remove("has-no-thumb");
    card.classList.remove("has-favicon-thumb");
    image.hidden = false;
    setThreadExplorerCachedImageSource(image, external.thumb);
  } else {
    const faviconUrl = getThreadExplorerFaviconUrl(external.uri);
    if (faviconUrl) {
      card.classList.remove("has-no-thumb");
      card.classList.add("has-favicon-thumb");
      image.hidden = false;
      setThreadExplorerCachedImageSource(image, faviconUrl);
    } else {
      card.classList.add("has-no-thumb");
      card.classList.remove("has-favicon-thumb");
      image.hidden = true;
      delete image.dataset.snapshotSource;
      delete image.dataset.snapshotThumb;
      delete image.dataset.snapshotHydrated;
      image.removeAttribute("src");
    }
  }
  title.textContent = external.title || external.uri;
  description.textContent = external.description || "";
  const publicationFooterLabel = getPublicationCardFooterLabel(standardSite);
  if (publicationFooterLabel) {
    url.textContent = `${shortenThreadExplorerUrlForDisplay(external.uri)} - ${publicationFooterLabel}`;
  } else {
    url.textContent = shortenThreadExplorerUrlForDisplay(external.uri);
  }
}

/**
 * Renders preview images from a quoted Thread Explorer post.
 * @param {object} quote - Normalized quoted post.
 * @param {HTMLElement|null} gallery - Target gallery element inside the quote card.
 * @returns {void}
 */
function renderThreadExplorerQuoteImages(quote, gallery) {
  if (!gallery) {
    return;
  }

  gallery.replaceChildren();
  let images = [];
  if (Array.isArray(quote?.images)) {
    images = quote.images;
  }
  gallery.dataset.imageCount = String(images.length);

  images.slice(0, 4).forEach((image, imageIndex) => {
    const img = document.createElement("img");
    const source = image.thumb || image.fullsize || "";
    setThreadExplorerCachedImageSource(img, source);
    img.alt = image.alt || "";
    img.loading = "lazy";
    img.addEventListener("load", () => {
      applyThreadExplorerPostImagePreviewShape(img, img, gallery);
      refreshThreadExplorerRenderedGeometry();
    }, { once: true });
    attachThreadExplorerRenderedMediaCacheHandlers(img, handleThreadExplorerQuoteImageError);
    img.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openThreadExplorerGallery(images, imageIndex);
    });
    gallery.appendChild(img);
    if (img.complete) {
      applyThreadExplorerPostImagePreviewShape(img, img, gallery);
      refreshThreadExplorerRenderedGeometry();
    }
  });

  gallery.hidden = images.length === 0;
}

/**
 * Renders a quoted post's external link card preview.
 * @param {object} quote - Normalized quoted post.
 * @param {DocumentFragment} fragment - Node template fragment.
 * @returns {void}
 */
function renderThreadExplorerQuoteExternalCard(quote, fragment) {
  const card = fragment.querySelector(".thread-explorer-quote-link-card");
  const image = fragment.querySelector(".thread-explorer-quote-link-card-image");
  const title = fragment.querySelector(".thread-explorer-quote-link-card-title");
  const description = fragment.querySelector(".thread-explorer-quote-link-card-description");
  const url = fragment.querySelector(".thread-explorer-quote-link-card-url");
  const external = quote?.externalCard;

  if (!card || !external || !external.uri) {
    if (card) {
      card.hidden = true;
      card.classList.remove("is-publication");
    }
    return;
  }

  const standardSite = normalizeStandardSiteMetadata(external.standardSite);
  card.hidden = false;
  if (standardSite) {
    card.classList.add("is-publication");
  } else {
    card.classList.remove("is-publication");
  }
  image.removeEventListener("error", handleThreadExplorerQuoteLinkImageError);
  image.addEventListener("error", handleThreadExplorerQuoteLinkImageError);
  image.addEventListener("load", () => {
    cacheThreadExplorerRenderedMediaImage(image);
    refreshThreadExplorerRenderedGeometry();
  }, { once: true });
  if (external.thumb) {
    card.classList.remove("has-no-thumb");
    card.classList.remove("has-favicon-thumb");
    image.hidden = false;
    setThreadExplorerCachedImageSource(image, external.thumb);
  } else {
    const faviconUrl = getThreadExplorerFaviconUrl(external.uri);
    if (faviconUrl) {
      card.classList.remove("has-no-thumb");
      card.classList.add("has-favicon-thumb");
      image.hidden = false;
      setThreadExplorerCachedImageSource(image, faviconUrl);
    } else {
      card.classList.add("has-no-thumb");
      card.classList.remove("has-favicon-thumb");
      image.hidden = true;
      delete image.dataset.snapshotSource;
      delete image.dataset.snapshotThumb;
      delete image.dataset.snapshotHydrated;
      image.removeAttribute("src");
    }
  }
  title.textContent = external.title || external.uri;
  description.textContent = external.description || "";
  const publicationFooterLabel = getPublicationCardFooterLabel(standardSite);
  if (publicationFooterLabel) {
    url.textContent = `${shortenThreadExplorerUrlForDisplay(external.uri)} - ${publicationFooterLabel}`;
  } else {
    url.textContent = shortenThreadExplorerUrlForDisplay(external.uri);
  }
}

/**
 * Renders a quoted post card into a Thread Explorer node fragment.
 * @param {object} post - Normalized Thread Explorer post.
 * @param {DocumentFragment} fragment - Node template fragment.
 * @returns {void}
 */
function renderThreadExplorerQuoteCard(post, fragment) {
  const card = fragment.querySelector(".thread-explorer-quote-card");
  const avatar = fragment.querySelector(".thread-explorer-quote-card-avatar");
  const author = fragment.querySelector(".thread-explorer-quote-card-author");
  const handle = fragment.querySelector(".thread-explorer-quote-card-handle");
  const text = fragment.querySelector(".thread-explorer-quote-card-text");
  const gallery = fragment.querySelector(".thread-explorer-quote-card-gallery");
  const meta = fragment.querySelector(".thread-explorer-quote-card-meta");
  const quote = post.quoteCard;

  if (!quote || !quote.uri) {
    card.hidden = true;
    return;
  }

  const url = buildThreadExplorerPostWebUrl(quote);
  if (!url) {
    card.hidden = true;
    return;
  }

  card.hidden = false;
  card.href = url;
  card.title = t("searchResultOpenInThreadExplorerButton");
  card.setAttribute("aria-label", t("searchResultOpenInThreadExplorerButton"));
  card.addEventListener("click", (event) => {
    event.preventDefault();
    void selectThreadExplorerPost(quote.uri);
  });
  markThreadExplorerAvatarImage(avatar, quote.author);
  setAvatarImage(avatar, getThreadExplorerActorAvatarUri(quote.author), getThreadExplorerActorLabel(quote.author));
  author.textContent = getThreadExplorerActorLabel(quote.author);
  if (quote.author?.handle) {
    handle.textContent = `@${quote.author.handle}`;
  } else {
    handle.textContent = quote.author?.did || "";
  }
  text.textContent = quote.text || t("threadExplorerNoText");
  renderThreadExplorerQuoteImages(quote, gallery);
  renderThreadExplorerQuoteExternalCard(quote, fragment);
  let metaText = formatThreadExplorerDate(quote.createdAt || quote.indexedAt);
  if (quote.editInfo?.isEdited === true) {
    metaText = `${metaText} - ${t("threadExplorerEditedBadge")}`.trim();
  }
  meta.textContent = metaText;
}

/**
 * Loads the Thread Explorer feed through the Service Worker.
 * @param {object} options - Set reset true to reload from the beginning.
 * @returns {Promise<void>} Resolves when the feed is rendered.
 */
async function loadThreadExplorerFeed(options = {}) {
  if (!authAccount || threadExplorerLoadingFeed) {
    return;
  }
  const isForeignAccountMode = isThreadExplorerForeignAccountMode();
  const append = options.append === true;
  if (append && !threadExplorerHasMore) {
    return;
  }

  if (options.reset === true) {
    threadExplorerCursor = "";
    threadExplorerHasMore = true;
    threadExplorerItems = [];
  }
  if (options.clearSelection === true) {
    threadExplorerSelectedUri = "";
    threadExplorerTree = null;
    clearThreadExplorerRenderedMediaCache();
    threadExplorerCollapsedUris.clear();
    clearThreadExplorerSelectionPreference();
  }
  threadExplorerFeedError = "";
  threadExplorerThreadError = "";
  threadExplorerAccountError = "";

  threadExplorerLoadingFeed = true;
  renderThreadExplorerWorkspace();
  try {
    let result = null;
    if (isForeignAccountMode) {
      result = await sendToServiceWorker("LOAD_THREAD_EXPLORER_ACTOR_FEED", {
        actor: getThreadExplorerRequestedActor(),
        cursor: threadExplorerCursor,
        mode: normalizeThreadExplorerAccountMode(threadExplorerAccountMode),
        limit: 50,
      }, {
        timeoutMs: 120000,
      });
    } else {
      const searchId = getThreadExplorerSearchIdFromSource(threadExplorerSource);
      const savedSearch = getSavedSearchById(searchId);
      result = await sendToServiceWorker("LOAD_THREAD_EXPLORER_FEED", {
        source: threadExplorerSource,
        cursor: threadExplorerCursor,
        limit: 50,
        search: savedSearch?.params || null,
      }, {
        timeoutMs: 120000,
      });
    }
    threadExplorerCursor = String(result?.cursor || "");
    threadExplorerHasMore = Boolean(threadExplorerCursor);
    if (Array.isArray(result?.items)) {
      if (append) {
        threadExplorerItems = appendThreadExplorerFeedItems(threadExplorerItems, result.items, {
          groupByRoot: !isForeignAccountMode && Boolean(getThreadExplorerSearchIdFromSource(threadExplorerSource)),
        });
        threadExplorerItems = sortThreadExplorerFeedItemsByDate(threadExplorerItems);
      } else {
        threadExplorerItems = sortThreadExplorerFeedItemsByDate(result.items);
      }
    } else {
      if (!append) {
        threadExplorerItems = [];
      }
    }
    if (!append) {
      const selectionUri = getThreadExplorerPreferredSelectionUri({
        allowStoredOutsideFeed: options.clearSelection !== true,
      });
      if (selectionUri) {
        await selectThreadExplorerPost(selectionUri);
      }
    }
  } catch (error) {
    const message = error?.message || t("threadExplorerFeedFailed");
    threadExplorerFeedError = message;
    if (isForeignAccountMode) {
      threadExplorerAccountError = message;
    }
  } finally {
    threadExplorerLoadingFeed = false;
    renderThreadExplorerWorkspace();
  }
}

/**
 * Loads and renders one live thread for a selected post URI.
 * @param {string} uri - AT URI of the selected post.
 * @returns {Promise<void>} Resolves when the thread tree is rendered.
 */
async function selectThreadExplorerPost(uri) {
  const selectedUri = String(uri || "").trim();
  if (!selectedUri || threadExplorerLoadingThread) {
    return;
  }

  threadExplorerSelectedUri = selectedUri;
  persistThreadExplorerSelectionPreference(selectedUri);
  threadExplorerLoadingThread = true;
  threadExplorerCardZoomState = null;
  threadExplorerTree = null;
  clearThreadExplorerRenderedMediaCache();
  threadExplorerThreadError = "";
  renderThreadExplorerWorkspace();
  try {
    const result = await sendToServiceWorker("LOAD_THREAD_EXPLORER_THREAD", {
      uri: selectedUri,
    }, {
      timeoutMs: 120000,
    });
    threadExplorerTree = result?.root || null;
    if (threadExplorerTree && isThreadExplorerReplyClusterModeActive()) {
      threadExplorerReplyClusterExpandedUris.clear();
      expandAllThreadExplorerReplyClusterNodes(threadExplorerTree);
    }
  } catch (error) {
    threadExplorerThreadError = error.message || t("threadExplorerThreadFailed");
  } finally {
    threadExplorerLoadingThread = false;
    renderThreadExplorerWorkspace();
    if (threadExplorerTree) {
      scheduleThreadExplorerSelectedFocus();
    }
  }
}

/**
 * Schedules a reliable focus pass for the currently selected Thread Explorer node.
 * @returns {void}
 */
function scheduleThreadExplorerSelectedFocus() {
  window.requestAnimationFrame(() => {
    window.requestAnimationFrame(() => {
      focusSelectedThreadExplorerNode();
      window.setTimeout(focusSelectedThreadExplorerNode, 80);
    });
  });
}

/**
 * Toggles collapsed state for a rendered Thread Explorer node.
 * @param {string} uri - AT URI of the node to toggle.
 * @returns {void}
 */
function toggleThreadExplorerNode(uri) {
  const normalizedUri = String(uri || "").trim();
  if (!normalizedUri) {
    return;
  }
  if (threadExplorerCollapsedUris.has(normalizedUri)) {
    threadExplorerCollapsedUris.delete(normalizedUri);
  } else {
    threadExplorerCollapsedUris.add(normalizedUri);
  }
  renderThreadExplorerTree();
}

/**
 * Scrolls the Thread Explorer tree to its root node.
 * @returns {void}
 */
function scrollThreadExplorerToRoot() {
  if (isThreadExplorerReplyClusterModeActive()) {
    const rootUri = String(threadExplorerTree?.post?.uri || "").trim();
    if (rootUri) {
      const rootItem = findRenderedThreadExplorerNode(rootUri);
      if (rootItem) {
        scrollThreadExplorerNodeIntoView(rootItem, {
          block: "center",
          inline: "center",
        });
      }
    }
    return;
  }
  const firstNode = threadExplorerThreadTree.querySelector(".thread-explorer-node-item");
  if (!firstNode) {
    return;
  }

  scrollThreadExplorerNodeIntoView(firstNode, {
    block: "center",
    inline: "center",
  });
}

/**
 * Scrolls one rendered Thread Explorer node into the viewport.
 * @param {HTMLElement} item - Rendered node item to reveal.
 * @param {object} options - Scroll placement options.
 * @param {string} options.block - Vertical placement: "start" or "center".
 * @param {string} options.inline - Horizontal placement: "start" or "center".
 * @returns {void}
 */
function scrollThreadExplorerNodeIntoView(item, options = {}) {
  if (!item) {
    return;
  }

  const viewportRect = threadExplorerThreadTree.getBoundingClientRect();
  const target = getRenderedThreadExplorerCard(item) || item;
  const targetRect = target.getBoundingClientRect();
  const targetWidth = targetRect.width;
  const targetHeight = targetRect.height;
  const visibleWidth = threadExplorerThreadTree.clientWidth;
  const visibleHeight = threadExplorerThreadTree.clientHeight;
  let desiredLeft = 24;
  let desiredTop = 24;
  if (options.inline === "center") {
    desiredLeft = (visibleWidth - targetWidth) / 2;
  }
  if (options.block === "center") {
    desiredTop = (visibleHeight - targetHeight) / 2;
  }
  threadExplorerPanX += desiredLeft - (targetRect.left - viewportRect.left);
  threadExplorerPanY += desiredTop - (targetRect.top - viewportRect.top);
  applyThreadExplorerStageTransform();
  scheduleThreadExplorerEdgeRender();
}

/**
 * Finds a rendered Thread Explorer node item by exact post URI.
 * @param {string} uri - AT URI to locate in the rendered tree.
 * @returns {HTMLElement|null} Matching rendered node item, or null.
 */
function findRenderedThreadExplorerNode(uri) {
  const normalizedUri = String(uri || "").trim();
  if (!normalizedUri) {
    return null;
  }

  const items = threadExplorerThreadStage.querySelectorAll(".thread-explorer-node-item");
  for (const item of items) {
    if (item.dataset.uri === normalizedUri) {
      return item;
    }
  }
  return null;
}

/**
 * Measures one rendered Thread Explorer element in untransformed stage coordinates.
 * @param {HTMLElement|null} element - Rendered stage element to measure.
 * @returns {{left:number, top:number, width:number, height:number}|null} Stage-space box or null when unavailable.
 */
function getThreadExplorerStageBox(element = null) {
  if (!element) {
    return null;
  }

  const rect = element.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0) {
    return null;
  }

  const viewportRect = threadExplorerThreadTree.getBoundingClientRect();
  let zoom = Number(threadExplorerZoom) || 1;
  if (zoom <= 0) {
    zoom = 1;
  }

  return {
    left: (rect.left - viewportRect.left - threadExplorerPanX) / zoom,
    top: (rect.top - viewportRect.top - threadExplorerPanY) / zoom,
    width: rect.width / zoom,
    height: rect.height / zoom,
  };
}

/**
 * Collects the complete bounds of the rendered Thread Explorer tree in stage coordinates.
 * @returns {{left:number, top:number, width:number, height:number}|null} Bounding box for the visible tree.
 */
function getThreadExplorerStageContentBounds() {
  const cards = Array.from(threadExplorerThreadStage.querySelectorAll(".thread-explorer-post-card"));
  if (!cards.length) {
    return null;
  }

  let minLeft = Number.POSITIVE_INFINITY;
  let minTop = Number.POSITIVE_INFINITY;
  let maxRight = Number.NEGATIVE_INFINITY;
  let maxBottom = Number.NEGATIVE_INFINITY;

  cards.forEach((card) => {
    const box = getThreadExplorerStageBox(card);
    if (!box) {
      return;
    }
    minLeft = Math.min(minLeft, box.left);
    minTop = Math.min(minTop, box.top);
    maxRight = Math.max(maxRight, box.left + box.width);
    maxBottom = Math.max(maxBottom, box.top + box.height);
  });

  if (!Number.isFinite(minLeft) || !Number.isFinite(minTop) || !Number.isFinite(maxRight) || !Number.isFinite(maxBottom)) {
    return null;
  }

  return {
    left: minLeft,
    top: minTop,
    width: Math.max(1, maxRight - minLeft),
    height: Math.max(1, maxBottom - minTop),
  };
}

/**
 * Merges one stage-space box into an accumulated bounding box.
 * @param {{left:number, top:number, width:number, height:number}|null} accumulatedBounds - Existing bounds.
 * @param {{left:number, top:number, width:number, height:number}|null} nextBounds - Box that should extend the bounds.
 * @returns {{left:number, top:number, width:number, height:number}|null} Combined bounds or null when nothing was available.
 */
function mergeThreadExplorerStageBounds(accumulatedBounds, nextBounds) {
  if (!nextBounds) {
    return accumulatedBounds;
  }
  if (!accumulatedBounds) {
    return {
      left: nextBounds.left,
      top: nextBounds.top,
      width: nextBounds.width,
      height: nextBounds.height,
    };
  }

  const left = Math.min(accumulatedBounds.left, nextBounds.left);
  const top = Math.min(accumulatedBounds.top, nextBounds.top);
  const right = Math.max(accumulatedBounds.left + accumulatedBounds.width, nextBounds.left + nextBounds.width);
  const bottom = Math.max(accumulatedBounds.top + accumulatedBounds.height, nextBounds.top + nextBounds.height);
  return {
    left,
    top,
    width: Math.max(1, right - left),
    height: Math.max(1, bottom - top),
  };
}

/**
 * Applies a viewport fit to one stage-space bounds box.
 * @param {{left:number, top:number, width:number, height:number}|null} bounds - Stage-space bounds to reveal.
 * @param {object} [options] - Optional zoom limits for this fit.
 * @param {number} [options.minZoom] - Minimum zoom that should be enforced.
 * @param {number} [options.maxZoom] - Maximum zoom that should be enforced.
 * @returns {void}
 */
function fitThreadExplorerStageToBounds(bounds, options = {}) {
  if (!bounds) {
    return;
  }

  const viewportWidth = Math.max(1, threadExplorerThreadTree.clientWidth);
  const viewportHeight = Math.max(1, threadExplorerThreadTree.clientHeight);
  const paddingX = Math.max(40, viewportWidth * 0.1);
  const paddingY = Math.max(40, viewportHeight * 0.12);
  const availableWidth = Math.max(1, viewportWidth - (paddingX * 2));
  const availableHeight = Math.max(1, viewportHeight - (paddingY * 2));
  const zoomByWidth = availableWidth / bounds.width;
  const zoomByHeight = availableHeight / bounds.height;
  let minimumZoom = Number(options.minZoom);
  if (!Number.isFinite(minimumZoom)) {
    minimumZoom = 0.08;
  }
  let maximumZoom = Number(options.maxZoom);
  if (!Number.isFinite(maximumZoom)) {
    maximumZoom = 1.85;
  }
  const fittedZoom = Math.min(zoomByWidth, zoomByHeight);
  const nextZoom = Math.min(maximumZoom, Math.max(minimumZoom, fittedZoom));

  threadExplorerZoom = nextZoom;
  threadExplorerPanX = ((viewportWidth - (bounds.width * nextZoom)) / 2) - (bounds.left * nextZoom);
  threadExplorerPanY = ((viewportHeight - (bounds.height * nextZoom)) / 2) - (bounds.top * nextZoom);
  applyThreadExplorerStageTransform();
  scheduleThreadExplorerEdgeRender();
}

/**
 * Fits the complete rendered Thread Explorer tree into the visible viewport.
 * @returns {void}
 */
function fitThreadExplorerStageToTree() {
  threadExplorerCardZoomState = null;
  const bounds = getThreadExplorerStageContentBounds();
  if (!bounds) {
    return;
  }

  fitThreadExplorerStageToBounds(bounds);
}

/**
 * Scrolls the selected Thread Explorer post into the center of the viewport.
 * @returns {void}
 */
function focusSelectedThreadExplorerNode() {
  if (isThreadExplorerReplyClusterModeActive()) {
    const clusterUri = String(threadExplorerSelectedUri || threadExplorerTree?.post?.uri || "").trim();
    if (!clusterUri) {
      return;
    }

    const clusterItem = findRenderedThreadExplorerNode(clusterUri);
    if (!clusterItem) {
      return;
    }

    scrollThreadExplorerNodeIntoView(clusterItem, {
      block: "center",
      inline: "center",
    });
    return;
  }
  const rootUri = String(threadExplorerTree?.post?.uri || "").trim();
  if (rootUri && rootUri === threadExplorerSelectedUri) {
    scrollThreadExplorerToRoot();
    return;
  }

  const item = findRenderedThreadExplorerNode(threadExplorerSelectedUri);
  if (!item) {
    return;
  }
  scrollThreadExplorerNodeIntoView(item, {
    block: "center",
    inline: "center",
  });
}

/**
 * Finds one rendered reply-cluster node inside the current cluster layout state.
 * @param {string} uri - AT URI of the wanted reply-cluster node.
 * @param {object|null} renderNode - Recursive reply-cluster render node.
 * @returns {object|null} Matching reply-cluster render node or null.
 */
function findThreadExplorerReplyClusterRenderNode(uri, renderNode) {
  const normalizedUri = String(uri || "").trim();
  if (!normalizedUri || !renderNode) {
    return null;
  }

  if (String(renderNode?.node?.post?.uri || "").trim() === normalizedUri) {
    return renderNode;
  }

  const children = Array.isArray(renderNode.children) ? renderNode.children : [];
  for (const childNode of children) {
    const matchingNode = findThreadExplorerReplyClusterRenderNode(normalizedUri, childNode);
    if (matchingNode) {
      return matchingNode;
    }
  }
  return null;
}

/**
 * Collects one stage-space bounds box for a rendered card and its direct replies in tree view.
 * @param {HTMLElement|null} item - Rendered Thread Explorer node item.
 * @returns {{left:number, top:number, width:number, height:number}|null} Combined bounds or null.
 */
function getThreadExplorerTreeCardNeighborhoodBounds(item) {
  if (!item) {
    return null;
  }

  let combinedBounds = null;
  const ownCard = getRenderedThreadExplorerCard(item) || item;
  combinedBounds = mergeThreadExplorerStageBounds(combinedBounds, getThreadExplorerStageBox(ownCard));

  const childCards = item.querySelectorAll(":scope > .thread-explorer-children > .thread-explorer-node-item > .thread-explorer-node > .thread-explorer-post-card");
  childCards.forEach((childCard) => {
    combinedBounds = mergeThreadExplorerStageBounds(combinedBounds, getThreadExplorerStageBox(childCard));
  });
  return combinedBounds;
}

/**
 * Collects one stage-space bounds box for a rendered card and its direct replies in reply-cluster view.
 * @param {string} uri - AT URI of the clicked post card.
 * @returns {{left:number, top:number, width:number, height:number}|null} Combined bounds or null.
 */
function getThreadExplorerReplyClusterCardNeighborhoodBounds(uri) {
  const rootRenderNode = threadExplorerReplyClusterLayoutState?.rootRenderNode || null;
  const targetNode = findThreadExplorerReplyClusterRenderNode(uri, rootRenderNode);
  if (!targetNode) {
    return null;
  }

  let combinedBounds = null;
  combinedBounds = mergeThreadExplorerStageBounds(combinedBounds, getThreadExplorerStageBox(getRenderedThreadExplorerCard(targetNode.item) || targetNode.item));
  const children = Array.isArray(targetNode.children) ? targetNode.children : [];
  children.forEach((childNode) => {
    combinedBounds = mergeThreadExplorerStageBounds(combinedBounds, getThreadExplorerStageBox(getRenderedThreadExplorerCard(childNode.item) || childNode.item));
  });
  return combinedBounds;
}

/**
 * Collects one stage-space bounds box for the clicked post card and its immediate reply neighborhood.
 * @param {HTMLElement|null} item - Rendered Thread Explorer node item.
 * @returns {{left:number, top:number, width:number, height:number}|null} Combined bounds or null.
 */
function getThreadExplorerCardNeighborhoodBounds(item) {
  const uri = String(item?.dataset?.uri || "").trim();
  if (!uri) {
    return null;
  }

  if (isThreadExplorerReplyClusterModeActive()) {
    return getThreadExplorerReplyClusterCardNeighborhoodBounds(uri);
  }
  return getThreadExplorerTreeCardNeighborhoodBounds(item);
}

/**
 * Restores the viewport that was active before the last Thread Explorer card zoom.
 * @returns {void}
 */
function restoreThreadExplorerCardZoomState() {
  if (!threadExplorerCardZoomState) {
    return;
  }

  threadExplorerZoom = threadExplorerCardZoomState.zoom;
  threadExplorerPanX = threadExplorerCardZoomState.panX;
  threadExplorerPanY = threadExplorerCardZoomState.panY;
  threadExplorerCardZoomState = null;
  applyThreadExplorerStageTransform();
  scheduleThreadExplorerEdgeRender();
}

/**
 * Cancels one pending single-click card selection.
 * @returns {void}
 */
function cancelPendingThreadExplorerCardClick() {
  if (threadExplorerPendingCardClickTimer) {
    window.clearTimeout(threadExplorerPendingCardClickTimer);
    threadExplorerPendingCardClickTimer = 0;
  }
  threadExplorerPendingCardClickUri = "";
}

/**
 * Schedules the single-click selection for one rendered Thread Explorer post card.
 * @param {HTMLElement|null} item - Rendered Thread Explorer node item.
 * @returns {void}
 */
function scheduleThreadExplorerCardClickSelection(item) {
  const uri = String(item?.dataset?.uri || "").trim();
  if (!uri) {
    return;
  }

  cancelPendingThreadExplorerCardClick();
  threadExplorerPendingCardClickUri = uri;
  threadExplorerPendingCardClickTimer = window.setTimeout(() => {
    const pendingUri = threadExplorerPendingCardClickUri;
    cancelPendingThreadExplorerCardClick();
    setThreadExplorerSelectedUriLocally(pendingUri);
  }, 220);
}

/**
 * Handles a single click on one Thread Explorer post card.
 * @param {MouseEvent} event - Click event from a rendered post card.
 * @returns {void}
 */
function handleThreadExplorerCardClick(event) {
  if (isThreadExplorerInteractiveTarget(event.target)) {
    return;
  }

  const card = event.currentTarget;
  const item = card?.closest(".thread-explorer-node-item");
  scheduleThreadExplorerCardClickSelection(item);
}

/**
 * Toggles a zoom focus for one rendered Thread Explorer post card.
 * @param {HTMLElement|null} item - Rendered Thread Explorer node item.
 * @returns {void}
 */
function toggleThreadExplorerCardZoom(item) {
  const uri = String(item?.dataset?.uri || "").trim();
  if (!uri) {
    return;
  }

  if (threadExplorerCardZoomState && threadExplorerCardZoomState.uri === uri) {
    restoreThreadExplorerCardZoomState();
    return;
  }

  const focusBounds = getThreadExplorerCardNeighborhoodBounds(item);
  if (!focusBounds) {
    return;
  }

  threadExplorerCardZoomState = {
    uri,
    zoom: threadExplorerZoom,
    panX: threadExplorerPanX,
    panY: threadExplorerPanY,
  };
  const minimumFocusZoom = Math.min(2, Math.max(1.35, threadExplorerZoom));
  fitThreadExplorerStageToBounds(focusBounds, {
    minZoom: minimumFocusZoom,
    maxZoom: 2,
  });
}

/**
 * Handles a mouse double-click on one Thread Explorer post card.
 * @param {MouseEvent} event - Double-click event from a rendered post card.
 * @returns {void}
 */
function handleThreadExplorerCardDoubleClick(event) {
  if (isThreadExplorerNativeInteractiveTarget(event.target)) {
    return;
  }

  cancelPendingThreadExplorerCardClick();
  event.preventDefault();
  event.stopPropagation();
  const card = event.currentTarget;
  const item = card?.closest(".thread-explorer-node-item");
  toggleThreadExplorerCardZoom(item);
}

/**
 * Handles touch-based double-tap zooming on one Thread Explorer post card.
 * @param {PointerEvent} event - Pointer-up event from a rendered post card.
 * @returns {void}
 */
function handleThreadExplorerCardPointerUp(event) {
  if (event.pointerType !== "touch" || isThreadExplorerNativeInteractiveTarget(event.target)) {
    return;
  }

  const card = event.currentTarget;
  const item = card?.closest(".thread-explorer-node-item");
  const uri = String(item?.dataset?.uri || "").trim();
  if (!uri) {
    return;
  }

  const now = Date.now();
  const sameTargetTappedTwice = threadExplorerLastTouchZoomTarget.uri === uri;
  const tappedQuicklyEnough = now - threadExplorerLastTouchZoomTarget.timestamp <= 320;
  threadExplorerLastTouchZoomTarget = {
    uri,
    timestamp: now,
  };
  if (!sameTargetTappedTwice || !tappedQuicklyEnough) {
    return;
  }

  cancelPendingThreadExplorerCardClick();
  event.preventDefault();
  event.stopPropagation();
  threadExplorerLastTouchZoomTarget = {
    uri: "",
    timestamp: 0,
  };
  toggleThreadExplorerCardZoom(item);
}

/**
 * Returns whether a target is a native interactive control that should not trigger card zoom.
 * @param {EventTarget|null} target - Event target from a card interaction.
 * @returns {boolean} True when the target is a button, link, or form control.
 */
function isThreadExplorerNativeInteractiveTarget(target) {
  if (!(target instanceof Element)) {
    return false;
  }

  const nativeInteractiveTarget = target.closest("button, a, input, textarea, select, summary");
  if (nativeInteractiveTarget) {
    return true;
  }

  return false;
}

/**
 * Returns whether a pointer target should keep its native interaction.
 * @param {EventTarget|null} target - Event target from a pointer event.
 * @returns {boolean} True when dragging should not start.
 */
function isThreadExplorerInteractiveTarget(target) {
  if (isThreadExplorerNativeInteractiveTarget(target)) {
    return true;
  }

  if (!(target instanceof Element)) {
    return false;
  }

  const selectableTextTarget = target.closest(
    ".thread-explorer-post-text, .thread-explorer-quote-card-text, .thread-explorer-link-card-title, .thread-explorer-link-card-description, .thread-explorer-link-card-url, .thread-explorer-quote-link-card-title, .thread-explorer-quote-link-card-description, .thread-explorer-quote-link-card-url, .thread-explorer-image figcaption, .thread-explorer-post-author, .thread-explorer-post-handle, .thread-explorer-post-meta, .thread-explorer-feed-text, .thread-explorer-feed-author, .thread-explorer-feed-meta",
  );
  if (selectableTextTarget) {
    return true;
  }

  return false;
}

/**
 * Starts mouse or pointer panning for the Thread Explorer viewport.
 * @param {PointerEvent} event - Pointer down event from the tree viewport.
 * @returns {void}
 */
function handleThreadExplorerPointerDown(event) {
  if (event.button !== 0 || isThreadExplorerInteractiveTarget(event.target)) {
    return;
  }
  cancelThreadExplorerPanInertia();
  threadExplorerThreadTree.classList.add("is-pan-armed");
  threadExplorerDragState = {
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    panX: threadExplorerPanX,
    panY: threadExplorerPanY,
    started: false,
    lastSampleX: event.clientX,
    lastSampleY: event.clientY,
    lastSampleTime: event.timeStamp,
    velocityX: 0,
    velocityY: 0,
  };
  threadExplorerThreadTree.setPointerCapture(event.pointerId);
  event.preventDefault();
}

/**
 * Pans the Thread Explorer viewport while the pointer is captured.
 * @param {PointerEvent} event - Pointer move event from the tree viewport.
 * @returns {void}
 */
function handleThreadExplorerPointerMove(event) {
  if (!threadExplorerDragState || threadExplorerDragState.pointerId !== event.pointerId) {
    return;
  }

  const deltaX = event.clientX - threadExplorerDragState.startX;
  const deltaY = event.clientY - threadExplorerDragState.startY;
  if (threadExplorerDragState.started !== true) {
    const movement = Math.max(Math.abs(deltaX), Math.abs(deltaY));
    if (movement < THREAD_EXPLORER_DRAG_THRESHOLD_PX) {
      return;
    }
    threadExplorerDragState.started = true;
    setThreadExplorerPanningMode(true);
  }

  updateThreadExplorerPanVelocity(threadExplorerDragState, event);
  threadExplorerPanX = threadExplorerDragState.panX + deltaX;
  threadExplorerPanY = threadExplorerDragState.panY + deltaY;
  applyThreadExplorerStageTransform();
  event.preventDefault();
}

/**
 * Stops mouse or pointer panning for the Thread Explorer viewport.
 * @param {PointerEvent} event - Pointer release or cancel event.
 * @returns {void}
 */
function handleThreadExplorerPointerUp(event) {
  if (!threadExplorerDragState || threadExplorerDragState.pointerId !== event.pointerId) {
    return;
  }
  const completedDragState = threadExplorerDragState;
  threadExplorerDragState = null;
  if (threadExplorerThreadTree.hasPointerCapture(event.pointerId)) {
    threadExplorerThreadTree.releasePointerCapture(event.pointerId);
  }
  if (completedDragState.started === true) {
    threadExplorerPanVelocityX = completedDragState.velocityX;
    threadExplorerPanVelocityY = completedDragState.velocityY;
    startThreadExplorerPanInertia();
    return;
  }
  setThreadExplorerPanningMode(false);
}

/**
 * Handles mouse-wheel interaction inside the Thread Explorer viewport.
 * @param {WheelEvent} event - Wheel event from the tree viewport.
 * @returns {void}
 */
function handleThreadExplorerWheel(event) {
  event.preventDefault();

  if (event.altKey || event.shiftKey) {
    applyThreadExplorerScrollDelta(-event.deltaX, -event.deltaY);
    scheduleThreadExplorerEdgeRender();
    return;
  }

  if (event.deltaY < 0) {
    zoomThreadExplorerAtPoint(1.14, event.clientX, event.clientY);
  } else {
    zoomThreadExplorerAtPoint(1 / 1.14, event.clientX, event.clientY);
  }
}

/**
 * Redraws Thread Explorer edges after viewport size changes.
 * @returns {void}
 */
function handleThreadExplorerResize() {
  if (currentWorkspace !== "threadExplorer") {
    return;
  }
  if (!threadExplorerTree) {
    return;
  }
  scheduleThreadExplorerEdgeRender();
}

/**
 * Adds all collapsible Thread Explorer node URIs to a target set.
 * @param {object|null} node - Tree node to inspect.
 * @param {Set<string>} targetSet - Set that receives post URIs for nodes with replies.
 * @returns {void}
 */
function collectCollapsibleThreadExplorerUris(node, targetSet) {
  if (!node || !Array.isArray(node.replies) || node.replies.length === 0) {
    return;
  }
  if (node.post?.uri) {
    targetSet.add(node.post.uri);
  }
  node.replies.forEach((reply) => {
    collectCollapsibleThreadExplorerUris(reply, targetSet);
  });
}

/**
 * Expands or collapses all current Thread Explorer tree nodes.
 * @param {boolean} shouldCollapse - True collapses all nodes with replies, false expands all nodes.
 * @returns {void}
 */
function setAllThreadExplorerNodesCollapsed(shouldCollapse) {
  threadExplorerCollapsedUris.clear();
  if (shouldCollapse) {
    collectCollapsibleThreadExplorerUris(threadExplorerTree, threadExplorerCollapsedUris);
  }
  renderThreadExplorerTree();
}

/**
 * Creates a safe filename part for Thread Explorer exports.
 * @param {string} value - Raw filename part.
 * @returns {string} Filesystem-friendly filename part.
 */
function sanitizeThreadExplorerFileNamePart(value) {
  const normalized = String(value || "").trim().replace(/^@+/, "");
  const safe = normalized.replace(/[<>:"/\\|?*\u0000-\u001f]+/g, "-").replace(/\s+/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "");
  if (safe) {
    return safe.slice(0, 80);
  }
  return "thread";
}

/**
 * Builds the Thread Explorer snapshot filename from the root post.
 * @param {string} extension - File extension without leading dot.
 * @returns {string} Snapshot filename.
 */
function buildThreadExplorerSnapshotFileName(extension = "png") {
  const rootPost = threadExplorerTree?.post || {};
  let handle = String(rootPost.author?.handle || rootPost.author?.displayName || rootPost.author?.did || "").trim();
  if (!handle) {
    handle = "thread";
  }

  let datePart = "";
  const timestamp = Date.parse(String(rootPost.createdAt || rootPost.indexedAt || "").trim());
  if (Number.isFinite(timestamp)) {
    datePart = new Date(timestamp).toISOString().slice(0, 10);
  } else {
    datePart = new Date().toISOString().slice(0, 10);
  }

  const safeExtension = sanitizeThreadExplorerFileNamePart(extension || "png").toLowerCase();
  return `threadline-thread-${sanitizeThreadExplorerFileNamePart(handle)}-${datePart}.${safeExtension}`;
}

/**
 * Counts media assets that make a Thread Explorer PNG snapshot expensive.
 * @param {object|null} node - Thread Explorer tree node.
 * @returns {number} Count of post images, quote images and external-card thumbnails.
 */
function countThreadExplorerSnapshotMediaAssets(node = null) {
  if (!node || typeof node !== "object") {
    return 0;
  }

  let count = 0;
  const post = node.post || {};
  if (Array.isArray(post.images)) {
    count += post.images.length;
  }
  if (post.externalCard?.thumb) {
    count += 1;
  }

  const quote = post.quoteCard || null;
  if (quote && typeof quote === "object") {
    if (Array.isArray(quote.images)) {
      count += quote.images.length;
    }
    if (quote.externalCard?.thumb) {
      count += 1;
    }
  }

  if (Array.isArray(node.replies)) {
    node.replies.forEach((reply) => {
      count += countThreadExplorerSnapshotMediaAssets(reply);
    });
  }

  return count;
}

/**
 * Encodes an already loaded image element as a data URL when the browser allows it.
 * @param {HTMLImageElement} image - Source image from the rendered Thread Explorer.
 * @returns {string} Data URL, original data URL, or an empty string when unavailable.
 */
function encodeThreadExplorerImageElement(image) {
  const source = String(image?.currentSrc || image?.src || "").trim();
  if (!source) {
    return "";
  }
  if (source.startsWith("data:")) {
    return source;
  }
  if (!image.complete || !image.naturalWidth || !image.naturalHeight) {
    return "";
  }

  try {
    const canvas = document.createElement("canvas");
    canvas.width = image.naturalWidth;
    canvas.height = image.naturalHeight;
    const context = canvas.getContext("2d");
    context.drawImage(image, 0, 0);
    return canvas.toDataURL("image/png");
  } catch {
    return "";
  }
}

/**
 * Reads a Thread Explorer avatar data URI from the shared local avatar cache.
 * @param {HTMLImageElement|null} image - Avatar image with cache lookup metadata.
 * @returns {string} Cached avatar data URI or an empty string.
 */
function getThreadExplorerSnapshotCachedAvatarUri(image = null) {
  const did = String(image?.dataset?.avatarDid || "").trim();
  const avatarUrl = String(image?.dataset?.avatarUrl || "").trim();
  if (!did || !avatarUrl) {
    return "";
  }

  let assets = [];
  if (Array.isArray(accountAvatarAssets)) {
    assets = accountAvatarAssets;
  }
  const asset = assets.find((entry) => entry.did === did && entry.url === avatarUrl);
  if (!asset) {
    return "";
  }

  return assetToDataUri(asset);
}

/**
 * Builds the cache lookup key for a Thread Explorer avatar image.
 * @param {HTMLImageElement|null} image - Avatar image with cache lookup metadata.
 * @returns {string} Stable avatar cache key or an empty string.
 */
function getThreadExplorerSnapshotAvatarCacheKey(image = null) {
  const did = String(image?.dataset?.avatarDid || "").trim();
  const avatarUrl = String(image?.dataset?.avatarUrl || "").trim();
  if (!did || !avatarUrl) {
    return "";
  }

  return `${did}|${avatarUrl}`;
}

/**
 * Loads one cached avatar data URI into an image object for canvas drawing.
 * @param {string} dataUri - Cached avatar data URI.
 * @returns {Promise<HTMLImageElement|null>} Loaded image or null when loading fails.
 */
function loadThreadExplorerSnapshotAvatarImage(dataUri) {
  const source = String(dataUri || "").trim();
  if (!source) {
    return Promise.resolve(null);
  }

  return new Promise((resolve) => {
    const image = new Image();
    image.addEventListener("load", () => {
      resolve(image);
    }, { once: true });
    image.addEventListener("error", () => {
      resolve(null);
    }, { once: true });
    image.src = source;
  });
}

/**
 * Loads one rendered snapshot image source into a canvas-safe image object.
 * @param {string} source - Data URI, blob URL or same-origin image URL.
 * @returns {Promise<HTMLImageElement|null>} Loaded image or null when loading fails.
 */
function loadThreadExplorerSnapshotCanvasImage(source) {
  const normalizedSource = String(source || "").trim();
  if (!normalizedSource) {
    return Promise.resolve(null);
  }

  return new Promise((resolve) => {
    const image = new Image();
    image.addEventListener("load", () => {
      resolve(image);
    }, { once: true });
    image.addEventListener("error", () => {
      resolve(null);
    }, { once: true });
    image.src = normalizedSource;
  });
}

/**
 * Preloads all cached Thread Explorer avatars needed by the canvas snapshot renderers.
 * @param {HTMLElement[]} cards - Rendered Thread Explorer post cards.
 * @returns {Promise<Map<string, HTMLImageElement>>} Loaded avatar image map keyed by DID and URL.
 */
async function preloadThreadExplorerSnapshotAvatarImages(cards) {
  const avatarEntries = new Map();
  cards.forEach((card) => {
    const avatar = card.querySelector(".thread-explorer-avatar");
    const key = getThreadExplorerSnapshotAvatarCacheKey(avatar);
    if (!key || avatarEntries.has(key)) {
      return;
    }

    const dataUri = getThreadExplorerSnapshotCachedAvatarUri(avatar);
    if (!dataUri) {
      return;
    }
    avatarEntries.set(key, dataUri);
  });

  const loaded = new Map();
  for (const [key, dataUri] of avatarEntries.entries()) {
    const image = await loadThreadExplorerSnapshotAvatarImage(dataUri);
    if (image) {
      loaded.set(key, image);
    }
  }
  return loaded;
}

/**
 * Returns whether a rendered image belongs to post media rather than account avatars.
 * @param {HTMLImageElement|null} image - Rendered image element.
 * @returns {boolean} True when the image should be painted as card media.
 */
function isThreadExplorerSnapshotMediaImage(image = null) {
  if (!image || image.hidden) {
    return false;
  }
  if (image.classList.contains("thread-explorer-avatar")) {
    return false;
  }
  if (image.classList.contains("thread-explorer-quote-card-avatar")) {
    return false;
  }
  return Boolean(image.closest(".thread-explorer-post-gallery, .thread-explorer-link-card, .thread-explorer-quote-card-gallery, .thread-explorer-quote-link-card"));
}

/**
 * Builds stable lookup keys for one rendered media image in a snapshot card.
 * @param {HTMLImageElement|null} image - Rendered media image.
 * @returns {string[]} Stable media image keys ordered by preference.
 */
function getThreadExplorerSnapshotMediaImageKeys(image = null) {
  const candidates = [
    image?.dataset?.snapshotSource,
    image?.dataset?.snapshotThumb,
    image?.currentSrc,
    image?.src,
  ];
  const keys = [];
  candidates.forEach((candidate) => {
    const source = String(candidate || "").trim();
    if (!source || keys.includes(source)) {
      return;
    }
    keys.push(source);
  });
  return keys;
}

/**
 * Builds the preferred key for one rendered media image in a snapshot card.
 * @param {HTMLImageElement|null} image - Rendered media image.
 * @returns {string} Stable media image key or an empty string.
 */
function getThreadExplorerSnapshotMediaImageKey(image = null) {
  const keys = getThreadExplorerSnapshotMediaImageKeys(image);
  if (keys.length === 0) {
    return "";
  }
  return keys[0];
}

/**
 * Finds a preloaded media image using all known keys for the rendered image element.
 * @param {HTMLImageElement|null} image - Rendered media image.
 * @param {Map<string, HTMLImageElement>} mediaImages - Preloaded media image map.
 * @returns {HTMLImageElement|null} Loaded image or null when no key matches.
 */
function getThreadExplorerSnapshotDrawableMediaImage(image = null, mediaImages = new Map()) {
  const keys = getThreadExplorerSnapshotMediaImageKeys(image);
  for (const key of keys) {
    if (mediaImages.has(key)) {
      return mediaImages.get(key);
    }
  }
  return null;
}

/**
 * Clears the short-lived cache for media currently shown in the Thread Explorer.
 * @returns {void}
 */
function clearThreadExplorerRenderedMediaCache() {
  threadExplorerMediaCacheGeneration += 1;
  if (threadExplorerMediaCachePrewarmController) {
    threadExplorerMediaCachePrewarmController.abort();
    threadExplorerMediaCachePrewarmController = null;
  }
  threadExplorerRenderedMediaCache = new Map();
  threadExplorerSnapshotMediaDataUris = new Map();
}

/**
 * Finds a cached data URI for any of the provided Thread Explorer media keys.
 * @param {string[]} keys - Media URL keys that may identify the same image.
 * @returns {string} Cached data URI, or an empty string.
 */
function getThreadExplorerRenderedMediaCacheDataUri(keys = []) {
  for (const key of keys) {
    const normalizedKey = String(key || "").trim();
    if (!normalizedKey) {
      continue;
    }
    if (threadExplorerRenderedMediaCache.has(normalizedKey)) {
      return threadExplorerRenderedMediaCache.get(normalizedKey);
    }
    if (threadExplorerSnapshotMediaDataUris.has(normalizedKey)) {
      return threadExplorerSnapshotMediaDataUris.get(normalizedKey);
    }
  }
  return "";
}

/**
 * Assigns a Thread Explorer image source, preferring already cached data URIs.
 * @param {HTMLImageElement|null} image - Target image element.
 * @param {string} primarySource - Original full image or thumbnail URL.
 * @param {string} secondarySource - Secondary URL for the same image.
 * @returns {void}
 */
function setThreadExplorerCachedImageSource(image = null, primarySource = "", secondarySource = "") {
  if (!image) {
    return;
  }

  const normalizedPrimary = String(primarySource || "").trim();
  const normalizedSecondary = String(secondarySource || "").trim();
  if (normalizedPrimary) {
    image.dataset.snapshotSource = normalizedPrimary;
  } else {
    delete image.dataset.snapshotSource;
  }
  if (normalizedSecondary && normalizedSecondary !== normalizedPrimary) {
    image.dataset.snapshotThumb = normalizedSecondary;
  } else {
    delete image.dataset.snapshotThumb;
  }

  const keys = getThreadExplorerSnapshotMediaImageKeys(image);
  const dataUri = getThreadExplorerRenderedMediaCacheDataUri(keys);
  if (dataUri) {
    image.dataset.snapshotHydrated = "true";
    image.src = dataUri;
    return;
  }

  delete image.dataset.snapshotHydrated;
  if (normalizedPrimary) {
    image.src = normalizedPrimary;
  } else if (normalizedSecondary) {
    image.src = normalizedSecondary;
  } else {
    image.removeAttribute("src");
  }
}

/**
 * Replaces rendered Thread Explorer media URLs with cache data URIs when available.
 * @returns {number} Number of image elements switched to cached sources.
 */
function applyThreadExplorerRenderedMediaCacheToDom() {
  if (!threadExplorerThreadStage) {
    return 0;
  }

  let appliedCount = 0;
  const images = Array.from(threadExplorerThreadStage.querySelectorAll("img"));
  images.forEach((image) => {
    if (!isThreadExplorerSnapshotMediaImage(image)) {
      return;
    }
    const dataUri = getThreadExplorerRenderedMediaCacheDataUri(getThreadExplorerSnapshotMediaImageKeys(image));
    if (!dataUri || image.src === dataUri) {
      return;
    }
    image.dataset.snapshotHydrated = "true";
    image.src = dataUri;
    appliedCount += 1;
  });

  if (appliedCount > 0) {
    scheduleThreadExplorerEdgeRender();
  }
  return appliedCount;
}

/**
 * Stores one Thread Explorer media data URI under every known cache key.
 * @param {string[]} keys - Cache keys that identify the same media image.
 * @param {string} dataUri - Canvas-safe data URI.
 * @returns {void}
 */
function storeThreadExplorerRenderedMediaDataUri(keys = [], dataUri = "") {
  const normalizedDataUri = String(dataUri || "").trim();
  if (!normalizedDataUri) {
    return;
  }

  keys.forEach((key) => {
    const normalizedKey = String(key || "").trim();
    if (normalizedKey) {
      threadExplorerRenderedMediaCache.set(normalizedKey, normalizedDataUri);
    }
  });
}

/**
 * Stores a rendered Thread Explorer media image as a data URI for the current thread.
 * @param {HTMLImageElement|null} image - Loaded media image from the visible thread.
 * @returns {void}
 */
function cacheThreadExplorerRenderedMediaImage(image = null) {
  if (!image || !image.complete || !image.naturalWidth || !image.naturalHeight) {
    return;
  }

  const keys = getThreadExplorerSnapshotMediaImageKeys(image);
  if (keys.length === 0) {
    return;
  }

  const dataUri = encodeThreadExplorerImageElement(image);
  if (!dataUri) {
    return;
  }

  storeThreadExplorerRenderedMediaDataUri(keys, dataUri);
}

/**
 * Registers load/error bookkeeping for a rendered Thread Explorer media image.
 * @param {HTMLImageElement|null} image - Media image element.
 * @param {(event: Event) => void} errorHandler - Existing error handler for this image.
 * @returns {void}
 */
function attachThreadExplorerRenderedMediaCacheHandlers(image = null, errorHandler = null) {
  if (!image) {
    return;
  }

  image.addEventListener("load", () => {
    cacheThreadExplorerRenderedMediaImage(image);
    refreshThreadExplorerRenderedGeometry();
  }, { once: true });
  if (typeof errorHandler === "function") {
    image.addEventListener("error", errorHandler);
  }
}

/**
 * Caches every currently loaded and readable media image in the Thread Explorer DOM.
 * @returns {number} Number of media elements inspected.
 */
function cacheLoadedThreadExplorerRenderedMediaImages() {
  const images = Array.from(threadExplorerThreadStage.querySelectorAll("img"))
    .filter((image) => isThreadExplorerSnapshotMediaImage(image));
  images.forEach((image) => {
    cacheThreadExplorerRenderedMediaImage(image);
  });
  return images.length;
}

/**
 * Collects canvas-safe rendered media images from Thread Explorer cards.
 * @param {HTMLElement[]} cards - Rendered Thread Explorer post cards.
 * @returns {Promise<Map<string, HTMLImageElement>>} Loaded media image map keyed by image source.
 */
async function preloadThreadExplorerSnapshotMediaImages(cards) {
  const sourceEntries = new Map();
  cards.forEach((card) => {
    const images = Array.from(card.querySelectorAll("img"));
    images.forEach((image) => {
      if (!isThreadExplorerSnapshotMediaImage(image)) {
        return;
      }

      const keys = getThreadExplorerSnapshotMediaImageKeys(image);
      if (keys.length === 0) {
        return;
      }

      let source = "";
      for (const key of keys) {
        if (threadExplorerRenderedMediaCache.has(key)) {
          source = threadExplorerRenderedMediaCache.get(key);
          break;
        }
        if (threadExplorerSnapshotMediaDataUris.has(key)) {
          source = threadExplorerSnapshotMediaDataUris.get(key);
          break;
        }
      }
      if (!source) {
        source = encodeThreadExplorerImageElement(image);
      }
      if (!source && canDrawThreadExplorerSnapshotImage(image)) {
        source = String(image.currentSrc || image.src || "").trim();
      }
      if (source) {
        keys.forEach((key) => {
          if (!sourceEntries.has(key)) {
            sourceEntries.set(key, source);
          }
        });
      }
    });
  });

  const loaded = new Map();
  for (const [key, source] of sourceEntries.entries()) {
    const image = await loadThreadExplorerSnapshotCanvasImage(source);
    if (image) {
      loaded.set(key, image);
    }
  }
  return loaded;
}

/**
 * Returns a hydrated data URI for a rendered Thread Explorer media image.
 * @param {HTMLImageElement|null} image - Rendered media image.
 * @returns {string} Hydrated data URI or an empty string.
 */
function getThreadExplorerSnapshotHydratedMediaUri(image = null) {
  const keys = getThreadExplorerSnapshotMediaImageKeys(image);
  for (const key of keys) {
    if (threadExplorerRenderedMediaCache.has(key)) {
      return threadExplorerRenderedMediaCache.get(key);
    }
    if (threadExplorerSnapshotMediaDataUris.has(key)) {
      return threadExplorerSnapshotMediaDataUris.get(key);
    }
  }
  return "";
}

/**
 * Applies hydrated media data URIs directly to rendered Thread Explorer image elements.
 * @param {(progress: {percent?: number, step?: string, detail?: string}) => Promise<void>} onProgress - Progress reporter.
 * @param {AbortSignal|null} signal - Abort signal for the current export.
 * @returns {Promise<object>} Counts for total, embedded and missing images.
 */
async function applyThreadExplorerSnapshotMediaDataUrisToRenderedTree(onProgress = async () => {}, signal = null) {
  const images = Array.from(threadExplorerThreadStage.querySelectorAll("img"));
  const mediaImages = images.filter((image) => isThreadExplorerSnapshotMediaImage(image));
  const total = mediaImages.length;
  let appliedCount = 0;
  let skippedCount = 0;

  for (let index = 0; index < mediaImages.length; index += 1) {
    throwIfThreadExplorerSnapshotAborted(signal);
    const image = mediaImages[index];

    const dataUri = getThreadExplorerSnapshotHydratedMediaUri(image);
    if (!dataUri) {
      skippedCount += 1;
    } else {
      image.dataset.snapshotHydrated = "true";
      image.src = dataUri;
      storeThreadExplorerRenderedMediaDataUri(getThreadExplorerSnapshotMediaImageKeys(image), dataUri);
      appliedCount += 1;
    }

    await onProgress({
      percent: 38 + ((index + 1) / Math.max(1, total) * 2),
      step: t("threadExplorerSnapshotProgressMedia"),
      detail: t("threadExplorerSnapshotProgressMediaEmbedDetail", {
        current: index + 1,
        total,
        remaining: Math.max(0, total - index - 1),
        embedded: appliedCount,
        skipped: skippedCount,
      }),
    });
  }
  return {
    total,
    embedded: appliedCount,
    missing: skippedCount,
  };
}

/**
 * Replaces cloned Thread Explorer images with data URLs read from rendered image elements.
 * @param {HTMLElement} source - Original rendered tree stage.
 * @param {HTMLElement} clone - Cloned tree stage.
 * @returns {void}
 */
function inlineThreadExplorerSnapshotImages(source, clone) {
  const sourceImages = Array.from(source.querySelectorAll("img"));
  const cloneImages = Array.from(clone.querySelectorAll("img"));
  cloneImages.forEach((cloneImage, index) => {
    const cachedAvatarUri = getThreadExplorerSnapshotCachedAvatarUri(cloneImage)
      || getThreadExplorerSnapshotCachedAvatarUri(sourceImages[index]);
    if (cachedAvatarUri) {
      cloneImage.setAttribute("src", cachedAvatarUri);
      return;
    }

    const hydratedMediaUri = getThreadExplorerSnapshotHydratedMediaUri(sourceImages[index])
      || getThreadExplorerSnapshotHydratedMediaUri(cloneImage);
    if (hydratedMediaUri) {
      cloneImage.setAttribute("src", hydratedMediaUri);
      return;
    }

    const dataUrl = encodeThreadExplorerImageElement(sourceImages[index]);
    if (dataUrl) {
      cloneImage.setAttribute("src", dataUrl);
      return;
    }
    cloneImage.setAttribute("src", DEFAULT_AVATAR_URI);
    cloneImage.classList.add("is-snapshot-fallback-image");
  });
}

/**
 * Collects accessible CSS text for the Thread Explorer snapshot SVG.
 * @returns {string} CSS text.
 */
function collectThreadExplorerSnapshotCss() {
  const parts = [];
  for (const styleSheet of Array.from(document.styleSheets)) {
    try {
      for (const rule of Array.from(styleSheet.cssRules || [])) {
        parts.push(rule.cssText);
      }
    } catch {
      // Cross-origin stylesheets cannot be read; local app styles are enough for Threadline.
    }
  }
  return parts.join("\n");
}

/**
 * Downloads a blob with the given filename.
 * @param {Blob} blob - Blob to download.
 * @param {string} fileName - Suggested download filename.
 * @returns {void}
 */
function downloadThreadExplorerBlob(blob, fileName) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * Draws rounded rectangle path for snapshot canvas rendering.
 * @param {CanvasRenderingContext2D} context - Target canvas context.
 * @param {number} x - Left coordinate.
 * @param {number} y - Top coordinate.
 * @param {number} width - Rectangle width.
 * @param {number} height - Rectangle height.
 * @param {number} radius - Corner radius.
 * @returns {void}
 */
function drawThreadExplorerSnapshotRoundRect(context, x, y, width, height, radius) {
  const safeRadius = Math.min(radius, width / 2, height / 2);
  context.beginPath();
  context.moveTo(x + safeRadius, y);
  context.lineTo(x + width - safeRadius, y);
  context.quadraticCurveTo(x + width, y, x + width, y + safeRadius);
  context.lineTo(x + width, y + height - safeRadius);
  context.quadraticCurveTo(x + width, y + height, x + width - safeRadius, y + height);
  context.lineTo(x + safeRadius, y + height);
  context.quadraticCurveTo(x, y + height, x, y + height - safeRadius);
  context.lineTo(x, y + safeRadius);
  context.quadraticCurveTo(x, y, x + safeRadius, y);
  context.closePath();
}

/**
 * Draws a rounded rectangle outline for snapshot canvas rendering.
 * @param {CanvasRenderingContext2D} context - Target canvas context.
 * @param {number} x - Left coordinate.
 * @param {number} y - Top coordinate.
 * @param {number} width - Rectangle width.
 * @param {number} height - Rectangle height.
 * @param {number} radius - Corner radius.
 * @param {string} color - Stroke color.
 * @param {number} lineWidth - Stroke width.
 * @returns {void}
 */
function strokeThreadExplorerSnapshotRoundRect(context, x, y, width, height, radius, color, lineWidth = 1) {
  context.save();
  drawThreadExplorerSnapshotRoundRect(context, x, y, width, height, radius);
  context.strokeStyle = color;
  context.lineWidth = lineWidth;
  context.stroke();
  context.restore();
}

/**
 * Wraps plain text for canvas snapshot rendering.
 * @param {CanvasRenderingContext2D} context - Measuring canvas context.
 * @param {string} text - Text to wrap.
 * @param {number} maxWidth - Maximum line width.
 * @param {number} maxLines - Maximum lines to return.
 * @returns {string[]} Wrapped lines.
 */
function wrapThreadExplorerSnapshotText(context, text, maxWidth, maxLines = 8) {
  const normalized = String(text || "").replace(/\s+/g, " ").trim();
  if (!normalized) {
    return [];
  }

  const words = normalized.split(" ");
  const lines = [];
  let current = "";
  words.forEach((word) => {
    const candidate = current ? `${current} ${word}` : word;
    if (context.measureText(candidate).width <= maxWidth) {
      current = candidate;
      return;
    }
    if (current) {
      lines.push(current);
    }
    current = word;
  });
  if (current) {
    lines.push(current);
  }

  if (lines.length <= maxLines) {
    return lines;
  }
  const clipped = lines.slice(0, maxLines);
  clipped[clipped.length - 1] = `${clipped[clipped.length - 1].replace(/\.+$/, "")}...`;
  return clipped;
}

/**
 * Draws one text block for snapshot canvas rendering.
 * @param {CanvasRenderingContext2D} context - Target canvas context.
 * @param {string[]} lines - Lines to draw.
 * @param {number} x - Left coordinate.
 * @param {number} y - First baseline coordinate.
 * @param {number} lineHeight - Distance between baselines.
 * @returns {number} Next baseline coordinate after the block.
 */
function drawThreadExplorerSnapshotTextBlock(context, lines, x, y, lineHeight) {
  let cursorY = y;
  lines.forEach((line) => {
    context.fillText(line, x, cursorY);
    cursorY += lineHeight;
  });
  return cursorY;
}

/**
 * Calculates a browser-safe scale for Thread Explorer snapshot canvases.
 * @param {number} width - Snapshot layout width in CSS pixels.
 * @param {number} height - Snapshot layout height in CSS pixels.
 * @returns {number} Canvas scale factor.
 */
function getThreadExplorerSnapshotScale(width, height) {
  let scale = Math.min(2, Math.max(1, window.devicePixelRatio || 1));
  const longestSide = Math.max(width, height, 1);
  const pixelCount = Math.max(width * height, 1);
  const dimensionScale = THREAD_EXPLORER_SNAPSHOT_MAX_CANVAS_DIMENSION / longestSide;
  const pixelScale = Math.sqrt(THREAD_EXPLORER_SNAPSHOT_MAX_CANVAS_PIXELS / pixelCount);

  if (dimensionScale < scale) {
    scale = dimensionScale;
  }
  if (pixelScale < scale) {
    scale = pixelScale;
  }
  if (!Number.isFinite(scale) || scale <= 0) {
    scale = 0.1;
  }

  return Math.max(0.01, Math.min(2, scale));
}

/**
 * Creates a canvas sized for the complete Thread Explorer snapshot.
 * @param {number} width - CSS pixel width.
 * @param {number} height - CSS pixel height.
 * @returns {object} Canvas, context, scale, width, and height.
 */
function createThreadExplorerSnapshotCanvas(width, height) {
  const canvas = document.createElement("canvas");
  const scale = getThreadExplorerSnapshotScale(width, height);
  canvas.width = Math.max(1, Math.floor(width * scale));
  canvas.height = Math.max(1, Math.floor(height * scale));
  const context = canvas.getContext("2d");
  context.setTransform(scale, 0, 0, scale, 0, 0);
  context.fillStyle = getComputedStyle(document.body).backgroundColor || "#ffffff";
  context.fillRect(0, 0, width, height);
  return {
    canvas,
    context,
    scale,
    width,
    height,
  };
}

/**
 * Converts a snapshot canvas to a blob.
 * @param {HTMLCanvasElement} canvas - Canvas to encode.
 * @param {string} mimeType - Target MIME type.
 * @returns {Promise<Blob>} Encoded image blob.
 */
async function encodeThreadExplorerSnapshotCanvas(canvas, mimeType) {
  let quality = undefined;
  if (mimeType === "image/jpeg") {
    quality = 0.92;
  }
  const blob = await new Promise((resolve) => canvas.toBlob(resolve, mimeType, quality));
  if (!blob) {
    throw new Error(t("threadExplorerSnapshotFailed"));
  }
  if (mimeType === "image/png") {
    return addThreadExplorerPngMetadata(blob);
  }
  return blob;
}

/**
 * Writes an unsigned 32-bit integer in big-endian order.
 * @param {Uint8Array} target - Target byte buffer.
 * @param {number} offset - Write offset.
 * @param {number} value - Unsigned integer value.
 * @returns {void}
 */
function writeThreadExplorerPngUint32(target, offset, value) {
  target[offset] = (value >>> 24) & 255;
  target[offset + 1] = (value >>> 16) & 255;
  target[offset + 2] = (value >>> 8) & 255;
  target[offset + 3] = value & 255;
}

/**
 * Builds the CRC table used by PNG chunks.
 * @returns {Uint32Array} CRC lookup table.
 */
function createThreadExplorerPngCrcTable() {
  const table = new Uint32Array(256);
  for (let index = 0; index < 256; index += 1) {
    let value = index;
    for (let bit = 0; bit < 8; bit += 1) {
      if ((value & 1) !== 0) {
        value = 0xedb88320 ^ (value >>> 1);
      } else {
        value >>>= 1;
      }
    }
    table[index] = value >>> 0;
  }
  return table;
}

/**
 * Calculates a PNG CRC over chunk type and payload.
 * @param {string} type - Four-character PNG chunk type.
 * @param {Uint8Array} data - Chunk payload bytes.
 * @param {Uint32Array} table - CRC lookup table.
 * @returns {number} Unsigned CRC value.
 */
function calculateThreadExplorerPngCrc(type, data, table) {
  let crc = 0xffffffff;
  for (let index = 0; index < type.length; index += 1) {
    crc = table[(crc ^ type.charCodeAt(index)) & 255] ^ (crc >>> 8);
  }
  for (let index = 0; index < data.length; index += 1) {
    crc = table[(crc ^ data[index]) & 255] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

/**
 * Creates one complete PNG chunk.
 * @param {string} type - Four-character PNG chunk type.
 * @param {Uint8Array} data - Chunk payload bytes.
 * @param {Uint32Array} crcTable - CRC lookup table.
 * @returns {Uint8Array} Encoded PNG chunk.
 */
function createThreadExplorerPngChunk(type, data, crcTable) {
  const chunk = new Uint8Array(data.length + 12);
  writeThreadExplorerPngUint32(chunk, 0, data.length);
  for (let index = 0; index < type.length; index += 1) {
    chunk[4 + index] = type.charCodeAt(index);
  }
  chunk.set(data, 8);
  writeThreadExplorerPngUint32(chunk, data.length + 8, calculateThreadExplorerPngCrc(type, data, crcTable));
  return chunk;
}

/**
 * Creates one PNG text metadata chunk.
 * @param {string} keyword - PNG text keyword.
 * @param {string} value - Text value.
 * @param {Uint32Array} crcTable - CRC lookup table.
 * @returns {Uint8Array} Encoded PNG tEXt chunk.
 */
function createThreadExplorerPngTextChunk(keyword, value, crcTable) {
  const encoder = new TextEncoder();
  const safeKeyword = String(keyword || "").replace(/[^\x20-\x7e]+/g, "").slice(0, 79);
  const safeValue = String(value || "").replace(/[^\x20-\x7e]+/g, "");
  const keywordBytes = encoder.encode(safeKeyword);
  const valueBytes = encoder.encode(safeValue);
  const data = new Uint8Array(keywordBytes.length + 1 + valueBytes.length);
  data.set(keywordBytes, 0);
  data[keywordBytes.length] = 0;
  data.set(valueBytes, keywordBytes.length + 1);
  return createThreadExplorerPngChunk("tEXt", data, crcTable);
}

/**
 * Escapes a text value for use inside PNG XMP metadata.
 * @param {string} value - Raw text value.
 * @returns {string} XML-safe text value.
 */
function escapeThreadExplorerPngXmpText(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

/**
 * Builds an XMP packet for PNG export metadata.
 * @param {string} applicationLabel - Threadline application and version label.
 * @returns {string} XMP metadata packet.
 */
function createThreadExplorerPngXmpPacket(applicationLabel) {
  const safeLabel = escapeThreadExplorerPngXmpText(applicationLabel);
  const metadataDate = escapeThreadExplorerPngXmpText(new Date().toISOString());
  return [
    '<?xpacket begin="" id="W5M0MpCehiHzreSzNTczkc9d"?>',
    '<x:xmpmeta xmlns:x="adobe:ns:meta/">',
    '<rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">',
    '<rdf:Description rdf:about="" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:xmp="http://ns.adobe.com/xap/1.0/">',
    '<dc:creator><rdf:Seq><rdf:li>Threadline</rdf:li></rdf:Seq></dc:creator>',
    `<xmp:CreatorTool>${safeLabel}</xmp:CreatorTool>`,
    `<xmp:MetadataDate>${metadataDate}</xmp:MetadataDate>`,
    `<xmp:ModifyDate>${metadataDate}</xmp:ModifyDate>`,
    '</rdf:Description>',
    '</rdf:RDF>',
    '</x:xmpmeta>',
    '<?xpacket end="w"?>',
  ].join("");
}

/**
 * Creates one PNG international text chunk for XMP metadata.
 * @param {string} value - XMP payload.
 * @param {Uint32Array} crcTable - CRC lookup table.
 * @returns {Uint8Array} Encoded PNG iTXt chunk.
 */
function createThreadExplorerPngXmpChunk(value, crcTable) {
  const encoder = new TextEncoder();
  const keywordBytes = encoder.encode("XML:com.adobe.xmp");
  const textBytes = encoder.encode(value);
  const data = new Uint8Array(keywordBytes.length + 5 + textBytes.length);
  data.set(keywordBytes, 0);
  data[keywordBytes.length] = 0;
  data[keywordBytes.length + 1] = 0;
  data[keywordBytes.length + 2] = 0;
  data[keywordBytes.length + 3] = 0;
  data[keywordBytes.length + 4] = 0;
  data.set(textBytes, keywordBytes.length + 5);
  return createThreadExplorerPngChunk("iTXt", data, crcTable);
}

/**
 * Builds PNG metadata chunks for Threadline exports.
 * @param {Uint32Array} crcTable - CRC lookup table.
 * @returns {Uint8Array[]} PNG metadata chunks.
 */
function createThreadExplorerPngMetadataChunks(crcTable) {
  const applicationLabel = getExportMetadataApplicationLabel();
  return [
    createThreadExplorerPngTextChunk("Software", applicationLabel, crcTable),
    createThreadExplorerPngTextChunk("Author", applicationLabel, crcTable),
    createThreadExplorerPngTextChunk("Creator", applicationLabel, crcTable),
    createThreadExplorerPngXmpChunk(createThreadExplorerPngXmpPacket(applicationLabel), crcTable),
  ];
}

/**
 * Adds Threadline metadata chunks to an encoded PNG blob.
 * @param {Blob} blob - PNG blob from browser canvas encoding.
 * @returns {Promise<Blob>} PNG blob with metadata chunks when possible.
 */
async function addThreadExplorerPngMetadata(blob) {
  const bytes = new Uint8Array(await blob.arrayBuffer());
  const signature = [137, 80, 78, 71, 13, 10, 26, 10];
  for (let index = 0; index < signature.length; index += 1) {
    if (bytes[index] !== signature[index]) {
      return blob;
    }
  }

  const crcTable = createThreadExplorerPngCrcTable();
  const insertionOffset = 8 + 4 + 4 + 13 + 4;
  if (bytes.length <= insertionOffset) {
    return blob;
  }

  const parts = [
    bytes.slice(0, insertionOffset),
    ...createThreadExplorerPngMetadataChunks(crcTable),
    bytes.slice(insertionOffset),
  ];
  return new Blob(parts, { type: "image/png" });
}

/**
 * Creates PNG IHDR data for an RGBA image.
 * @param {number} width - Image width in pixels.
 * @param {number} height - Image height in pixels.
 * @returns {Uint8Array} IHDR payload.
 */
function createThreadExplorerPngHeaderData(width, height) {
  const data = new Uint8Array(13);
  writeThreadExplorerPngUint32(data, 0, width);
  writeThreadExplorerPngUint32(data, 4, height);
  data[8] = 8;
  data[9] = 6;
  data[10] = 0;
  data[11] = 0;
  data[12] = 0;
  return data;
}

/**
 * Returns the Thread Explorer snapshot background color.
 * @returns {string} CSS color string.
 */
function getThreadExplorerSnapshotBackgroundColor() {
  const stageColor = getComputedStyle(threadExplorerThreadStage).backgroundColor;
  if (stageColor && stageColor !== "rgba(0, 0, 0, 0)") {
    return stageColor;
  }

  const treeColor = getComputedStyle(threadExplorerThreadTree).backgroundColor;
  if (treeColor && treeColor !== "rgba(0, 0, 0, 0)") {
    return treeColor;
  }

  const bodyColor = getComputedStyle(document.body).backgroundColor;
  if (bodyColor && bodyColor !== "rgba(0, 0, 0, 0)") {
    return bodyColor;
  }

  return "#f2f7ff";
}

/**
 * Renders one full-resolution Thread Explorer snapshot tile.
 * @param {number} tileX - Tile left coordinate in snapshot pixels.
 * @param {number} tileY - Tile top coordinate in snapshot pixels.
 * @param {number} tileWidth - Tile width in pixels.
 * @param {number} tileHeight - Tile height in pixels.
 * @param {DOMRect} stageRect - Thread Explorer stage rectangle.
 * @param {HTMLElement[]} cards - Rendered post card elements.
 * @param {Map<string, HTMLImageElement>} avatarImages - Preloaded cached avatars for canvas drawing.
 * @param {Map<string, HTMLImageElement>} mediaImages - Preloaded canvas-safe media images.
 * @returns {HTMLCanvasElement} Rendered tile canvas.
 */
function renderThreadExplorerSnapshotTile(tileX, tileY, tileWidth, tileHeight, stageRect, cards, avatarImages = new Map(), mediaImages = new Map()) {
  const canvas = document.createElement("canvas");
  canvas.width = tileWidth;
  canvas.height = tileHeight;
  const context = canvas.getContext("2d");
  context.fillStyle = getThreadExplorerSnapshotBackgroundColor();
  context.fillRect(0, 0, tileWidth, tileHeight);
  context.save();
  context.translate(-tileX, -tileY);
  drawThreadExplorerSnapshotEdges(context);
  cards.forEach((card) => {
    drawThreadExplorerSnapshotCard(context, card, stageRect, avatarImages, mediaImages);
  });
  context.restore();
  return canvas;
}

/**
 * Draws a circular fallback avatar into a snapshot canvas.
 * @param {CanvasRenderingContext2D} context - Target canvas context.
 * @param {number} x - Avatar left coordinate.
 * @param {number} y - Avatar top coordinate.
 * @param {number} size - Avatar diameter.
 * @returns {void}
 */
function drawThreadExplorerSnapshotFallbackAvatar(context, x, y, size) {
  const center = size / 2;
  context.fillStyle = "#0070ff";
  context.beginPath();
  context.arc(x + center, y + center, center, 0, Math.PI * 2);
  context.fill();
  context.fillStyle = "#ffffff";
  context.beginPath();
  context.arc(x + center, y + (size * 0.4), size * 0.18, 0, Math.PI * 2);
  context.fill();
  context.beginPath();
  context.arc(x + center, y + (size * 0.78), size * 0.28, Math.PI, 0, true);
  context.fill();
}

/**
 * Checks whether an image URL can be drawn without tainting the snapshot canvas.
 * @param {HTMLImageElement|null} image - Candidate image element.
 * @returns {boolean} True when the image source is same-origin or local data.
 */
function canDrawThreadExplorerSnapshotImage(image) {
  const source = String(image?.currentSrc || image?.src || "").trim();
  if (!source) {
    return false;
  }
  if (source.startsWith("data:") || source.startsWith("blob:")) {
    return true;
  }
  try {
    return new URL(source, window.location.href).origin === window.location.origin;
  } catch {
    return false;
  }
}

/**
 * Draws a circular avatar image into a snapshot canvas when the image can be used safely.
 * @param {CanvasRenderingContext2D} context - Target canvas context.
 * @param {HTMLImageElement|null} image - Rendered avatar image element.
 * @param {number} x - Avatar left coordinate.
 * @param {number} y - Avatar top coordinate.
 * @param {number} size - Avatar diameter.
 * @returns {boolean} True when a real avatar was drawn.
 */
function drawThreadExplorerSnapshotAvatarImage(context, image, x, y, size) {
  if (!canDrawThreadExplorerSnapshotImage(image)) {
    return false;
  }
  if (!image || !image.complete || !image.naturalWidth || !image.naturalHeight) {
    return false;
  }

  try {
    const scale = Math.max(size / image.naturalWidth, size / image.naturalHeight);
    const drawWidth = image.naturalWidth * scale;
    const drawHeight = image.naturalHeight * scale;
    const offsetX = x + ((size - drawWidth) / 2);
    const offsetY = y + ((size - drawHeight) / 2);
    context.save();
    context.beginPath();
    context.arc(x + (size / 2), y + (size / 2), size / 2, 0, Math.PI * 2);
    context.clip();
    context.drawImage(image, offsetX, offsetY, drawWidth, drawHeight);
    context.restore();
    return true;
  } catch {
    return false;
  }
}

/**
 * Draws an image inside a rounded rectangle using cover behavior.
 * @param {CanvasRenderingContext2D} context - Target canvas context.
 * @param {HTMLImageElement|null} image - Loaded image to draw.
 * @param {number} x - Left coordinate.
 * @param {number} y - Top coordinate.
 * @param {number} width - Target width.
 * @param {number} height - Target height.
 * @param {number} radius - Clip radius.
 * @returns {boolean} True when an image was drawn.
 */
function drawThreadExplorerSnapshotCoverImage(context, image, x, y, width, height, radius = 6) {
  if (!image || !image.complete || !image.naturalWidth || !image.naturalHeight) {
    return false;
  }

  try {
    const scale = Math.max(width / image.naturalWidth, height / image.naturalHeight);
    const drawWidth = image.naturalWidth * scale;
    const drawHeight = image.naturalHeight * scale;
    const offsetX = x + ((width - drawWidth) / 2);
    const offsetY = y + ((height - drawHeight) / 2);
    context.save();
    drawThreadExplorerSnapshotRoundRect(context, x, y, width, height, radius);
    context.clip();
    context.drawImage(image, offsetX, offsetY, drawWidth, drawHeight);
    context.restore();
    return true;
  } catch {
    return false;
  }
}

/**
 * Draws a lightweight placeholder for a media image that cannot be painted into canvas.
 * @param {CanvasRenderingContext2D} context - Target canvas context.
 * @param {DOMRect} rect - Media rectangle in snapshot coordinates.
 * @returns {void}
 */
function drawThreadExplorerSnapshotMediaPlaceholder(context, rect) {
  context.save();
  drawThreadExplorerSnapshotRoundRect(context, rect.left, rect.top, rect.width, rect.height, 6);
  context.fillStyle = "#dfe8f7";
  context.fill();
  context.strokeStyle = "#c9d8ee";
  context.lineWidth = 1;
  context.stroke();
  context.restore();
}

/**
 * Draws a compact ALT text overlay for one snapshot media image.
 * @param {CanvasRenderingContext2D} context - Target canvas context.
 * @param {string} altText - Image ALT text.
 * @param {DOMRect} rect - Media rectangle in snapshot coordinates.
 * @param {number} maxBottom - Lowest y-coordinate the ALT text block may use.
 * @returns {void}
 */
function drawThreadExplorerSnapshotImageAltText(context, altText, rect, maxBottom = 0) {
  const normalizedAlt = String(altText || "").replace(/\s+/g, " ").trim();
  if (!normalizedAlt) {
    return;
  }

  const paddingX = 8;
  const paddingY = 6;
  const lineHeight = 13;
  const labelTop = rect.bottom + 4;
  let maxLines = 3;
  if (maxBottom > labelTop) {
    const availableHeight = Math.max(0, maxBottom - labelTop);
    maxLines = Math.floor((availableHeight - (paddingY * 2)) / lineHeight);
    maxLines = Math.min(12, Math.max(1, maxLines));
  } else {
    if (rect.height < 96) {
      maxLines = 2;
    }
    if (rect.height < 52) {
      maxLines = 1;
    }
  }

  const label = `${t("archivePdfAltPrefix")} ${normalizedAlt}`;
  context.save();
  context.font = "11px Segoe UI, Arial, sans-serif";
  const lines = wrapThreadExplorerSnapshotText(context, label, Math.max(40, rect.width - (paddingX * 2)), maxLines);
  if (lines.length === 0) {
    context.restore();
    return;
  }

  const labelHeight = (paddingY * 2) + (lines.length * lineHeight);
  drawThreadExplorerSnapshotRoundRect(context, rect.left, labelTop, rect.width, labelHeight, 6);
  context.fillStyle = "#eef5ff";
  context.fill();
  context.strokeStyle = "#c9d8ee";
  context.lineWidth = 1;
  context.stroke();
  context.fillStyle = "#345070";
  drawThreadExplorerSnapshotTextBlock(context, lines, rect.left + paddingX, labelTop + paddingY + 9, lineHeight);
  context.restore();
}

/**
 * Draws all visible media images inside a Thread Explorer card at their rendered positions.
 * @param {CanvasRenderingContext2D} context - Target canvas context.
 * @param {HTMLElement} card - Rendered post card.
 * @param {DOMRect} stageRect - Thread Explorer stage rectangle.
 * @param {Map<string, HTMLImageElement>} mediaImages - Preloaded canvas-safe media images.
 * @param {number} altTextMaxBottom - Lowest y-coordinate ALT text blocks may use.
 * @returns {void}
 */
function drawThreadExplorerSnapshotMediaImages(context, card, stageRect, mediaImages = new Map(), altTextMaxBottom = 0) {
  const images = Array.from(card.querySelectorAll("img"));
  images.forEach((image) => {
    if (!isThreadExplorerSnapshotMediaImage(image)) {
      return;
    }

    const imageRect = getThreadExplorerStageRect(image, stageRect);
    if (imageRect.width <= 0 || imageRect.height <= 0) {
      return;
    }

    const drawableImage = getThreadExplorerSnapshotDrawableMediaImage(image, mediaImages);

    const wasDrawn = drawThreadExplorerSnapshotCoverImage(context, drawableImage, imageRect.left, imageRect.top, imageRect.width, imageRect.height, 6);
    if (!wasDrawn) {
      drawThreadExplorerSnapshotMediaPlaceholder(context, imageRect);
    }
    strokeThreadExplorerSnapshotRoundRect(context, imageRect.left, imageRect.top, imageRect.width, imageRect.height, 6, "#d6e2f2", 1);
    drawThreadExplorerSnapshotImageAltText(context, image.alt || "", imageRect, altTextMaxBottom);
  });
}

/**
 * Builds a readable counts line from rendered Thread Explorer count elements.
 * @param {HTMLElement} card - Rendered post card.
 * @returns {string} Snapshot-ready count summary with explicit spacing.
 */
function getThreadExplorerSnapshotCountsText(card) {
  const container = card.querySelector(".thread-explorer-post-counts");
  if (!container) {
    return "";
  }

  const parts = [];
  Array.from(container.children).forEach((child) => {
    const text = String(child.textContent || "").replace(/\s+/g, " ").trim();
    if (text) {
      parts.push(text);
    }
  });
  return parts.join("   ");
}

/**
 * Creates the standard error used when a Thread Explorer snapshot export is cancelled.
 * @returns {Error} Cancel error.
 */
function createThreadExplorerSnapshotAbortError() {
  const error = new Error(t("threadExplorerSnapshotCancelled"));
  error.name = "AbortError";
  return error;
}

/**
 * Throws when the current Thread Explorer snapshot export was cancelled.
 * @param {AbortSignal|null} signal - Abort signal for the current export.
 * @returns {void}
 */
function throwIfThreadExplorerSnapshotAborted(signal = null) {
  if (signal?.aborted) {
    throw createThreadExplorerSnapshotAbortError();
  }
}

/**
 * Creates the standard error used when a media ZIP export is cancelled.
 * @returns {Error} Cancel error.
 */
function createMediaExportAbortError() {
  const error = new Error(t("archiveMediaCancelled"));
  error.name = "AbortError";
  return error;
}

/**
 * Throws when the current media ZIP export was cancelled.
 * @param {AbortSignal|null} signal - Abort signal for the current export.
 * @returns {void}
 */
function throwIfMediaExportAborted(signal = null) {
  if (signal?.aborted) {
    throw createMediaExportAbortError();
  }
}

/**
 * Keeps Snapshot progress values inside the visible 0-100 percent range.
 * @param {number} value - Raw progress value.
 * @returns {number} Integer progress value between 0 and 100.
 */
function clampThreadExplorerSnapshotProgress(value) {
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue)) {
    return 0;
  }
  if (numericValue < 0) {
    return 0;
  }
  if (numericValue > 100) {
    return 100;
  }
  return Math.round(numericValue);
}

/**
 * Waits until the browser has had time to paint progress updates.
 * @returns {Promise<void>} Resolves after two animation frames.
 */
function waitForThreadExplorerSnapshotFrame() {
  return new Promise((resolve) => {
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(resolve);
    });
  });
}

/**
 * Updates the modal Snapshot progress UI.
 * @param {{percent?: number, step?: string, detail?: string, title?: string}} progress - Progress state to render.
 * @returns {void}
 */
function updateThreadExplorerSnapshotProgress(progress = {}) {
  const percent = clampThreadExplorerSnapshotProgress(progress.percent);
  if (threadExplorerSnapshotProgressTitle) {
    if (progress.title) {
      threadExplorerSnapshotProgressTitle.textContent = progress.title;
    } else {
      threadExplorerSnapshotProgressTitle.textContent = t("threadExplorerSnapshotProgressTitle");
    }
  }
  if (threadExplorerSnapshotProgressStep) {
    threadExplorerSnapshotProgressStep.textContent = progress.step || "";
  }
  if (threadExplorerSnapshotProgressDetail) {
    threadExplorerSnapshotProgressDetail.textContent = progress.detail || `${percent}%`;
  }
  if (threadExplorerSnapshotProgressFill) {
    threadExplorerSnapshotProgressFill.style.width = `${percent}%`;
  }
  if (threadExplorerSnapshotProgressBar) {
    threadExplorerSnapshotProgressBar.setAttribute("aria-valuenow", String(percent));
    threadExplorerSnapshotProgressBar.setAttribute("aria-label", `${percent}%`);
  }
}

/**
 * Shows the blocking Snapshot progress dialog.
 * @param {{percent?: number, step?: string, detail?: string, title?: string}} progress - Initial progress state.
 * @returns {void}
 */
function openThreadExplorerSnapshotProgress(progress = {}) {
  updateThreadExplorerSnapshotProgress(progress);
  if (threadExplorerSnapshotProgressDialog && !threadExplorerSnapshotProgressDialog.open) {
    threadExplorerSnapshotProgressDialog.showModal();
  }
}

/**
 * Hides the blocking Snapshot progress dialog.
 * @returns {void}
 */
function closeThreadExplorerSnapshotProgress() {
  if (threadExplorerSnapshotProgressDialog && threadExplorerSnapshotProgressDialog.open) {
    threadExplorerSnapshotProgressDialog.close();
  }
}

/**
 * Creates an awaited progress reporter for long Snapshot export phases.
 * @param {AbortSignal|null} signal - Abort signal for the current export.
 * @returns {(progress: {percent?: number, step?: string, detail?: string, title?: string}) => Promise<void>} Progress reporter.
 */
function createThreadExplorerSnapshotProgressReporter(signal = null) {
  return async (progress = {}) => {
    throwIfThreadExplorerSnapshotAborted(signal);
    updateThreadExplorerSnapshotProgress(progress);
    await waitForThreadExplorerSnapshotFrame();
    throwIfThreadExplorerSnapshotAborted(signal);
  };
}

/**
 * Renders a full-resolution PNG through small canvas tiles and an assembled PNG stream.
 * @param {number} width - Snapshot width in pixels.
 * @param {number} height - Snapshot height in pixels.
 * @param {(progress: {percent?: number, step?: string, detail?: string}) => Promise<void>} onProgress - Progress reporter.
 * @param {AbortSignal|null} signal - Abort signal for the current export.
 * @returns {Promise<Blob>} Lossless PNG blob.
 */
async function renderThreadExplorerTiledPngSnapshotBlob(width, height, onProgress = async () => {}, signal = null) {
  throwIfThreadExplorerSnapshotAborted(signal);
  const crcTable = createThreadExplorerPngCrcTable();
  const parts = [];
  const signature = new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]);
  parts.push(signature);
  parts.push(createThreadExplorerPngChunk("IHDR", createThreadExplorerPngHeaderData(width, height), crcTable));
  parts.push(...createThreadExplorerPngMetadataChunks(crcTable));

  if (typeof CompressionStream !== "function") {
    throw new Error("CompressionStream is not available.");
  }
  const compressionStream = new CompressionStream("deflate");
  const compressionWriter = compressionStream.writable.getWriter();
  const compressedBytesPromise = new Response(compressionStream.readable).arrayBuffer();
  const stageRect = threadExplorerThreadStage.getBoundingClientRect();
  const cards = Array.from(threadExplorerThreadStage.querySelectorAll(".thread-explorer-post-card"));
  await onProgress({
    percent: 54,
    step: t("threadExplorerSnapshotProgressAvatars"),
    detail: t("threadExplorerSnapshotProgressPostCount", { count: cards.length }),
  });
  const avatarImages = await preloadThreadExplorerSnapshotAvatarImages(cards);
  throwIfThreadExplorerSnapshotAborted(signal);
  await onProgress({
    percent: 58,
    step: t("threadExplorerSnapshotProgressMedia"),
    detail: t("threadExplorerSnapshotProgressPostCount", { count: cards.length }),
  });
  const mediaImages = await preloadThreadExplorerSnapshotMediaImages(cards);
  throwIfThreadExplorerSnapshotAborted(signal);
  const tileRows = Math.max(1, Math.ceil(height / THREAD_EXPLORER_SNAPSHOT_TILE_SIZE));
  let tileRow = 0;

  for (let tileY = 0; tileY < height; tileY += THREAD_EXPLORER_SNAPSHOT_TILE_SIZE) {
    throwIfThreadExplorerSnapshotAborted(signal);
    tileRow += 1;
    const tilePercent = 60 + ((tileRow - 1) / tileRows * 32);
    await onProgress({
      percent: tilePercent,
      step: t("threadExplorerSnapshotProgressRenderTiles"),
      detail: t("threadExplorerSnapshotProgressRenderTileDetail", { row: tileRow, rows: tileRows }),
    });
    const tileHeight = Math.min(THREAD_EXPLORER_SNAPSHOT_TILE_SIZE, height - tileY);
    const rowTiles = [];
    for (let tileX = 0; tileX < width; tileX += THREAD_EXPLORER_SNAPSHOT_TILE_SIZE) {
      const tileWidth = Math.min(THREAD_EXPLORER_SNAPSHOT_TILE_SIZE, width - tileX);
      const tileCanvas = renderThreadExplorerSnapshotTile(tileX, tileY, tileWidth, tileHeight, stageRect, cards, avatarImages, mediaImages);
      const tileContext = tileCanvas.getContext("2d");
      rowTiles.push({
        x: tileX,
        width: tileWidth,
        data: tileContext.getImageData(0, 0, tileWidth, tileHeight).data,
      });
      await new Promise((resolve) => window.requestAnimationFrame(resolve));
    }

    for (let row = 0; row < tileHeight; row += 1) {
      const scanline = new Uint8Array((width * 4) + 1);
      scanline[0] = 0;
      rowTiles.forEach((tile) => {
        const sourceOffset = row * tile.width * 4;
        const targetOffset = 1 + (tile.x * 4);
        scanline.set(tile.data.subarray(sourceOffset, sourceOffset + (tile.width * 4)), targetOffset);
      });
      await compressionWriter.write(scanline);
    }
  }

  throwIfThreadExplorerSnapshotAborted(signal);
  await onProgress({
    percent: 94,
    step: t("threadExplorerSnapshotProgressEncode"),
    detail: t("threadExplorerSnapshotProgressRenderTileDetail", { row: tileRows, rows: tileRows }),
  });
  await compressionWriter.close();
  const compressedScanlines = new Uint8Array(await compressedBytesPromise);
  parts.push(createThreadExplorerPngChunk("IDAT", compressedScanlines, crcTable));
  parts.push(createThreadExplorerPngChunk("IEND", new Uint8Array(0), crcTable));
  return new Blob(parts, { type: "image/png" });
}

/**
 * Checks whether PNG export should avoid one large canvas.
 * @param {number} width - Snapshot width in pixels.
 * @param {number} height - Snapshot height in pixels.
 * @returns {boolean} True when tiled PNG assembly is safer.
 */
function shouldUseThreadExplorerTiledPngSnapshot(width, height) {
  if (width > THREAD_EXPLORER_SNAPSHOT_MAX_CANVAS_DIMENSION) {
    return true;
  }
  if (height > THREAD_EXPLORER_SNAPSHOT_MAX_CANVAS_DIMENSION) {
    return true;
  }
  if ((width * height) > THREAD_EXPLORER_SNAPSHOT_MAX_CANVAS_PIXELS) {
    return true;
  }
  return false;
}

/**
 * Draws Thread Explorer SVG edge paths on a snapshot canvas.
 * @param {CanvasRenderingContext2D} context - Target canvas context.
 * @returns {void}
 */
function drawThreadExplorerSnapshotEdges(context) {
  const edges = Array.from(threadExplorerThreadStage.querySelectorAll(".thread-explorer-edge"));
  edges.forEach((edge) => {
    const data = String(edge.getAttribute("d") || "").trim();
    if (!data) {
      return;
    }
    try {
      context.save();
      context.strokeStyle = getComputedStyle(edge).stroke || "#b8cce8";
      context.lineWidth = Number.parseFloat(getComputedStyle(edge).strokeWidth) || 2;
      context.lineCap = "round";
      context.stroke(new Path2D(data));
      context.restore();
    } catch {
      // Ignore malformed paths in fallback renderer.
    }
  });
}

/**
 * Draws one rendered Thread Explorer card into the fallback snapshot canvas.
 * @param {CanvasRenderingContext2D} context - Target canvas context.
 * @param {HTMLElement} card - Rendered post card.
 * @param {DOMRect} stageRect - Thread Explorer stage rectangle.
 * @param {Map<string, HTMLImageElement>} avatarImages - Preloaded cached avatars for canvas drawing.
 * @param {Map<string, HTMLImageElement>} mediaImages - Preloaded canvas-safe media images.
 * @returns {void}
 */
function drawThreadExplorerSnapshotCard(context, card, stageRect, avatarImages = new Map(), mediaImages = new Map()) {
  const rect = getThreadExplorerStageRect(card, stageRect);
  const computed = getComputedStyle(card);
  context.save();
  drawThreadExplorerSnapshotRoundRect(context, rect.left, rect.top, rect.width, rect.height, 8);
  context.fillStyle = computed.backgroundColor || "#ffffff";
  context.fill();
  context.strokeStyle = computed.borderColor || "#d8e3f2";
  context.lineWidth = 1.5;
  context.stroke();

  const avatarX = rect.left + 16;
  const avatarY = rect.top + 16;
  const avatar = card.querySelector(".thread-explorer-avatar");
  const avatarKey = getThreadExplorerSnapshotAvatarCacheKey(avatar);
  let avatarImage = null;
  if (avatarKey && avatarImages.has(avatarKey)) {
    avatarImage = avatarImages.get(avatarKey);
  } else {
    avatarImage = avatar;
  }
  const avatarWasDrawn = drawThreadExplorerSnapshotAvatarImage(context, avatarImage, avatarX, avatarY, 40);
  if (!avatarWasDrawn) {
    drawThreadExplorerSnapshotFallbackAvatar(context, avatarX, avatarY, 40);
  }

  const textX = rect.left + 66;
  const textWidth = Math.max(80, rect.width - 86);
  let y = rect.top + 28;
  const author = card.querySelector(".thread-explorer-post-author")?.textContent || "";
  const handle = card.querySelector(".thread-explorer-post-handle")?.textContent || "";
  const meta = card.querySelector(".thread-explorer-post-meta")?.textContent || "";
  const body = card.querySelector(".thread-explorer-post-text")?.textContent || "";
  const counts = getThreadExplorerSnapshotCountsText(card);
  const editMarker = card.querySelector(".thread-explorer-edit-button:not([hidden])")?.textContent || "";
  const countsElement = card.querySelector(".thread-explorer-post-counts");
  let altTextMaxBottom = rect.bottom - 20;
  if (countsElement) {
    const countsRect = getThreadExplorerStageRect(countsElement, stageRect);
    if (countsRect.top > rect.top) {
      altTextMaxBottom = countsRect.top - 8;
    }
  }

  context.fillStyle = "#14233d";
  context.font = "700 16px Segoe UI, Arial, sans-serif";
  drawThreadExplorerSnapshotTextBlock(context, wrapThreadExplorerSnapshotText(context, author, textWidth, 1), textX, y, 18);
  y += 18;
  context.fillStyle = "#5d7394";
  context.font = "13px Segoe UI, Arial, sans-serif";
  drawThreadExplorerSnapshotTextBlock(context, wrapThreadExplorerSnapshotText(context, handle, textWidth, 1), textX, y, 16);
  y += 26;
  if (meta) {
    drawThreadExplorerSnapshotTextBlock(context, wrapThreadExplorerSnapshotText(context, meta, textWidth, 1), rect.left + 16, y, 16);
    y += 24;
  }
  if (editMarker) {
    context.fillStyle = "#92560d";
    context.font = "700 12px Segoe UI, Arial, sans-serif";
    y = drawThreadExplorerSnapshotTextBlock(context, wrapThreadExplorerSnapshotText(context, editMarker, rect.width - 32, 1), rect.left + 16, y, 15);
    y += 8;
  }

  context.fillStyle = "#1e3150";
  context.font = "14px Segoe UI, Arial, sans-serif";
  y = drawThreadExplorerSnapshotTextBlock(context, wrapThreadExplorerSnapshotText(context, body, rect.width - 32, 10), rect.left + 16, y, 19);
  drawThreadExplorerSnapshotMediaImages(context, card, stageRect, mediaImages, altTextMaxBottom);
  if (counts) {
    context.fillStyle = "#5d7394";
    context.font = "12px Segoe UI, Arial, sans-serif";
    const countLines = wrapThreadExplorerSnapshotText(context, counts, rect.width - 32, 2);
    const countY = rect.bottom - 16 - ((countLines.length - 1) * 15);
    drawThreadExplorerSnapshotTextBlock(context, countLines, rect.left + 16, countY, 15);
  }
  context.restore();
}

/**
 * Renders the complete Thread Explorer tree directly to canvas as a robust fallback.
 * @param {string} mimeType - Target image MIME type.
 * @param {number} width - Snapshot width.
 * @param {number} height - Snapshot height.
 * @param {(progress: {percent?: number, step?: string, detail?: string}) => Promise<void>} onProgress - Progress reporter.
 * @param {AbortSignal|null} signal - Abort signal for the current export.
 * @returns {Promise<Blob>} Image blob.
 */
async function renderThreadExplorerCanvasSnapshotBlob(mimeType, width, height, onProgress = async () => {}, signal = null) {
  throwIfThreadExplorerSnapshotAborted(signal);
  const snapshot = createThreadExplorerSnapshotCanvas(width, height);
  const stageRect = threadExplorerThreadStage.getBoundingClientRect();
  await onProgress({
    percent: 64,
    step: t("threadExplorerSnapshotProgressRenderCanvas"),
    detail: t("threadExplorerSnapshotProgressEdges"),
  });
  drawThreadExplorerSnapshotEdges(snapshot.context);
  const cards = Array.from(threadExplorerThreadStage.querySelectorAll(".thread-explorer-post-card"));
  await onProgress({
    percent: 68,
    step: t("threadExplorerSnapshotProgressAvatars"),
    detail: t("threadExplorerSnapshotProgressPostCount", { count: cards.length }),
  });
  const avatarImages = await preloadThreadExplorerSnapshotAvatarImages(cards);
  throwIfThreadExplorerSnapshotAborted(signal);
  await onProgress({
    percent: 72,
    step: t("threadExplorerSnapshotProgressMedia"),
    detail: t("threadExplorerSnapshotProgressPostCount", { count: cards.length }),
  });
  const mediaImages = await preloadThreadExplorerSnapshotMediaImages(cards);
  throwIfThreadExplorerSnapshotAborted(signal);
  const totalCards = Math.max(1, cards.length);
  for (let index = 0; index < cards.length; index += 1) {
    throwIfThreadExplorerSnapshotAborted(signal);
    drawThreadExplorerSnapshotCard(snapshot.context, cards[index], stageRect, avatarImages, mediaImages);
    if ((index % 10) === 0) {
      const percent = 74 + (index / totalCards * 18);
      await onProgress({
        percent,
        step: t("threadExplorerSnapshotProgressRenderCanvas"),
        detail: t("threadExplorerSnapshotProgressRenderCardDetail", { index: index + 1, count: cards.length }),
      });
    }
  }
  throwIfThreadExplorerSnapshotAborted(signal);
  await onProgress({
    percent: 94,
    step: t("threadExplorerSnapshotProgressEncode"),
    detail: t("threadExplorerSnapshotProgressRenderCardDetail", { index: cards.length, count: cards.length }),
  });
  return encodeThreadExplorerSnapshotCanvas(snapshot.canvas, mimeType);
}

/**
 * Renders the complete Thread Explorer tree through SVG foreignObject.
 * @param {string} mimeType - Target image MIME type.
 * @param {number} width - Snapshot width.
 * @param {number} height - Snapshot height.
 * @param {(progress: {percent?: number, step?: string, detail?: string}) => Promise<void>} onProgress - Progress reporter.
 * @param {AbortSignal|null} signal - Abort signal for the current export.
 * @returns {Promise<Blob>} Image blob.
 */
async function renderThreadExplorerForeignObjectSnapshotBlob(mimeType, width, height, onProgress = async () => {}, signal = null) {
  throwIfThreadExplorerSnapshotAborted(signal);
  const sourceStage = threadExplorerThreadStage;
  await onProgress({
    percent: 62,
    step: t("threadExplorerSnapshotProgressRenderSvg"),
    detail: t("threadExplorerSnapshotProgressClone"),
  });
  const clone = sourceStage.cloneNode(true);
  clone.style.setProperty("--thread-explorer-zoom", "1");
  clone.style.setProperty("--thread-explorer-pan-x", "0px");
  clone.style.setProperty("--thread-explorer-pan-y", "0px");
  clone.style.width = `${width}px`;
  clone.style.minWidth = `${width}px`;
  clone.style.height = `${height}px`;
  clone.style.padding = getComputedStyle(sourceStage).padding;
  inlineThreadExplorerSnapshotImages(sourceStage, clone);

  const css = collectThreadExplorerSnapshotCss();
  const html = `
    <div xmlns="http://www.w3.org/1999/xhtml">
      <style>${css}</style>
      ${clone.outerHTML}
    </div>
  `;
  const svg = `
    <svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
      <foreignObject width="100%" height="100%">${html}</foreignObject>
    </svg>
  `;
  const svgBlob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" });
  const svgUrl = URL.createObjectURL(svgBlob);
  try {
    const image = new Image();
    throwIfThreadExplorerSnapshotAborted(signal);
    await onProgress({
      percent: 76,
      step: t("threadExplorerSnapshotProgressRenderSvg"),
      detail: t("threadExplorerSnapshotProgressBrowserImage"),
    });
    await new Promise((resolve, reject) => {
      const handleAbort = () => {
        reject(createThreadExplorerSnapshotAbortError());
      };
      const cleanup = () => {
        image.removeEventListener("load", handleLoad);
        image.removeEventListener("error", handleError);
        if (signal) {
          signal.removeEventListener("abort", handleAbort);
        }
      };
      const handleLoad = () => {
        cleanup();
        resolve();
      };
      const handleError = () => {
        cleanup();
        const error = new Error("foreignObject snapshot failed");
        error.name = "ThreadExplorerSnapshotFallbackError";
        reject(error);
      };
      image.addEventListener("load", handleLoad, { once: true });
      image.addEventListener("error", handleError, { once: true });
      if (signal) {
        signal.addEventListener("abort", handleAbort, { once: true });
      }
      image.src = svgUrl;
    });

    throwIfThreadExplorerSnapshotAborted(signal);
    await onProgress({
      percent: 88,
      step: t("threadExplorerSnapshotProgressRenderSvg"),
      detail: t("threadExplorerSnapshotProgressEncode"),
    });
    const snapshot = createThreadExplorerSnapshotCanvas(width, height);
    snapshot.context.drawImage(image, 0, 0);
    return encodeThreadExplorerSnapshotCanvas(snapshot.canvas, mimeType);
  } finally {
    URL.revokeObjectURL(svgUrl);
  }
}

/**
 * Renders the complete Thread Explorer tree as an image blob.
 * @param {string} mimeType - Target image MIME type.
 * @param {(progress: {percent?: number, step?: string, detail?: string}) => Promise<void>} onProgress - Progress reporter.
 * @param {AbortSignal|null} signal - Abort signal for the current export.
 * @returns {Promise<Blob>} Image blob.
 */
async function renderThreadExplorerSnapshotBlob(mimeType = "image/png", onProgress = async () => {}, signal = null) {
  if (!threadExplorerTree) {
    throw new Error(t("threadExplorerSnapshotNoThread"));
  }
  throwIfThreadExplorerSnapshotAborted(signal);

  await onProgress({
    percent: 4,
    step: t("threadExplorerSnapshotProgressPreparing"),
    detail: t("threadExplorerSnapshotProgressPreparingDetail"),
  });
  await hydrateThreadExplorerTreeAvatars(threadExplorerTree, onProgress, signal);
  throwIfThreadExplorerSnapshotAborted(signal);
  await onProgress({
    percent: 18,
    step: t("threadExplorerSnapshotProgressMedia"),
    detail: t("threadExplorerSnapshotProgressMediaDetail"),
  });
  await hydrateThreadExplorerSnapshotMedia(threadExplorerTree, onProgress, signal);
  throwIfThreadExplorerSnapshotAborted(signal);
  await onProgress({
    percent: 28,
    step: t("threadExplorerSnapshotProgressAvatars"),
    detail: t("threadExplorerSnapshotProgressCacheDetail"),
  });
  await restoreAccountAvatarCache();
  applyThreadExplorerAvatarCacheToTree(threadExplorerTree);
  throwIfThreadExplorerSnapshotAborted(signal);
  await onProgress({
    percent: 36,
    step: t("threadExplorerSnapshotProgressRenderTree"),
    detail: t("threadExplorerSnapshotProgressRenderTreeDetail"),
  });
  threadExplorerForceHydrateCards = true;
  try {
    renderThreadExplorerTree();
  } finally {
    threadExplorerForceHydrateCards = false;
  }
  const inspectedMediaCount = cacheLoadedThreadExplorerRenderedMediaImages();
  await onProgress({
    percent: 37,
    step: t("threadExplorerSnapshotProgressMedia"),
    detail: t("threadExplorerSnapshotProgressRenderedCacheDetail", { count: inspectedMediaCount }),
  });
  const hydratedMediaCounts = await applyThreadExplorerSnapshotMediaDataUrisToRenderedTree(onProgress, signal);
  await onProgress({
    percent: 40,
    step: t("threadExplorerSnapshotProgressMedia"),
    detail: t("threadExplorerSnapshotProgressHydratedMediaDetail", {
      count: hydratedMediaCounts.embedded,
      missing: hydratedMediaCounts.missing,
      total: hydratedMediaCounts.total,
    }),
  });
  throwIfThreadExplorerSnapshotAborted(signal);
  await onProgress({
    percent: 44,
    step: t("threadExplorerSnapshotProgressBrowserFrame"),
    detail: t("threadExplorerSnapshotProgressBrowserFrameDetail"),
  });
  await waitForThreadExplorerSnapshotFrame();

  const sourceStage = threadExplorerThreadStage;
  await onProgress({
    percent: 50,
    step: t("threadExplorerSnapshotProgressMeasure"),
    detail: t("threadExplorerSnapshotProgressMeasureDetail"),
  });
  const width = Math.ceil(Math.max(sourceStage.scrollWidth, sourceStage.offsetWidth, sourceStage.getBoundingClientRect().width));
  const height = Math.ceil(Math.max(sourceStage.scrollHeight, sourceStage.offsetHeight, sourceStage.getBoundingClientRect().height));
  if (!width || !height) {
    throw new Error(t("threadExplorerSnapshotFailed"));
  }

  if (mimeType === "image/png" && shouldUseThreadExplorerTiledPngSnapshot(width, height)) {
    try {
      return await renderThreadExplorerTiledPngSnapshotBlob(width, height, onProgress, signal);
    } catch (error) {
      console.warn("Thread Explorer tiled PNG snapshot failed; using scaled fallback.", error);
      await onProgress({
        percent: 58,
        step: t("threadExplorerSnapshotProgressFallback"),
        detail: t("threadExplorerSnapshotProgressFallbackDetail"),
      });
    }
  }

  try {
    return await renderThreadExplorerForeignObjectSnapshotBlob(mimeType, width, height, onProgress, signal);
  } catch (error) {
    if (error?.name === "ThreadExplorerSnapshotFallbackError") {
      console.info("Thread Explorer foreignObject snapshot was not supported for this tree; using canvas fallback.");
    } else {
      console.warn("Thread Explorer foreignObject snapshot failed; using canvas fallback.", error);
    }
    await onProgress({
      percent: 58,
      step: t("threadExplorerSnapshotProgressFallback"),
      detail: t("threadExplorerSnapshotProgressFallbackDetail"),
    });
    return renderThreadExplorerCanvasSnapshotBlob(mimeType, width, height, onProgress, signal);
  }
}

/**
 * Downloads the complete Thread Explorer tree as a PNG snapshot.
 * @returns {Promise<void>} Resolves after the browser download was triggered.
 */
async function downloadThreadExplorerSnapshot() {
  threadExplorerSnapshotAbortController = new AbortController();
  const snapshotSignal = threadExplorerSnapshotAbortController.signal;
  const reportProgress = createThreadExplorerSnapshotProgressReporter(snapshotSignal);
  try {
    threadExplorerSnapshotPngButton.disabled = true;
    if (threadExplorerSnapshotCancelButton) {
      threadExplorerSnapshotCancelButton.disabled = false;
    }
    threadExplorerSnapshotPngButton.textContent = t("threadExplorerSnapshotBusy");
    openThreadExplorerSnapshotProgress({
      percent: 0,
      step: t("threadExplorerSnapshotProgressPreparing"),
      detail: t("threadExplorerSnapshotProgressPreparingDetail"),
    });
    await reportProgress({
      percent: 1,
      step: t("threadExplorerSnapshotProgressPreparing"),
      detail: t("threadExplorerSnapshotProgressPreparingDetail"),
    });
    const blob = await renderThreadExplorerSnapshotBlob("image/png", reportProgress, snapshotSignal);
    const fileName = buildThreadExplorerSnapshotFileName("png");
    await reportProgress({
      percent: 97,
      step: t("threadExplorerSnapshotProgressDownload"),
      detail: fileName,
    });
    downloadThreadExplorerBlob(blob, fileName);
    await reportProgress({
      percent: 100,
      step: t("threadExplorerSnapshotProgressDone"),
      detail: fileName,
    });
    await new Promise((resolve) => window.setTimeout(resolve, 260));
  } catch (error) {
    if (error?.name === "AbortError") {
      threadExplorerThreadStatus.textContent = t("threadExplorerSnapshotCancelled");
    } else {
      console.error(error);
      threadExplorerThreadStatus.textContent = error.message || t("threadExplorerSnapshotFailed");
    }
  } finally {
    if (threadExplorerSnapshotCancelButton) {
      threadExplorerSnapshotCancelButton.disabled = true;
    }
    threadExplorerSnapshotAbortController = null;
    closeThreadExplorerSnapshotProgress();
    threadExplorerSnapshotPngButton.textContent = t("threadExplorerSnapshotPngButton");
    updateThreadExplorerControls();
  }
}

/**
 * Cancels the currently running Thread Explorer PNG snapshot export.
 * @returns {void}
 */
function cancelThreadExplorerSnapshotExport() {
  if (!threadExplorerSnapshotAbortController) {
    return;
  }
  threadExplorerSnapshotAbortController.abort();
  updateThreadExplorerSnapshotProgress({
    percent: 100,
    step: t("threadExplorerSnapshotCancelled"),
    detail: t("threadExplorerSnapshotCancelledDetail"),
  });
}

